const UMA_F64_ASSIGN_M0_GATE_MIN_NODES: usize = 6000;
#[allow(dead_code)]
const UMA_F32_ATOMWISE_BLAS_GATE_MIN_ATOMS: usize = 16;
#[cfg(feature = "parallel")]
const UMA_F32_DIRECT_CONCAT_ROTATE_MIN_EDGES: usize = 3_000;
#[cfg(feature = "parallel")]
fn uma_f64_direct_concat_rotate_min_edges() -> usize {
    use std::sync::OnceLock;
    static THRESHOLD: OnceLock<usize> = OnceLock::new();
    *THRESHOLD.get_or_init(|| {
        std::env::var("LLMLIP_UMA_F64_DIRECT_CONCAT_ROTATE_MIN_EDGES")
            .ok()
            .and_then(|v| v.trim().parse::<usize>().ok())
            .filter(|&v| v > 0)
            .unwrap_or(6_000)
    })
}
