fn uma_trace_timings_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        matches!(
            env::var("LLMLIP_UMA_TRACE_TIMINGS").ok().as_deref(),
            Some("1" | "true" | "TRUE" | "yes" | "YES" | "on" | "ON")
        )
    })
}

fn uma_trace_start() -> Option<Instant> {
    uma_trace_timings_enabled().then(Instant::now)
}

fn uma_timing_start(profile_enabled: bool) -> Option<Instant> {
    (profile_enabled || uma_trace_timings_enabled()).then(Instant::now)
}

