fn trace_uma_stage(stage: &str, start: Option<Instant>) {
    if !uma_trace_timings_enabled() {
        return;
    }
    if let Some(start) = start {
        eprintln!(
            "uma_trace stage={} elapsed_ms={:.6}",
            stage,
            start.elapsed().as_secs_f64() * 1000.0
        );
    }
}

fn trace_uma_block_stage(block_index: usize, stage: &str, start: Option<Instant>) {
    if !uma_trace_timings_enabled() {
        return;
    }
    if let Some(start) = start {
        eprintln!(
            "uma_trace block={} stage={} elapsed_ms={:.6}",
            block_index,
            stage,
            start.elapsed().as_secs_f64() * 1000.0
        );
    }
}

