#[derive(Clone, Debug)]
struct UmaMixedSo2Weights {
    m0_weight: Vec<f64>,
    m_weights: Vec<Vec<f64>>,
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    m_fused_weights: Vec<Vec<f64>>,
    /// Precomputed fused m-conv forward weight matrices for portable f64 DGEMM.
    /// Element `i` is the fused weight for m-order `i+1`.
    /// Layout: `[[W0^T, W1^T], [-W1^T, W0^T]]` as `[2*in_dim, 2*out_dim]`.
    /// Empty on non-BLAS builds.
    #[allow(dead_code)]
    m_fused_weights_fwd: Vec<Vec<f64>>,
    /// Precomputed fused m-conv VJP weight matrices for portable f64 DGEMM.
    /// Element `i` is the fused weight for m-order `i+1`.
    /// Layout: `[[W0, -W1], [W1, W0]]` as `[2*out_dim, 2*in_dim]`.
    /// Empty on non-BLAS builds.
    #[allow(dead_code)]
    m_fused_weights_vjp: Vec<Vec<f64>>,
}

