fn transpose_so3_degree_weights_f32(
    weights_out_by_in: &[f32],
    degree_count: usize,
    in_channels: usize,
    out_channels: usize,
) -> Vec<f32> {
    let per_degree_len = in_channels * out_channels;
    let mut weights_in_by_out = vec![0.0_f32; weights_out_by_in.len()];
    for degree in 0..degree_count {
        let base = degree * per_degree_len;
        for out_channel in 0..out_channels {
            for in_channel in 0..in_channels {
                weights_in_by_out[base + in_channel * out_channels + out_channel] =
                    weights_out_by_in[base + out_channel * in_channels + in_channel];
            }
        }
    }
    weights_in_by_out
}

fn mix_uma_so2_weights_minor(
    config: EsenSo2ConvolutionConfig,
    experts: usize,
    m0_experts_minor: &[f64],
    m_experts_minor: &[&[f64]],
    coefficients: &[f64],
) -> Result<UmaMixedSo2Weights, ModelError> {
    check_len(
        "UMA expert-minor SO2 m expert weight count",
        config.m_max(),
        m_experts_minor.len(),
    )?;
    let m0_weight = mix_uma_expert_weights_minor(
        experts,
        config.m0_weight_len(),
        m0_experts_minor,
        coefficients,
    )?;
    let mut m_weights = Vec::with_capacity(config.m_max());
    for order in 1..=config.m_max() {
        m_weights.push(mix_uma_expert_weights_minor(
            experts,
            config.m_conv_weight_len(order),
            m_experts_minor[order - 1],
            coefficients,
        )?);
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    let m_fused_weights = {
        let mut fused = Vec::with_capacity(config.m_max());
        for order in 1..=config.m_max() {
            fused.push(
                fairchem_esen_so2_m_conv_fused_weight(config, order, &m_weights[order - 1])
                    .map_err(ModelError::Core)?,
            );
        }
        fused
    };
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    let (m_fused_weights_fwd, m_fused_weights_vjp) =
        build_uma_mixed_so2_fused_weights_f64(config, &m_weights);
    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )))]
    let (m_fused_weights_fwd, m_fused_weights_vjp) = (Vec::new(), Vec::new());
    Ok(UmaMixedSo2Weights {
        m0_weight,
        m_weights,
        #[cfg(any(
            all(feature = "accelerate-blas", target_os = "macos"),
            all(
                any(feature = "intel-mkl", feature = "openblas"),
                target_os = "linux",
                any(target_arch = "x86_64", target_arch = "aarch64")
            )
        ))]
        m_fused_weights,
        m_fused_weights_fwd,
        m_fused_weights_vjp,
    })
}

fn uma_mixed_so2_weight_refs(
    weights: &UmaMixedSo2Weights,
) -> Result<[&[f64]; UMA_M_MAX], ModelError> {
    check_len(
        "UMA mixed SO2 m weights",
        UMA_M_MAX,
        weights.m_weights.len(),
    )?;
    Ok([
        weights.m_weights[0].as_slice(),
        weights.m_weights[1].as_slice(),
    ])
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
fn build_uma_mixed_so2_fused_weights_f64(
    config: EsenSo2ConvolutionConfig,
    m_weights: &[Vec<f64>],
) -> (Vec<Vec<f64>>, Vec<Vec<f64>>) {
    let mut fwd = Vec::with_capacity(m_weights.len());
    let mut vjp = Vec::with_capacity(m_weights.len());
    for order in 1..=config.m_max() {
        let m_size = config.m_size(order).unwrap_or(1);
        let in_dim = m_size * config.in_channels();
        let out_dim = m_size * config.out_channels();
        let w = &m_weights[order - 1];
        fwd.push(crate::blas_backend::so2_mconv_build_fused_fwd_weight(
            in_dim, out_dim, w,
        ));
        vjp.push(crate::blas_backend::so2_mconv_build_fused_vjp_weight(
            in_dim, out_dim, w,
        ));
    }
    (fwd, vjp)
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
