#[allow(dead_code, clippy::too_many_arguments)]
fn uma_dense_forward_with_bias_rows_f32_with_fwd_weight(
    rows: usize,
    in_dim: usize,
    out_dim: usize,
    input: &[f32],
    weight: &[f32],
    weight_fwd: &[f32],
    bias: &[f32],
    out: &mut [f32],
) -> Result<(), ModelError> {
    check_len("UMA f32 dense input", rows * in_dim, input.len())?;
    check_len("UMA f32 dense weight", out_dim * in_dim, weight.len())?;
    if !weight_fwd.is_empty() {
        check_len(
            "UMA f32 dense forward weight",
            in_dim * out_dim,
            weight_fwd.len(),
        )?;
    }
    check_len("UMA f32 dense bias", out_dim, bias.len())?;
    check_len("UMA f32 dense output", rows * out_dim, out.len())?;
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    {
        #[cfg(all(feature = "parallel", target_arch = "x86_64"))]
        if !weight_fwd.is_empty()
            && crate::blas_backend::uma_f32_try_parallel_row_matmul_bias(
                rows, in_dim, out_dim, input, weight_fwd, bias, out,
            )
        {
            return Ok(());
        }
        crate::blas_backend::dense_forward_output_major_weight_f32(
            input, rows, in_dim, weight, out, out_dim, 1.0, 0.0,
        );
        let used_sve = {
            #[cfg(all(
                target_arch = "aarch64",
                target_os = "linux",
                llmlip_aarch64_sve_kernels
            ))]
            {
                uma_f32_bias_sve_enabled() && uma_add_bias_rows_sve_f32(rows, out_dim, bias, out)
            }
            #[cfg(not(all(
                target_arch = "aarch64",
                target_os = "linux",
                llmlip_aarch64_sve_kernels
            )))]
            {
                false
            }
        };
        if !used_sve {
            for out_row in out.chunks_exact_mut(out_dim).take(rows) {
                for (value, bias_value) in out_row.iter_mut().zip(bias.iter()) {
                    *value += *bias_value;
                }
            }
        }
        Ok(())
    }

    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )))]
    {
        for row in 0..rows {
            let input_row = &input[row * in_dim..(row + 1) * in_dim];
            let out_row = &mut out[row * out_dim..(row + 1) * out_dim];
            out_row.copy_from_slice(bias);
            for out_index in 0..out_dim {
                let weight_row = &weight[out_index * in_dim..(out_index + 1) * in_dim];
                let mut dot = 0.0_f32;
                for in_index in 0..in_dim {
                    dot += weight_row[in_index] * input_row[in_index];
                }
                out_row[out_index] += dot;
            }
        }
        Ok(())
    }
}

