#[allow(clippy::too_many_arguments)]
fn uma_mixed_so2_convolution_forward(
    config: EsenSo2ConvolutionConfig,
    input_l_major: &[f64],
    radial: Option<&[f64]>,
    weights: &UmaMixedSo2Weights,
    m0_bias: &[f64],
    out_l_major: &mut [f64],
    extra_m0_out: Option<&mut [f64]>,
) -> Result<(), ModelError> {
    let m_weight_refs = uma_mixed_so2_weight_refs(weights)?;
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    let m_fused_weight_refs = uma_mixed_so2_fused_weight_refs(weights)?;
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    let m_fused_weights = Some(m_fused_weight_refs.as_slice());
    #[cfg(not(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )))]
    let m_fused_weights: Option<&[&[f64]]> = None;
    fairchem_esen_so2_convolution_forward_with_fused_m_weights(
        config,
        input_l_major,
        radial,
        &weights.m0_weight,
        m0_bias,
        m_weight_refs.as_slice(),
        m_fused_weights,
        out_l_major,
        extra_m0_out,
    )
    .map_err(ModelError::Core)
}

