#[allow(clippy::too_many_arguments)]
fn uma_mixed_so2_convolution_forward_f32(
    config: EsenSo2ConvolutionConfig,
    input_l_major: &[f32],
    radial: Option<&[f32]>,
    weights: &UmaMixedSo2WeightsF32,
    m0_bias: &[f32],
    out_l_major: &mut [f32],
    extra_m0_out: Option<&mut [f32]>,
) -> Result<(), ModelError> {
    let rows = if !input_l_major.is_empty() {
        input_l_major.len() / config.input_node_stride()
    } else {
        0
    };
    // Use the precomputed-fused fast path when available (eliminates per-call
    // fused-weight rebuild and mix_expert_weights allocation).
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(
            any(feature = "intel-mkl", feature = "openblas"),
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if !weights.m_fused_weights_fwd.is_empty() {
        let m_weight_refs: Vec<&[f32]> = weights.m_weights.iter().map(Vec::as_slice).collect();
        let fused_fwd_refs: Vec<&[f32]> = weights
            .m_fused_weights_fwd
            .iter()
            .map(Vec::as_slice)
            .collect();
        return fairchem_uma_mole_so2_convolution_forward_precomputed_f32(
            config,
            rows,
            input_l_major,
            radial,
            &weights.m0_weight,
            m0_bias,
            &m_weight_refs,
            &fused_fwd_refs,
            out_l_major,
            extra_m0_out,
        )
        .map_err(ModelError::Core);
    }
    let m_weight_refs: Vec<&[f32]> = weights.m_weights.iter().map(Vec::as_slice).collect();
    fairchem_uma_mole_so2_convolution_forward_f32(
        UmaMoleSo2ConvolutionConfig {
            systems: 1,
            experts: 1,
            so2: config,
        },
        input_l_major,
        radial,
        &weights.m0_weight,
        m0_bias,
        &m_weight_refs,
        &[1.0_f32],
        &[rows],
        out_l_major,
        extra_m0_out,
    )
    .map_err(ModelError::Core)
}

