// ──────────────────────────────────────────────────────────────────────────────
// f64 fused UMA l=2/m=2 SO2 forward
//
// This mirrors the f32 fused forward below, but keeps f64 intermediates and
// calls portable DGEMM helpers from `blas_backend`. It is intentionally scoped
// to UMA's fixed l=2/m=2 conv1(radial)+gate+conv2 shape.
// ──────────────────────────────────────────────────────────────────────────────

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[allow(clippy::too_many_arguments)]
fn uma_so2_conv_l2_m2_radial_gate_conv2_forward_f64(
    nodes: usize,
    conv1_in_channels: usize,
    channels: usize,
    conv1_m0_weight: &[f64],
    conv1_m0_bias: &[f64],
    conv1_m_fused_fwd: &[Vec<f64>],
    conv2_m0_weight: &[f64],
    conv2_m0_bias: &[f64],
    conv2_m_fused_fwd: &[Vec<f64>],
    input_l_major: &[f64],
    radial: &[f64],
    conv1_out_l_major: &mut [f64],
    gate_sigmoids: &mut [f64],
    scalar_silu_derivatives: &mut [f64],
    conv2_out_l_major: &mut [f64],
) -> Result<(), ModelError> {
    check_len(
        "UMA f64 SO2 conv1 fused weights",
        2,
        conv1_m_fused_fwd.len(),
    )?;
    check_len(
        "UMA f64 SO2 conv2 fused weights",
        2,
        conv2_m_fused_fwd.len(),
    )?;
    check_len(
        "UMA f64 SO2 input",
        nodes * 9 * conv1_in_channels,
        input_l_major.len(),
    )?;
    check_len(
        "UMA f64 SO2 radial",
        nodes * 6 * conv1_in_channels,
        radial.len(),
    )?;
    check_len(
        "UMA f64 SO2 conv1 output",
        nodes * 9 * channels,
        conv1_out_l_major.len(),
    )?;
    check_len(
        "UMA f64 SO2 gates",
        nodes * 2 * channels,
        gate_sigmoids.len(),
    )?;
    check_len(
        "UMA f64 SO2 scalar derivatives",
        nodes * channels,
        scalar_silu_derivatives.len(),
    )?;
    check_len(
        "UMA f64 SO2 conv2 output",
        nodes * 9 * channels,
        conv2_out_l_major.len(),
    )?;

    let m0_out_dim = 5 * channels;
    let input_node_stride = 9 * conv1_in_channels;
    let radial_node_stride = 6 * conv1_in_channels;
    let conv1_out_node_stride = 9 * channels;
    let gate_node_stride = 2 * channels;
    let conv2_m0_in_node_stride = 3 * channels;
    #[cfg(feature = "parallel")]
    let parallel_nodes = rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes();

    UMA_L2_M2_FUSED_F64_FWD_SCRATCH.with(|scratch| -> Result<(), ModelError> {
        let mut scratch = scratch.borrow_mut();
        let UmaL2M2FusedF64ForwardScratch {
            conv1_m0_input,
            conv1_m0_dense_out,
            conv2_m0_input,
            conv2_m0_out,
            conv1_block_input,
            conv1_block_out,
            conv2_block_input,
            conv2_block_out,
        } = &mut *scratch;

        reset_f64_vec_uninit(conv1_m0_input, nodes * 3 * conv1_in_channels);
        #[cfg(feature = "parallel")]
        if parallel_nodes {
            conv1_m0_input
                .par_chunks_mut(3 * conv1_in_channels)
                .enumerate()
                .for_each(|(node, m0_input)| {
                    let in_base = node * input_node_stride;
                    let rad_base = node * radial_node_stride;
                    for ch in 0..conv1_in_channels {
                        m0_input[ch] = input_l_major[in_base + ch] * radial[rad_base + ch];
                        m0_input[conv1_in_channels + ch] = input_l_major
                            [in_base + 2 * conv1_in_channels + ch]
                            * radial[rad_base + conv1_in_channels + ch];
                        m0_input[2 * conv1_in_channels + ch] = input_l_major
                            [in_base + 6 * conv1_in_channels + ch]
                            * radial[rad_base + 2 * conv1_in_channels + ch];
                    }
                });
        } else {
            for node in 0..nodes {
                let in_base = node * input_node_stride;
                let rad_base = node * radial_node_stride;
                let blk_base = node * 3 * conv1_in_channels;
                for ch in 0..conv1_in_channels {
                    conv1_m0_input[blk_base + ch] =
                        input_l_major[in_base + ch] * radial[rad_base + ch];
                    conv1_m0_input[blk_base + conv1_in_channels + ch] = input_l_major
                        [in_base + 2 * conv1_in_channels + ch]
                        * radial[rad_base + conv1_in_channels + ch];
                    conv1_m0_input[blk_base + 2 * conv1_in_channels + ch] = input_l_major
                        [in_base + 6 * conv1_in_channels + ch]
                        * radial[rad_base + 2 * conv1_in_channels + ch];
                }
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let in_base = node * input_node_stride;
                let rad_base = node * radial_node_stride;
                let blk_base = node * 3 * conv1_in_channels;
                for ch in 0..conv1_in_channels {
                    conv1_m0_input[blk_base + ch] =
                        input_l_major[in_base + ch] * radial[rad_base + ch];
                    conv1_m0_input[blk_base + conv1_in_channels + ch] = input_l_major
                        [in_base + 2 * conv1_in_channels + ch]
                        * radial[rad_base + conv1_in_channels + ch];
                    conv1_m0_input[blk_base + 2 * conv1_in_channels + ch] = input_l_major
                        [in_base + 6 * conv1_in_channels + ch]
                        * radial[rad_base + 2 * conv1_in_channels + ch];
                }
            }
        }

        reset_f64_vec_uninit(conv1_m0_dense_out, nodes * m0_out_dim);
        uma_dense_forward_with_bias_rows(
            nodes,
            3 * conv1_in_channels,
            m0_out_dim,
            conv1_m0_input,
            conv1_m0_weight,
            conv1_m0_bias,
            conv1_m0_dense_out,
        )?;

        reset_f64_vec_uninit(conv2_m0_input, nodes * 3 * channels);
        #[cfg(feature = "parallel")]
        if parallel_nodes {
            conv2_m0_input
                .par_chunks_mut(conv2_m0_in_node_stride)
                .zip(gate_sigmoids.par_chunks_mut(gate_node_stride))
                .zip(conv1_out_l_major.par_chunks_mut(conv1_out_node_stride))
                .zip(scalar_silu_derivatives.par_chunks_mut(channels))
                .zip(conv1_m0_dense_out.par_chunks(m0_out_dim))
                .for_each(|((((conv2_in, gates), conv1_out), derivs), dense)| {
                    for ch in 0..channels {
                        let gate1 = uma_so2_gate_sigmoid_f64(dense[ch]);
                        gates[ch] = gate1;

                        let gate2 = uma_so2_gate_sigmoid_f64(dense[channels + ch]);
                        gates[channels + ch] = gate2;

                        let scalar = dense[2 * channels + ch];
                        conv1_out[ch] = scalar;
                        conv2_in[ch] = silu(scalar);
                        derivs[ch] = silu_derivative(scalar);

                        let l1_val = dense[3 * channels + ch];
                        conv1_out[channels + ch] = l1_val;
                        conv2_in[channels + ch] = l1_val * gate1;

                        let l2_val = dense[4 * channels + ch];
                        conv1_out[2 * channels + ch] = l2_val;
                        conv2_in[2 * channels + ch] = l2_val * gate2;
                    }
                });
        } else {
            for node in 0..nodes {
                let dense_base = node * m0_out_dim;
                let conv1_base = node * conv1_out_node_stride;
                let gate_base = node * gate_node_stride;
                let conv2_in_base = node * conv2_m0_in_node_stride;
                let deriv_base = node * channels;
                for ch in 0..channels {
                    let gate1_raw = conv1_m0_dense_out[dense_base + ch];
                    let gate1 = uma_so2_gate_sigmoid_f64(gate1_raw);
                    gate_sigmoids[gate_base + ch] = gate1;

                    let gate2_raw = conv1_m0_dense_out[dense_base + channels + ch];
                    let gate2 = uma_so2_gate_sigmoid_f64(gate2_raw);
                    gate_sigmoids[gate_base + channels + ch] = gate2;

                    let scalar = conv1_m0_dense_out[dense_base + 2 * channels + ch];
                    conv1_out_l_major[conv1_base + ch] = scalar;
                    let silu_val = silu(scalar);
                    let silu_deriv = silu_derivative(scalar);
                    conv2_m0_input[conv2_in_base + ch] = silu_val;
                    scalar_silu_derivatives[deriv_base + ch] = silu_deriv;

                    let l1_val = conv1_m0_dense_out[dense_base + 3 * channels + ch];
                    conv1_out_l_major[conv1_base + channels + ch] = l1_val;
                    conv2_m0_input[conv2_in_base + channels + ch] = l1_val * gate1;

                    let l2_val = conv1_m0_dense_out[dense_base + 4 * channels + ch];
                    conv1_out_l_major[conv1_base + 2 * channels + ch] = l2_val;
                    conv2_m0_input[conv2_in_base + 2 * channels + ch] = l2_val * gate2;
                }
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let dense_base = node * m0_out_dim;
                let conv1_base = node * conv1_out_node_stride;
                let gate_base = node * gate_node_stride;
                let conv2_in_base = node * conv2_m0_in_node_stride;
                let deriv_base = node * channels;
                for ch in 0..channels {
                    let gate1_raw = conv1_m0_dense_out[dense_base + ch];
                    let gate1 = uma_so2_gate_sigmoid_f64(gate1_raw);
                    gate_sigmoids[gate_base + ch] = gate1;

                    let gate2_raw = conv1_m0_dense_out[dense_base + channels + ch];
                    let gate2 = uma_so2_gate_sigmoid_f64(gate2_raw);
                    gate_sigmoids[gate_base + channels + ch] = gate2;

                    let scalar = conv1_m0_dense_out[dense_base + 2 * channels + ch];
                    conv1_out_l_major[conv1_base + ch] = scalar;
                    let silu_val = silu(scalar);
                    let silu_deriv = silu_derivative(scalar);
                    conv2_m0_input[conv2_in_base + ch] = silu_val;
                    scalar_silu_derivatives[deriv_base + ch] = silu_deriv;

                    let l1_val = conv1_m0_dense_out[dense_base + 3 * channels + ch];
                    conv1_out_l_major[conv1_base + channels + ch] = l1_val;
                    conv2_m0_input[conv2_in_base + channels + ch] = l1_val * gate1;

                    let l2_val = conv1_m0_dense_out[dense_base + 4 * channels + ch];
                    conv1_out_l_major[conv1_base + 2 * channels + ch] = l2_val;
                    conv2_m0_input[conv2_in_base + 2 * channels + ch] = l2_val * gate2;
                }
            }
        }

        reset_f64_vec_uninit(conv2_m0_out, nodes * 3 * channels);
        uma_dense_forward_with_bias_rows(
            nodes,
            3 * channels,
            3 * channels,
            conv2_m0_input,
            conv2_m0_weight,
            conv2_m0_bias,
            conv2_m0_out,
        )?;
        #[cfg(feature = "parallel")]
        if parallel_nodes {
            conv2_out_l_major
                .par_chunks_mut(conv1_out_node_stride)
                .zip(conv2_m0_out.par_chunks(3 * channels))
                .for_each(|(out_node, m0_out)| {
                    out_node[..channels].copy_from_slice(&m0_out[..channels]);
                    out_node[2 * channels..3 * channels]
                        .copy_from_slice(&m0_out[channels..2 * channels]);
                    out_node[6 * channels..7 * channels]
                        .copy_from_slice(&m0_out[2 * channels..3 * channels]);
                });
        } else {
            for node in 0..nodes {
                let src_base = node * 3 * channels;
                let dst_base = node * conv1_out_node_stride;
                conv2_out_l_major[dst_base..dst_base + channels]
                    .copy_from_slice(&conv2_m0_out[src_base..src_base + channels]);
                conv2_out_l_major[dst_base + 2 * channels..dst_base + 3 * channels]
                    .copy_from_slice(&conv2_m0_out[src_base + channels..src_base + 2 * channels]);
                conv2_out_l_major[dst_base + 6 * channels..dst_base + 7 * channels]
                    .copy_from_slice(
                        &conv2_m0_out[src_base + 2 * channels..src_base + 3 * channels],
                    );
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let src_base = node * 3 * channels;
                let dst_base = node * conv1_out_node_stride;
                conv2_out_l_major[dst_base..dst_base + channels]
                    .copy_from_slice(&conv2_m0_out[src_base..src_base + channels]);
                conv2_out_l_major[dst_base + 2 * channels..dst_base + 3 * channels]
                    .copy_from_slice(&conv2_m0_out[src_base + channels..src_base + 2 * channels]);
                conv2_out_l_major[dst_base + 6 * channels..dst_base + 7 * channels]
                    .copy_from_slice(
                        &conv2_m0_out[src_base + 2 * channels..src_base + 3 * channels],
                    );
            }
        }

        #[cfg(all(
            feature = "parallel",
            any(
                all(feature = "accelerate-blas", target_os = "macos"),
                all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
                all(
                    feature = "openblas",
                    target_os = "linux",
                    any(target_arch = "x86_64", target_arch = "aarch64")
                )
            )
        ))]
        if rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes() {
            return uma_so2_conv_l2_m2_orders_forward_parallel_f64(
                nodes,
                conv1_in_channels,
                channels,
                conv1_m_fused_fwd,
                conv2_m_fused_fwd,
                input_l_major,
                radial,
                gate_sigmoids,
                conv1_out_l_major,
                conv2_out_l_major,
            );
        }

        let max_sources = 4usize;
        reset_f64_vec_uninit(conv1_block_input, nodes * max_sources * conv1_in_channels);
        reset_f64_vec_uninit(conv1_block_out, nodes * max_sources * channels);
        reset_f64_vec_uninit(conv2_block_input, nodes * max_sources * channels);
        reset_f64_vec_uninit(conv2_block_out, nodes * max_sources * channels);
        let mut radial_offset = 3 * conv1_in_channels;

        for (order_idx, (sources, m_size)) in
            [(&[3usize, 7, 1, 5][..], 2usize), (&[8usize, 4][..], 1usize)]
                .iter()
                .enumerate()
        {
            let sources = *sources;
            let m_size = *m_size;
            let n_sources = sources.len();
            let conv1_block_len = nodes * n_sources * conv1_in_channels;
            let conv1_out_len = nodes * n_sources * channels;

            let conv1_blk = &mut conv1_block_input[..conv1_block_len];
            let conv1_blk_in_stride = n_sources * conv1_in_channels;
            for node in 0..nodes {
                let in_base = node * input_node_stride;
                let rad_base = node * radial_node_stride + radial_offset;
                let blk_base = node * conv1_blk_in_stride;
                if m_size == 2 {
                    for ch in 0..conv1_in_channels {
                        let r0 = radial[rad_base + ch];
                        let r1 = radial[rad_base + conv1_in_channels + ch];
                        conv1_blk[blk_base + ch] =
                            input_l_major[in_base + 3 * conv1_in_channels + ch] * r0;
                        conv1_blk[blk_base + conv1_in_channels + ch] =
                            input_l_major[in_base + 7 * conv1_in_channels + ch] * r1;
                        conv1_blk[blk_base + 2 * conv1_in_channels + ch] =
                            input_l_major[in_base + conv1_in_channels + ch] * r0;
                        conv1_blk[blk_base + 3 * conv1_in_channels + ch] =
                            input_l_major[in_base + 5 * conv1_in_channels + ch] * r1;
                    }
                } else {
                    for ch in 0..conv1_in_channels {
                        let r0 = radial[rad_base + ch];
                        conv1_blk[blk_base + ch] =
                            input_l_major[in_base + 8 * conv1_in_channels + ch] * r0;
                        conv1_blk[blk_base + conv1_in_channels + ch] =
                            input_l_major[in_base + 4 * conv1_in_channels + ch] * r0;
                    }
                }
            }

            let in_dim = m_size * conv1_in_channels;
            let out_dim = m_size * channels;
            let conv1_blk_out = &mut conv1_block_out[..conv1_out_len];
            crate::blas_backend::so2_mconv_forward_set_precomputed_fused(
                nodes,
                in_dim,
                out_dim,
                &conv1_m_fused_fwd[order_idx],
                conv1_blk,
                conv1_blk_out,
            );

            let conv2_blk_len = nodes * n_sources * channels;
            let conv2_blk = &mut conv2_block_input[..conv2_blk_len];
            let conv1_blk_out = &conv1_block_out[..conv1_out_len];
            let blk_stride = n_sources * channels;
            if m_size == 2 {
                for node in 0..nodes {
                    let conv1_base = node * conv1_out_node_stride + 3 * channels;
                    let gate_base = node * gate_node_stride;
                    let blk_base = node * blk_stride;
                    for ch in 0..channels {
                        let gate1 = gate_sigmoids[gate_base + ch];
                        let gate2 = gate_sigmoids[gate_base + channels + ch];

                        let v3 = conv1_blk_out[blk_base + ch];
                        conv1_out_l_major[conv1_base + ch] = v3;
                        conv2_blk[blk_base + ch] = v3 * gate1;

                        let v7 = conv1_blk_out[blk_base + channels + ch];
                        conv1_out_l_major[conv1_base + channels + ch] = v7;
                        conv2_blk[blk_base + channels + ch] = v7 * gate2;

                        let v1 = conv1_blk_out[blk_base + 2 * channels + ch];
                        conv1_out_l_major[conv1_base + 2 * channels + ch] = v1;
                        conv2_blk[blk_base + 2 * channels + ch] = v1 * gate1;

                        let v5 = conv1_blk_out[blk_base + 3 * channels + ch];
                        conv1_out_l_major[conv1_base + 3 * channels + ch] = v5;
                        conv2_blk[blk_base + 3 * channels + ch] = v5 * gate2;
                    }
                }
            } else {
                for node in 0..nodes {
                    let conv1_base = node * conv1_out_node_stride + 7 * channels;
                    let gate_base = node * gate_node_stride;
                    let blk_base = node * blk_stride;
                    for ch in 0..channels {
                        let gate2 = gate_sigmoids[gate_base + channels + ch];

                        let v8 = conv1_blk_out[blk_base + ch];
                        conv1_out_l_major[conv1_base + ch] = v8;
                        conv2_blk[blk_base + ch] = v8 * gate2;

                        let v4 = conv1_blk_out[blk_base + channels + ch];
                        conv1_out_l_major[conv1_base + channels + ch] = v4;
                        conv2_blk[blk_base + channels + ch] = v4 * gate2;
                    }
                }
            }

            let conv2_in_dim = m_size * channels;
            let conv2_out_dim = m_size * channels;
            let conv2_blk_out = &mut conv2_block_out[..conv2_blk_len];
            crate::blas_backend::so2_mconv_forward_set_precomputed_fused(
                nodes,
                conv2_in_dim,
                conv2_out_dim,
                &conv2_m_fused_fwd[order_idx],
                conv2_blk,
                conv2_blk_out,
            );

            let conv2_blk_out = &conv2_block_out[..conv2_blk_len];
            let out_stride = 9 * channels;
            if m_size == 2 {
                for node in 0..nodes {
                    let dst = node * out_stride;
                    let blk = node * blk_stride;
                    conv2_out_l_major[dst + 3 * channels..dst + 4 * channels]
                        .copy_from_slice(&conv2_blk_out[blk..blk + channels]);
                    conv2_out_l_major[dst + 7 * channels..dst + 8 * channels]
                        .copy_from_slice(&conv2_blk_out[blk + channels..blk + 2 * channels]);
                    conv2_out_l_major[dst + channels..dst + 2 * channels]
                        .copy_from_slice(&conv2_blk_out[blk + 2 * channels..blk + 3 * channels]);
                    conv2_out_l_major[dst + 5 * channels..dst + 6 * channels]
                        .copy_from_slice(&conv2_blk_out[blk + 3 * channels..blk + 4 * channels]);
                }
            } else {
                for node in 0..nodes {
                    let dst = node * out_stride;
                    let blk = node * blk_stride;
                    conv2_out_l_major[dst + 8 * channels..dst + 9 * channels]
                        .copy_from_slice(&conv2_blk_out[blk..blk + channels]);
                    conv2_out_l_major[dst + 4 * channels..dst + 5 * channels]
                        .copy_from_slice(&conv2_blk_out[blk + channels..blk + 2 * channels]);
                }
            }

            radial_offset += m_size * conv1_in_channels;
        }

        Ok(())
    })
}

#[inline(always)]
#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
fn uma_so2_gate_sigmoid_f64(x: f64) -> f64 {
    if x >= 0.0 {
        1.0 / (1.0 + (-x).exp())
    } else {
        let e = x.exp();
        e / (1.0 + e)
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[allow(clippy::too_many_arguments)]
fn uma_so2_conv_l2_m2_radial_gate_conv2_vjp_f64(
    nodes: usize,
    conv1_in_channels: usize,
    channels: usize,
    conv2_m0_weight: &[f64],
    conv2_m_fused_vjp: &[Vec<f64>],
    grad_conv2_out_l_major: &[f64],
    conv1_out_l_major: &[f64],
    gate_sigmoids: &[f64],
    scalar_silu_derivatives: &[f64],
    conv1_m0_weight: &[f64],
    conv1_m_fused_vjp: &[Vec<f64>],
    conv1_input_l_major: &[f64],
    conv1_radial: &[f64],
    grad_conv1_input_l_major: &mut [f64],
    grad_conv1_radial: &mut [f64],
    mut profile: Option<&mut UmaSo2FusedVjpProfile>,
) -> Result<(), ModelError> {
    check_len("UMA f64 SO2 conv2 VJP weights", 2, conv2_m_fused_vjp.len())?;
    check_len("UMA f64 SO2 conv1 VJP weights", 2, conv1_m_fused_vjp.len())?;
    let m0_out_dim = 5 * channels;
    let radial_node_stride = 6 * conv1_in_channels;
    let input_node_stride = 9 * conv1_in_channels;
    let out_node_stride = 9 * channels;
    let gate_node_stride = 2 * channels;
    check_len(
        "UMA f64 SO2 VJP grad_conv2_out",
        nodes * out_node_stride,
        grad_conv2_out_l_major.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP conv1_out",
        nodes * out_node_stride,
        conv1_out_l_major.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP gates",
        nodes * gate_node_stride,
        gate_sigmoids.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP scalar derivatives",
        nodes * channels,
        scalar_silu_derivatives.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP conv1 input",
        nodes * input_node_stride,
        conv1_input_l_major.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP conv1 radial",
        nodes * radial_node_stride,
        conv1_radial.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP grad conv1 input",
        nodes * input_node_stride,
        grad_conv1_input_l_major.len(),
    )?;
    check_len(
        "UMA f64 SO2 VJP grad conv1 radial",
        nodes * radial_node_stride,
        grad_conv1_radial.len(),
    )?;
    let profile_enabled = profile.is_some();
    #[cfg(feature = "parallel")]
    let parallel_nodes = rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes();

    UMA_L2_M2_FUSED_F64_VJP_SCRATCH.with(|scratch| -> Result<(), ModelError> {
        let mut scratch = scratch.borrow_mut();
        let UmaL2M2FusedF64VjpScratch {
            conv1_m0_full_grad_out,
            conv2_m0_grad_out,
            activated_m0_grad,
            conv2_block_grad_out,
            activated_block_grad,
            conv1_block_grad_out,
            conv1_block_grad_modulated,
            order2_m0_gate_grad,
            conv1_m0_grad_modulated,
        } = &mut *scratch;
        let _ = &mut *order2_m0_gate_grad;

        let stage_start = uma_timing_start(profile_enabled);
        let assign_m0_gate = nodes >= UMA_F64_ASSIGN_M0_GATE_MIN_NODES;
        if assign_m0_gate {
            reset_f64_vec_uninit(conv1_m0_full_grad_out, nodes * m0_out_dim);
        } else {
            conv1_m0_full_grad_out.resize(nodes * m0_out_dim, 0.0);
            #[cfg(feature = "parallel")]
            if parallel_nodes {
                conv1_m0_full_grad_out
                    .par_chunks_mut(m0_out_dim)
                    .for_each(|row| row.fill(0.0));
            } else {
                conv1_m0_full_grad_out.fill(0.0);
            }
            #[cfg(not(feature = "parallel"))]
            {
                conv1_m0_full_grad_out.fill(0.0);
            }
        }
        trace_uma_stage("f64.so2_vjp.m0_grad_zero", stage_start);
        if let Some(p) = profile.as_deref_mut() {
            p.m0_grad_zero.record_optional(stage_start);
        }

        let stage_start = uma_timing_start(profile_enabled);
        reset_f64_vec_uninit(conv2_m0_grad_out, nodes * 3 * channels);
        #[cfg(feature = "parallel")]
        if parallel_nodes {
            conv2_m0_grad_out
                .par_chunks_mut(3 * channels)
                .enumerate()
                .for_each(|(node, row)| {
                    let src = node * out_node_stride;
                    row[..channels].copy_from_slice(&grad_conv2_out_l_major[src..src + channels]);
                    row[channels..2 * channels].copy_from_slice(
                        &grad_conv2_out_l_major[src + 2 * channels..src + 3 * channels],
                    );
                    row[2 * channels..3 * channels].copy_from_slice(
                        &grad_conv2_out_l_major[src + 6 * channels..src + 7 * channels],
                    );
                });
        } else {
            for node in 0..nodes {
                let src = node * out_node_stride;
                let dst = node * 3 * channels;
                conv2_m0_grad_out[dst..dst + channels]
                    .copy_from_slice(&grad_conv2_out_l_major[src..src + channels]);
                conv2_m0_grad_out[dst + channels..dst + 2 * channels].copy_from_slice(
                    &grad_conv2_out_l_major[src + 2 * channels..src + 3 * channels],
                );
                conv2_m0_grad_out[dst + 2 * channels..dst + 3 * channels].copy_from_slice(
                    &grad_conv2_out_l_major[src + 6 * channels..src + 7 * channels],
                );
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let src = node * out_node_stride;
                let dst = node * 3 * channels;
                conv2_m0_grad_out[dst..dst + channels]
                    .copy_from_slice(&grad_conv2_out_l_major[src..src + channels]);
                conv2_m0_grad_out[dst + channels..dst + 2 * channels].copy_from_slice(
                    &grad_conv2_out_l_major[src + 2 * channels..src + 3 * channels],
                );
                conv2_m0_grad_out[dst + 2 * channels..dst + 3 * channels].copy_from_slice(
                    &grad_conv2_out_l_major[src + 6 * channels..src + 7 * channels],
                );
            }
        }
        trace_uma_stage("f64.so2_vjp.m0_gather_conv2", stage_start);
        if let Some(p) = profile.as_deref_mut() {
            p.m0_gather_conv2.record_optional(stage_start);
        }

        let stage_start = uma_timing_start(profile_enabled);
        reset_f64_vec_uninit(activated_m0_grad, nodes * 3 * channels);
        uma_dense_vjp_input_rows_write(
            nodes,
            3 * channels,
            3 * channels,
            conv2_m0_weight,
            conv2_m0_grad_out,
            activated_m0_grad,
        )?;
        trace_uma_stage("f64.so2_vjp.m0_conv2_dense_vjp", stage_start);
        if let Some(p) = profile.as_deref_mut() {
            p.m0_conv2_dense_vjp.record_optional(stage_start);
        }

        let stage_start = uma_timing_start(profile_enabled);
        #[cfg(feature = "parallel")]
        if parallel_nodes {
            conv1_m0_full_grad_out
                .par_chunks_mut(m0_out_dim)
                .zip(activated_m0_grad.par_chunks(3 * channels))
                .zip(conv1_out_l_major.par_chunks(out_node_stride))
                .zip(gate_sigmoids.par_chunks(gate_node_stride))
                .zip(scalar_silu_derivatives.par_chunks(channels))
                .for_each(|((((full_grad, act), conv1_out), gates), derivs)| {
                    for ch in 0..channels {
                        let grad_scalar = act[ch];
                        let grad_scalar_value = grad_scalar * derivs[ch];

                        let grad_l1 = act[channels + ch];
                        let gate_l1 = gates[ch];
                        let conv1_l1 = conv1_out[channels + ch];
                        let grad_l1_gate = grad_l1 * gate_l1;
                        let grad_l1_m0_gate = grad_l1 * conv1_l1;

                        let grad_l2 = act[2 * channels + ch];
                        let gate_l2 = gates[channels + ch];
                        let conv1_l2 = conv1_out[2 * channels + ch];
                        let grad_l2_gate = grad_l2 * gate_l2;
                        let grad_l2_m0_gate = grad_l2 * conv1_l2;
                        if assign_m0_gate {
                            full_grad[2 * channels + ch] = grad_scalar_value;
                            full_grad[3 * channels + ch] = grad_l1_gate;
                            full_grad[ch] = grad_l1_m0_gate;
                            full_grad[4 * channels + ch] = grad_l2_gate;
                            full_grad[channels + ch] = grad_l2_m0_gate;
                        } else {
                            full_grad[2 * channels + ch] += grad_scalar_value;
                            full_grad[3 * channels + ch] += grad_l1_gate;
                            full_grad[ch] += grad_l1_m0_gate;
                            full_grad[4 * channels + ch] += grad_l2_gate;
                            full_grad[channels + ch] += grad_l2_m0_gate;
                        }
                    }
                });
        } else {
            for node in 0..nodes {
                let act_base = node * 3 * channels;
                let conv1_base = node * out_node_stride;
                let gate_base = node * gate_node_stride;
                let deriv_base = node * channels;
                let full_grad_base = node * m0_out_dim;
                for ch in 0..channels {
                    let grad_scalar = activated_m0_grad[act_base + ch];
                    let grad_scalar_value = grad_scalar * scalar_silu_derivatives[deriv_base + ch];

                    let grad_l1 = activated_m0_grad[act_base + channels + ch];
                    let gate_l1 = gate_sigmoids[gate_base + ch];
                    let conv1_l1 = conv1_out_l_major[conv1_base + channels + ch];
                    let grad_l1_gate = grad_l1 * gate_l1;
                    let grad_l1_m0_gate = grad_l1 * conv1_l1;

                    let grad_l2 = activated_m0_grad[act_base + 2 * channels + ch];
                    let gate_l2 = gate_sigmoids[gate_base + channels + ch];
                    let conv1_l2 = conv1_out_l_major[conv1_base + 2 * channels + ch];
                    let grad_l2_gate = grad_l2 * gate_l2;
                    let grad_l2_m0_gate = grad_l2 * conv1_l2;
                    if assign_m0_gate {
                        conv1_m0_full_grad_out[full_grad_base + 2 * channels + ch] =
                            grad_scalar_value;
                        conv1_m0_full_grad_out[full_grad_base + 3 * channels + ch] = grad_l1_gate;
                        conv1_m0_full_grad_out[full_grad_base + ch] = grad_l1_m0_gate;
                        conv1_m0_full_grad_out[full_grad_base + 4 * channels + ch] = grad_l2_gate;
                        conv1_m0_full_grad_out[full_grad_base + channels + ch] = grad_l2_m0_gate;
                    } else {
                        conv1_m0_full_grad_out[full_grad_base + 2 * channels + ch] +=
                            grad_scalar_value;
                        conv1_m0_full_grad_out[full_grad_base + 3 * channels + ch] += grad_l1_gate;
                        conv1_m0_full_grad_out[full_grad_base + ch] += grad_l1_m0_gate;
                        conv1_m0_full_grad_out[full_grad_base + 4 * channels + ch] += grad_l2_gate;
                        conv1_m0_full_grad_out[full_grad_base + channels + ch] += grad_l2_m0_gate;
                    }
                }
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let act_base = node * 3 * channels;
                let conv1_base = node * out_node_stride;
                let gate_base = node * gate_node_stride;
                let deriv_base = node * channels;
                let full_grad_base = node * m0_out_dim;
                for ch in 0..channels {
                    let grad_scalar = activated_m0_grad[act_base + ch];
                    let grad_scalar_value = grad_scalar * scalar_silu_derivatives[deriv_base + ch];

                    let grad_l1 = activated_m0_grad[act_base + channels + ch];
                    let gate_l1 = gate_sigmoids[gate_base + ch];
                    let conv1_l1 = conv1_out_l_major[conv1_base + channels + ch];
                    let grad_l1_gate = grad_l1 * gate_l1;
                    let grad_l1_m0_gate = grad_l1 * conv1_l1;

                    let grad_l2 = activated_m0_grad[act_base + 2 * channels + ch];
                    let gate_l2 = gate_sigmoids[gate_base + channels + ch];
                    let conv1_l2 = conv1_out_l_major[conv1_base + 2 * channels + ch];
                    let grad_l2_gate = grad_l2 * gate_l2;
                    let grad_l2_m0_gate = grad_l2 * conv1_l2;
                    if assign_m0_gate {
                        conv1_m0_full_grad_out[full_grad_base + 2 * channels + ch] =
                            grad_scalar_value;
                        conv1_m0_full_grad_out[full_grad_base + 3 * channels + ch] = grad_l1_gate;
                        conv1_m0_full_grad_out[full_grad_base + ch] = grad_l1_m0_gate;
                        conv1_m0_full_grad_out[full_grad_base + 4 * channels + ch] = grad_l2_gate;
                        conv1_m0_full_grad_out[full_grad_base + channels + ch] = grad_l2_m0_gate;
                    } else {
                        conv1_m0_full_grad_out[full_grad_base + 2 * channels + ch] +=
                            grad_scalar_value;
                        conv1_m0_full_grad_out[full_grad_base + 3 * channels + ch] += grad_l1_gate;
                        conv1_m0_full_grad_out[full_grad_base + ch] += grad_l1_m0_gate;
                        conv1_m0_full_grad_out[full_grad_base + 4 * channels + ch] += grad_l2_gate;
                        conv1_m0_full_grad_out[full_grad_base + channels + ch] += grad_l2_m0_gate;
                    }
                }
            }
        }
        trace_uma_stage("f64.so2_vjp.m0_gate_vjp", stage_start);
        if let Some(p) = profile.as_deref_mut() {
            p.m0_gate_vjp.record_optional(stage_start);
        }

        #[cfg(all(
            feature = "parallel",
            any(
                all(feature = "accelerate-blas", target_os = "macos"),
                all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
                all(
                    feature = "openblas",
                    target_os = "linux",
                    any(target_arch = "x86_64", target_arch = "aarch64")
                )
            )
        ))]
        let skip_seq_loop =
            if rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes() {
                reset_f64_vec_uninit(order2_m0_gate_grad, nodes * channels);
                let stage_start = uma_timing_start(profile_enabled);
                uma_so2_conv_l2_m2_orders_vjp_parallel_f64(
                    nodes,
                    conv1_in_channels,
                    channels,
                    m0_out_dim,
                    conv2_m_fused_vjp,
                    conv1_m_fused_vjp,
                    grad_conv2_out_l_major,
                    conv1_out_l_major,
                    gate_sigmoids,
                    conv1_input_l_major,
                    conv1_radial,
                    conv1_m0_full_grad_out,
                    order2_m0_gate_grad,
                    grad_conv1_input_l_major,
                    grad_conv1_radial,
                    nodes >= UMA_F64_INPLACE_GATE_CONV1_MIN_NODES,
                    profile.as_deref_mut(),
                )?;
                trace_uma_stage("f64.so2_vjp.orders_parallel", stage_start);
                if let Some(p) = profile.as_deref_mut() {
                    p.orders_parallel.record_optional(stage_start);
                }
                true
            } else {
                false
            };
        #[cfg(not(all(
            feature = "parallel",
            any(
                all(feature = "accelerate-blas", target_os = "macos"),
                all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
                all(
                    feature = "openblas",
                    target_os = "linux",
                    any(target_arch = "x86_64", target_arch = "aarch64")
                )
            )
        )))]
        let skip_seq_loop = false;

        if !skip_seq_loop {
            let max_sources = 4usize;
            reset_f64_vec_uninit(conv2_block_grad_out, nodes * max_sources * channels);
            reset_f64_vec_uninit(activated_block_grad, nodes * max_sources * channels);
            reset_f64_vec_uninit(conv1_block_grad_out, nodes * max_sources * channels);
            reset_f64_vec_uninit(
                conv1_block_grad_modulated,
                nodes * max_sources * conv1_in_channels,
            );
            let mut radial_offset = 3 * conv1_in_channels;

            for (order_idx, (sources, m_size)) in
                [(&[3usize, 7, 1, 5][..], 2usize), (&[8usize, 4][..], 1usize)]
                    .iter()
                    .enumerate()
            {
                let sources = *sources;
                let m_size = *m_size;
                let n_sources = sources.len();
                let blk_len = nodes * n_sources * channels;
                let blk_stride = n_sources * channels;

                let conv2_blk_grad = &mut conv2_block_grad_out[..blk_len];
                if m_size == 2 {
                    for node in 0..nodes {
                        let src = node * out_node_stride;
                        let dst = node * blk_stride;
                        conv2_blk_grad[dst..dst + channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 3 * channels..src + 4 * channels],
                        );
                        conv2_blk_grad[dst + channels..dst + 2 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 7 * channels..src + 8 * channels],
                        );
                        conv2_blk_grad[dst + 2 * channels..dst + 3 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + channels..src + 2 * channels],
                        );
                        conv2_blk_grad[dst + 3 * channels..dst + 4 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 5 * channels..src + 6 * channels],
                        );
                    }
                } else {
                    for node in 0..nodes {
                        let src = node * out_node_stride;
                        let dst = node * blk_stride;
                        conv2_blk_grad[dst..dst + channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 8 * channels..src + 9 * channels],
                        );
                        conv2_blk_grad[dst + channels..dst + 2 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 4 * channels..src + 5 * channels],
                        );
                    }
                }

                let act_blk_grad = &mut activated_block_grad[..blk_len];
                let conv2_in_dim = m_size * channels;
                let conv2_out_dim = m_size * channels;
                crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                    nodes,
                    conv2_in_dim,
                    conv2_out_dim,
                    &conv2_m_fused_vjp[order_idx],
                    conv2_blk_grad,
                    act_blk_grad,
                );

                let conv1_blk_grad = &mut conv1_block_grad_out[..blk_len];
                let act_blk_grad = &activated_block_grad[..blk_len];
                if m_size == 2 {
                    for node in 0..nodes {
                        let blk = node * blk_stride;
                        let conv1_base = node * out_node_stride + 3 * channels;
                        let gate_base = node * gate_node_stride;
                        let full_grad_base = node * m0_out_dim;
                        for ch in 0..channels {
                            let gate1 = gate_sigmoids[gate_base + ch];
                            let gate2 = gate_sigmoids[gate_base + channels + ch];
                            let grad3 = act_blk_grad[blk + ch];
                            let grad7 = act_blk_grad[blk + channels + ch];
                            let grad1 = act_blk_grad[blk + 2 * channels + ch];
                            let grad5 = act_blk_grad[blk + 3 * channels + ch];
                            conv1_blk_grad[blk + ch] = grad3 * gate1;
                            conv1_blk_grad[blk + channels + ch] = grad7 * gate2;
                            conv1_blk_grad[blk + 2 * channels + ch] = grad1 * gate1;
                            conv1_blk_grad[blk + 3 * channels + ch] = grad5 * gate2;
                            conv1_m0_full_grad_out[full_grad_base + ch] += grad3
                                * conv1_out_l_major[conv1_base + ch]
                                + grad1 * conv1_out_l_major[conv1_base + 2 * channels + ch];
                            conv1_m0_full_grad_out[full_grad_base + channels + ch] += grad7
                                * conv1_out_l_major[conv1_base + channels + ch]
                                + grad5 * conv1_out_l_major[conv1_base + 3 * channels + ch];
                        }
                    }
                } else {
                    for node in 0..nodes {
                        let blk = node * blk_stride;
                        let conv1_base = node * out_node_stride + 7 * channels;
                        let gate_base = node * gate_node_stride;
                        let full_grad_base = node * m0_out_dim;
                        for ch in 0..channels {
                            let gate2 = gate_sigmoids[gate_base + channels + ch];
                            let grad8 = act_blk_grad[blk + ch];
                            let grad4 = act_blk_grad[blk + channels + ch];
                            conv1_blk_grad[blk + ch] = grad8 * gate2;
                            conv1_blk_grad[blk + channels + ch] = grad4 * gate2;
                            conv1_m0_full_grad_out[full_grad_base + channels + ch] += grad8
                                * conv1_out_l_major[conv1_base + ch]
                                + grad4 * conv1_out_l_major[conv1_base + channels + ch];
                        }
                    }
                }

                let in_dim = m_size * conv1_in_channels;
                let out_dim_conv1 = m_size * channels;
                let blk_grad_mod_len = nodes * n_sources * conv1_in_channels;
                let conv1_blk_mod = &mut conv1_block_grad_modulated[..blk_grad_mod_len];
                crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                    nodes,
                    in_dim,
                    out_dim_conv1,
                    &conv1_m_fused_vjp[order_idx],
                    conv1_blk_grad,
                    conv1_blk_mod,
                );

                let blk_in_stride = n_sources * conv1_in_channels;
                let conv1_blk_mod = &conv1_block_grad_modulated[..blk_grad_mod_len];
                if m_size == 2 {
                    for node in 0..nodes {
                        let in_base = node * input_node_stride;
                        let rad_base = node * radial_node_stride + radial_offset;
                        let blk_base = node * blk_in_stride;
                        for ch in 0..conv1_in_channels {
                            let r0 = rad_base + ch;
                            let r1 = rad_base + conv1_in_channels + ch;
                            let radial_v0 = conv1_radial[r0];
                            let radial_v1 = conv1_radial[r1];

                            let i3 = in_base + 3 * conv1_in_channels + ch;
                            let g0 = conv1_blk_mod[blk_base + ch];
                            let inp0 = conv1_input_l_major[i3];
                            grad_conv1_input_l_major[i3] = g0 * radial_v0;

                            let i7 = in_base + 7 * conv1_in_channels + ch;
                            let g1 = conv1_blk_mod[blk_base + conv1_in_channels + ch];
                            let inp1 = conv1_input_l_major[i7];
                            grad_conv1_input_l_major[i7] = g1 * radial_v1;

                            let i1 = in_base + conv1_in_channels + ch;
                            let g2 = conv1_blk_mod[blk_base + 2 * conv1_in_channels + ch];
                            let inp2 = conv1_input_l_major[i1];
                            grad_conv1_input_l_major[i1] = g2 * radial_v0;

                            let i5 = in_base + 5 * conv1_in_channels + ch;
                            let g3 = conv1_blk_mod[blk_base + 3 * conv1_in_channels + ch];
                            let inp3 = conv1_input_l_major[i5];
                            grad_conv1_input_l_major[i5] = g3 * radial_v1;

                            grad_conv1_radial[r0] = g0 * inp0 + g2 * inp2;
                            grad_conv1_radial[r1] = g1 * inp1 + g3 * inp3;
                        }
                    }
                } else {
                    for node in 0..nodes {
                        let in_base = node * input_node_stride;
                        let rad_base = node * radial_node_stride + radial_offset;
                        let blk_base = node * blk_in_stride;
                        for ch in 0..conv1_in_channels {
                            let r0 = rad_base + ch;
                            let radial_v0 = conv1_radial[r0];

                            let i8 = in_base + 8 * conv1_in_channels + ch;
                            let g0 = conv1_blk_mod[blk_base + ch];
                            let inp0 = conv1_input_l_major[i8];
                            grad_conv1_input_l_major[i8] = g0 * radial_v0;

                            let i4 = in_base + 4 * conv1_in_channels + ch;
                            let g1 = conv1_blk_mod[blk_base + conv1_in_channels + ch];
                            let inp1 = conv1_input_l_major[i4];
                            grad_conv1_input_l_major[i4] = g1 * radial_v0;

                            grad_conv1_radial[r0] = g0 * inp0 + g1 * inp1;
                        }
                    }
                }

                radial_offset += m_size * conv1_in_channels;
            }
        }

        let stage_start = uma_timing_start(profile_enabled);
        #[cfg(feature = "parallel")]
        if parallel_nodes {
            conv1_m0_full_grad_out
                .par_chunks_mut(m0_out_dim)
                .zip(gate_sigmoids.par_chunks(gate_node_stride))
                .for_each(|(full_grad, gates)| {
                    for ch in 0..channels {
                        let g1 = gates[ch];
                        full_grad[ch] *= g1 * (1.0 - g1);
                        let g2 = gates[channels + ch];
                        full_grad[channels + ch] *= g2 * (1.0 - g2);
                    }
                });
        } else {
            for node in 0..nodes {
                let gate_base = node * gate_node_stride;
                let full_grad_base = node * m0_out_dim;
                for ch in 0..channels {
                    let g1 = gate_sigmoids[gate_base + ch];
                    conv1_m0_full_grad_out[full_grad_base + ch] *= g1 * (1.0 - g1);
                    let g2 = gate_sigmoids[gate_base + channels + ch];
                    conv1_m0_full_grad_out[full_grad_base + channels + ch] *= g2 * (1.0 - g2);
                }
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let gate_base = node * gate_node_stride;
                let full_grad_base = node * m0_out_dim;
                for ch in 0..channels {
                    let g1 = gate_sigmoids[gate_base + ch];
                    conv1_m0_full_grad_out[full_grad_base + ch] *= g1 * (1.0 - g1);
                    let g2 = gate_sigmoids[gate_base + channels + ch];
                    conv1_m0_full_grad_out[full_grad_base + channels + ch] *= g2 * (1.0 - g2);
                }
            }
        }
        trace_uma_stage("f64.so2_vjp.gate_sigmoid_derivative", stage_start);
        if let Some(p) = profile.as_deref_mut() {
            p.gate_sigmoid_derivative.record_optional(stage_start);
        }

        let m0_in_len = 3 * conv1_in_channels;
        let stage_start = uma_timing_start(profile_enabled);
        reset_f64_vec_uninit(conv1_m0_grad_modulated, nodes * m0_in_len);
        uma_dense_vjp_input_rows_write(
            nodes,
            m0_in_len,
            m0_out_dim,
            conv1_m0_weight,
            conv1_m0_full_grad_out,
            conv1_m0_grad_modulated,
        )?;
        trace_uma_stage("f64.so2_vjp.m0_conv1_dense_vjp", stage_start);
        if let Some(p) = profile.as_deref_mut() {
            p.m0_conv1_dense_vjp.record_optional(stage_start);
        }

        let stage_start = uma_timing_start(profile_enabled);
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes() {
            grad_conv1_input_l_major
                .par_chunks_mut(input_node_stride)
                .zip(grad_conv1_radial.par_chunks_mut(radial_node_stride))
                .enumerate()
                .for_each(|(node, (grad_input_node, grad_radial_node))| {
                    let in_base = node * input_node_stride;
                    let rad_base = node * radial_node_stride;
                    let blk_base = node * m0_in_len;
                    for ch in 0..conv1_in_channels {
                        let g0 = conv1_m0_grad_modulated[blk_base + ch];
                        let inp0 = conv1_input_l_major[in_base + ch];
                        let r0 = conv1_radial[rad_base + ch];
                        grad_input_node[ch] = g0 * r0;
                        grad_radial_node[ch] = g0 * inp0;

                        let g1 = conv1_m0_grad_modulated[blk_base + conv1_in_channels + ch];
                        let inp1 = conv1_input_l_major[in_base + 2 * conv1_in_channels + ch];
                        let r1 = conv1_radial[rad_base + conv1_in_channels + ch];
                        grad_input_node[2 * conv1_in_channels + ch] = g1 * r1;
                        grad_radial_node[conv1_in_channels + ch] = g1 * inp1;

                        let g2 = conv1_m0_grad_modulated[blk_base + 2 * conv1_in_channels + ch];
                        let inp2 = conv1_input_l_major[in_base + 6 * conv1_in_channels + ch];
                        let r2 = conv1_radial[rad_base + 2 * conv1_in_channels + ch];
                        grad_input_node[6 * conv1_in_channels + ch] = g2 * r2;
                        grad_radial_node[2 * conv1_in_channels + ch] = g2 * inp2;
                    }
                });
        } else {
            for node in 0..nodes {
                let in_base = node * input_node_stride;
                let rad_base = node * radial_node_stride;
                let blk_base = node * m0_in_len;
                for ch in 0..conv1_in_channels {
                    let g0 = conv1_m0_grad_modulated[blk_base + ch];
                    let inp0 = conv1_input_l_major[in_base + ch];
                    let r0 = conv1_radial[rad_base + ch];
                    grad_conv1_input_l_major[in_base + ch] = g0 * r0;
                    grad_conv1_radial[rad_base + ch] = g0 * inp0;

                    let g1 = conv1_m0_grad_modulated[blk_base + conv1_in_channels + ch];
                    let inp1 = conv1_input_l_major[in_base + 2 * conv1_in_channels + ch];
                    let r1 = conv1_radial[rad_base + conv1_in_channels + ch];
                    grad_conv1_input_l_major[in_base + 2 * conv1_in_channels + ch] = g1 * r1;
                    grad_conv1_radial[rad_base + conv1_in_channels + ch] = g1 * inp1;

                    let g2 = conv1_m0_grad_modulated[blk_base + 2 * conv1_in_channels + ch];
                    let inp2 = conv1_input_l_major[in_base + 6 * conv1_in_channels + ch];
                    let r2 = conv1_radial[rad_base + 2 * conv1_in_channels + ch];
                    grad_conv1_input_l_major[in_base + 6 * conv1_in_channels + ch] = g2 * r2;
                    grad_conv1_radial[rad_base + 2 * conv1_in_channels + ch] = g2 * inp2;
                }
            }
        }
        #[cfg(not(feature = "parallel"))]
        {
            for node in 0..nodes {
                let in_base = node * input_node_stride;
                let rad_base = node * radial_node_stride;
                let blk_base = node * m0_in_len;
                for ch in 0..conv1_in_channels {
                    let g0 = conv1_m0_grad_modulated[blk_base + ch];
                    let inp0 = conv1_input_l_major[in_base + ch];
                    let r0 = conv1_radial[rad_base + ch];
                    grad_conv1_input_l_major[in_base + ch] = g0 * r0;
                    grad_conv1_radial[rad_base + ch] = g0 * inp0;

                    let g1 = conv1_m0_grad_modulated[blk_base + conv1_in_channels + ch];
                    let inp1 = conv1_input_l_major[in_base + 2 * conv1_in_channels + ch];
                    let r1 = conv1_radial[rad_base + conv1_in_channels + ch];
                    grad_conv1_input_l_major[in_base + 2 * conv1_in_channels + ch] = g1 * r1;
                    grad_conv1_radial[rad_base + conv1_in_channels + ch] = g1 * inp1;

                    let g2 = conv1_m0_grad_modulated[blk_base + 2 * conv1_in_channels + ch];
                    let inp2 = conv1_input_l_major[in_base + 6 * conv1_in_channels + ch];
                    let r2 = conv1_radial[rad_base + 2 * conv1_in_channels + ch];
                    grad_conv1_input_l_major[in_base + 6 * conv1_in_channels + ch] = g2 * r2;
                    grad_conv1_radial[rad_base + 2 * conv1_in_channels + ch] = g2 * inp2;
                }
            }
        }
        trace_uma_stage("f64.so2_vjp.m0_radial_vjp", stage_start);
        if let Some(p) = &mut profile {
            p.m0_radial_vjp.record_optional(stage_start);
        }

        Ok(())
    })
}

#[cfg(all(
    feature = "parallel",
    any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )
))]
#[allow(clippy::too_many_arguments, unsafe_code)]
fn uma_so2_conv_l2_m2_orders_forward_parallel_f64(
    nodes: usize,
    conv1_in_channels: usize,
    channels: usize,
    conv1_m_fused_fwd: &[Vec<f64>],
    conv2_m_fused_fwd: &[Vec<f64>],
    input_l_major: &[f64],
    radial: &[f64],
    gate_sigmoids: &[f64],
    conv1_out_l_major: &mut [f64],
    conv2_out_l_major: &mut [f64],
) -> Result<(), ModelError> {
    let radial_offset_1 = 3 * conv1_in_channels;
    let radial_offset_2 = radial_offset_1 + 2 * conv1_in_channels;
    let input_node_stride = 9 * conv1_in_channels;
    let radial_node_stride = 6 * conv1_in_channels;
    let gate_node_stride = 2 * channels;
    let out_node_stride = 9 * channels;

    let conv1_out_addr = conv1_out_l_major.as_mut_ptr() as usize;
    let conv2_out_addr = conv2_out_l_major.as_mut_ptr() as usize;

    let process_order1 = move || -> Result<(), ModelError> {
        let n_sources = 4usize;
        let m_size = 2usize;
        let in_dim = m_size * conv1_in_channels;
        let out_dim = m_size * channels;
        let blk_in_len = nodes * n_sources * conv1_in_channels;
        let blk_out_len = nodes * n_sources * channels;
        let blk_stride = n_sources * channels;
        let blk_in_stride = n_sources * conv1_in_channels;

        UMA_L2_M2_FUSED_F64_ORDER_FWD_SCRATCH.with(|scratch| -> Result<(), ModelError> {
            let mut scratch = scratch.borrow_mut();
            let UmaL2M2FusedF64OrderForwardScratch {
                conv1_block_input,
                conv1_block_out,
                conv2_block_input,
                conv2_block_out,
            } = &mut *scratch;

            reset_f64_vec_uninit(conv1_block_input, blk_in_len);
            let conv1_blk_in = &mut conv1_block_input[..blk_in_len];
            conv1_blk_in
                .par_chunks_mut(blk_in_stride)
                .enumerate()
                .for_each(|(node, block)| {
                    let in_base = node * input_node_stride;
                    let rad_base = node * radial_node_stride + radial_offset_1;
                    for ch in 0..conv1_in_channels {
                        let r0 = radial[rad_base + ch];
                        let r1 = radial[rad_base + conv1_in_channels + ch];
                        block[ch] = input_l_major[in_base + 3 * conv1_in_channels + ch] * r0;
                        block[conv1_in_channels + ch] =
                            input_l_major[in_base + 7 * conv1_in_channels + ch] * r1;
                        block[2 * conv1_in_channels + ch] =
                            input_l_major[in_base + conv1_in_channels + ch] * r0;
                        block[3 * conv1_in_channels + ch] =
                            input_l_major[in_base + 5 * conv1_in_channels + ch] * r1;
                    }
                });

            reset_f64_vec_uninit(conv1_block_out, blk_out_len);
            crate::blas_backend::so2_mconv_forward_set_precomputed_fused(
                nodes,
                in_dim,
                out_dim,
                &conv1_m_fused_fwd[0],
                conv1_blk_in,
                conv1_block_out,
            );

            reset_f64_vec_uninit(conv2_block_input, blk_out_len);
            let conv1_blk_out = &conv1_block_out[..blk_out_len];
            let conv2_blk_in = &mut conv2_block_input[..blk_out_len];
            conv2_blk_in
                .par_chunks_mut(blk_stride)
                .enumerate()
                .for_each(|(node, conv2_row)| {
                    let conv1_out_raw = conv1_out_addr as *mut f64;
                    let blk_base = node * blk_stride;
                    let gate_base = node * gate_node_stride;
                    let conv1_base = node * out_node_stride + 3 * channels;
                    unsafe {
                        std::ptr::copy_nonoverlapping(
                            conv1_blk_out.as_ptr().add(blk_base),
                            conv1_out_raw.add(conv1_base),
                            4 * channels,
                        );
                    }
                    for ch in 0..channels {
                        let gate1 = gate_sigmoids[gate_base + ch];
                        let gate2 = gate_sigmoids[gate_base + channels + ch];
                        let v3 = conv1_blk_out[blk_base + ch];
                        let v7 = conv1_blk_out[blk_base + channels + ch];
                        let v1 = conv1_blk_out[blk_base + 2 * channels + ch];
                        let v5 = conv1_blk_out[blk_base + 3 * channels + ch];
                        conv2_row[ch] = v3 * gate1;
                        conv2_row[channels + ch] = v7 * gate2;
                        conv2_row[2 * channels + ch] = v1 * gate1;
                        conv2_row[3 * channels + ch] = v5 * gate2;
                    }
                });

            reset_f64_vec_uninit(conv2_block_out, blk_out_len);
            crate::blas_backend::so2_mconv_forward_set_precomputed_fused(
                nodes,
                out_dim,
                out_dim,
                &conv2_m_fused_fwd[0],
                conv2_blk_in,
                conv2_block_out,
            );

            {
                (0..nodes).into_par_iter().for_each(|node| {
                    let conv2_out_raw = conv2_out_addr as *mut f64;
                    let dst = node * out_node_stride;
                    let blk = node * blk_stride;
                    unsafe {
                        std::ptr::copy_nonoverlapping(
                            conv2_block_out.as_ptr().add(blk),
                            conv2_out_raw.add(dst + 3 * channels),
                            channels,
                        );
                        std::ptr::copy_nonoverlapping(
                            conv2_block_out.as_ptr().add(blk + channels),
                            conv2_out_raw.add(dst + 7 * channels),
                            channels,
                        );
                        std::ptr::copy_nonoverlapping(
                            conv2_block_out.as_ptr().add(blk + 2 * channels),
                            conv2_out_raw.add(dst + channels),
                            channels,
                        );
                        std::ptr::copy_nonoverlapping(
                            conv2_block_out.as_ptr().add(blk + 3 * channels),
                            conv2_out_raw.add(dst + 5 * channels),
                            channels,
                        );
                    }
                });
            }

            Ok(())
        })
    };

    let process_order2 = move || -> Result<(), ModelError> {
        let n_sources = 2usize;
        let m_size = 1usize;
        let in_dim = m_size * conv1_in_channels;
        let out_dim = m_size * channels;
        let blk_in_len = nodes * n_sources * conv1_in_channels;
        let blk_out_len = nodes * n_sources * channels;
        let blk_stride = n_sources * channels;
        let blk_in_stride = n_sources * conv1_in_channels;

        UMA_L2_M2_FUSED_F64_ORDER2_FWD_SCRATCH.with(|scratch| -> Result<(), ModelError> {
            let mut scratch = scratch.borrow_mut();
            let UmaL2M2FusedF64OrderForwardScratch {
                conv1_block_input,
                conv1_block_out,
                conv2_block_input,
                conv2_block_out,
            } = &mut *scratch;

            reset_f64_vec_uninit(conv1_block_input, blk_in_len);
            let conv1_blk_in = &mut conv1_block_input[..blk_in_len];
            conv1_blk_in
                .par_chunks_mut(blk_in_stride)
                .enumerate()
                .for_each(|(node, block)| {
                    let in_base = node * input_node_stride;
                    let rad_base = node * radial_node_stride + radial_offset_2;
                    for ch in 0..conv1_in_channels {
                        let r0 = radial[rad_base + ch];
                        block[ch] = input_l_major[in_base + 8 * conv1_in_channels + ch] * r0;
                        block[conv1_in_channels + ch] =
                            input_l_major[in_base + 4 * conv1_in_channels + ch] * r0;
                    }
                });

            reset_f64_vec_uninit(conv1_block_out, blk_out_len);
            crate::blas_backend::so2_mconv_forward_set_precomputed_fused(
                nodes,
                in_dim,
                out_dim,
                &conv1_m_fused_fwd[1],
                conv1_blk_in,
                conv1_block_out,
            );

            reset_f64_vec_uninit(conv2_block_input, blk_out_len);
            let conv1_blk_out = &conv1_block_out[..blk_out_len];
            let conv2_blk_in = &mut conv2_block_input[..blk_out_len];
            conv2_blk_in
                .par_chunks_mut(blk_stride)
                .enumerate()
                .for_each(|(node, conv2_row)| {
                    let conv1_out_raw = conv1_out_addr as *mut f64;
                    let blk_base = node * blk_stride;
                    let gate_base = node * gate_node_stride;
                    let conv1_base = node * out_node_stride + 7 * channels;
                    unsafe {
                        std::ptr::copy_nonoverlapping(
                            conv1_blk_out.as_ptr().add(blk_base),
                            conv1_out_raw.add(conv1_base),
                            2 * channels,
                        );
                    }
                    for ch in 0..channels {
                        let gate2 = gate_sigmoids[gate_base + channels + ch];
                        let v8 = conv1_blk_out[blk_base + ch];
                        let v4 = conv1_blk_out[blk_base + channels + ch];
                        conv2_row[ch] = v8 * gate2;
                        conv2_row[channels + ch] = v4 * gate2;
                    }
                });

            reset_f64_vec_uninit(conv2_block_out, blk_out_len);
            crate::blas_backend::so2_mconv_forward_set_precomputed_fused(
                nodes,
                out_dim,
                out_dim,
                &conv2_m_fused_fwd[1],
                conv2_blk_in,
                conv2_block_out,
            );

            {
                (0..nodes).into_par_iter().for_each(|node| {
                    let conv2_out_raw = conv2_out_addr as *mut f64;
                    let dst = node * out_node_stride;
                    let blk = node * blk_stride;
                    unsafe {
                        std::ptr::copy_nonoverlapping(
                            conv2_block_out.as_ptr().add(blk),
                            conv2_out_raw.add(dst + 8 * channels),
                            channels,
                        );
                        std::ptr::copy_nonoverlapping(
                            conv2_block_out.as_ptr().add(blk + channels),
                            conv2_out_raw.add(dst + 4 * channels),
                            channels,
                        );
                    }
                });
            }

            Ok(())
        })
    };

    let (res1, res2) = rayon::join(process_order1, process_order2);
    res1?;
    res2?;
    Ok(())
}

#[cfg(all(
    feature = "parallel",
    any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )
))]
#[allow(clippy::too_many_arguments, unsafe_code)]
fn uma_so2_conv_l2_m2_orders_vjp_parallel_f64(
    nodes: usize,
    conv1_in_channels: usize,
    channels: usize,
    m0_out_dim: usize,
    conv2_m_fused_vjp: &[Vec<f64>],
    conv1_m_fused_vjp: &[Vec<f64>],
    grad_conv2_out_l_major: &[f64],
    conv1_out_l_major: &[f64],
    gate_sigmoids: &[f64],
    conv1_input_l_major: &[f64],
    conv1_radial: &[f64],
    conv1_m0_full_grad_out: &mut [f64],
    order2_m0_gate_grad: &mut [f64],
    grad_conv1_input_l_major: &mut [f64],
    grad_conv1_radial: &mut [f64],
    use_inplace_gate_conv1: bool,
    mut profile: Option<&mut UmaSo2FusedVjpProfile>,
) -> Result<(), ModelError> {
    let radial_offset_1 = 3 * conv1_in_channels;
    let radial_offset_2 = radial_offset_1 + 2 * conv1_in_channels;
    let input_node_stride = 9 * conv1_in_channels;
    let radial_node_stride = 6 * conv1_in_channels;
    let out_node_stride = 9 * channels;
    let gate_node_stride = 2 * channels;

    let grad_input_addr = grad_conv1_input_l_major.as_mut_ptr() as usize;
    let grad_radial_addr = grad_conv1_radial.as_mut_ptr() as usize;
    let conv1_m0_full_grad_addr = conv1_m0_full_grad_out.as_mut_ptr() as usize;
    debug_assert!(order2_m0_gate_grad.len() >= nodes * channels);
    let order2_m0_gate_grad_addr = order2_m0_gate_grad.as_mut_ptr() as usize;
    let profile_enabled = profile.is_some();

    let process_order1 = move || -> Result<UmaSo2FusedVjpOrderProfile, ModelError> {
        let mut order_profile = UmaSo2FusedVjpOrderProfile::default();
        let n_sources = 4usize;
        let m_size = 2usize;
        let blk_len = nodes * n_sources * channels;
        let blk_stride = n_sources * channels;
        let conv2_in_dim = m_size * channels;
        let conv2_out_dim = m_size * channels;

        UMA_L2_M2_FUSED_F64_ORDER_VJP_SCRATCH.with(
            |scratch| -> Result<UmaSo2FusedVjpOrderProfile, ModelError> {
                let mut scratch = scratch.borrow_mut();
                let UmaL2M2FusedF64OrderVjpScratch {
                    conv2_block_grad_out,
                    activated_block_grad,
                    conv1_block_grad_out,
                    conv1_block_grad_modulated,
                } = &mut *scratch;

                let stage_start = uma_timing_start(profile_enabled);
                reset_f64_vec_uninit(conv2_block_grad_out, blk_len);
                conv2_block_grad_out
                    .par_chunks_mut(blk_stride)
                    .enumerate()
                    .for_each(|(node, row)| {
                        let src = node * out_node_stride;
                        row[..channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 3 * channels..src + 4 * channels],
                        );
                        row[channels..2 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 7 * channels..src + 8 * channels],
                        );
                        row[2 * channels..3 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + channels..src + 2 * channels],
                        );
                        row[3 * channels..4 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 5 * channels..src + 6 * channels],
                        );
                    });
                trace_uma_stage("f64.so2_vjp.order1.gather_conv2", stage_start);
                order_profile.gather_conv2.record_optional(stage_start);

                let stage_start = uma_timing_start(profile_enabled);
                reset_f64_vec_uninit(activated_block_grad, blk_len);
                crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                    nodes,
                    conv2_in_dim,
                    conv2_out_dim,
                    &conv2_m_fused_vjp[0],
                    conv2_block_grad_out,
                    activated_block_grad,
                );
                trace_uma_stage("f64.so2_vjp.order1.conv2_vjp", stage_start);
                order_profile.conv2_vjp.record_optional(stage_start);

                let m0_grad_raw = conv1_m0_full_grad_addr as *mut f64;
                let in_dim = m_size * conv1_in_channels;
                let out_dim_conv1 = m_size * channels;
                let blk_grad_mod_len = nodes * n_sources * conv1_in_channels;
                reset_f64_vec_uninit(conv1_block_grad_modulated, blk_grad_mod_len);
                if use_inplace_gate_conv1 {
                    let stage_start = uma_timing_start(profile_enabled);
                    let conv1_blk_grad = &mut activated_block_grad[..blk_len];
                    for node in 0..nodes {
                        let blk = node * blk_stride;
                        let conv1_base = node * out_node_stride + 3 * channels;
                        let gate_base = node * gate_node_stride;
                        let full_grad_base = node * m0_out_dim;
                        for ch in 0..channels {
                            let gate1 = gate_sigmoids[gate_base + ch];
                            let gate2 = gate_sigmoids[gate_base + channels + ch];
                            let grad3 = conv1_blk_grad[blk + ch];
                            let grad7 = conv1_blk_grad[blk + channels + ch];
                            let grad1 = conv1_blk_grad[blk + 2 * channels + ch];
                            let grad5 = conv1_blk_grad[blk + 3 * channels + ch];
                            conv1_blk_grad[blk + ch] = grad3 * gate1;
                            conv1_blk_grad[blk + channels + ch] = grad7 * gate2;
                            conv1_blk_grad[blk + 2 * channels + ch] = grad1 * gate1;
                            conv1_blk_grad[blk + 3 * channels + ch] = grad5 * gate2;
                            unsafe {
                                *m0_grad_raw.add(full_grad_base + ch) += grad3
                                    * conv1_out_l_major[conv1_base + ch]
                                    + grad1 * conv1_out_l_major[conv1_base + 2 * channels + ch];
                                *m0_grad_raw.add(full_grad_base + channels + ch) += grad7
                                    * conv1_out_l_major[conv1_base + channels + ch]
                                    + grad5 * conv1_out_l_major[conv1_base + 3 * channels + ch];
                            }
                        }
                    }
                    crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                        nodes,
                        in_dim,
                        out_dim_conv1,
                        &conv1_m_fused_vjp[0],
                        conv1_blk_grad,
                        conv1_block_grad_modulated,
                    );
                    trace_uma_stage("f64.so2_vjp.order1.gate_conv1_stack_vjp", stage_start);
                    order_profile
                        .gate_conv1_stack_vjp
                        .record_optional(stage_start);
                } else {
                    let stage_start = uma_timing_start(profile_enabled);
                    reset_f64_vec_uninit(conv1_block_grad_out, blk_len);
                    let act_blk_grad = &activated_block_grad[..blk_len];
                    let conv1_blk_grad = &mut conv1_block_grad_out[..blk_len];
                    for node in 0..nodes {
                        let blk = node * blk_stride;
                        let conv1_base = node * out_node_stride + 3 * channels;
                        let gate_base = node * gate_node_stride;
                        let full_grad_base = node * m0_out_dim;
                        for ch in 0..channels {
                            let gate1 = gate_sigmoids[gate_base + ch];
                            let gate2 = gate_sigmoids[gate_base + channels + ch];
                            let grad3 = act_blk_grad[blk + ch];
                            let grad7 = act_blk_grad[blk + channels + ch];
                            let grad1 = act_blk_grad[blk + 2 * channels + ch];
                            let grad5 = act_blk_grad[blk + 3 * channels + ch];
                            conv1_blk_grad[blk + ch] = grad3 * gate1;
                            conv1_blk_grad[blk + channels + ch] = grad7 * gate2;
                            conv1_blk_grad[blk + 2 * channels + ch] = grad1 * gate1;
                            conv1_blk_grad[blk + 3 * channels + ch] = grad5 * gate2;
                            unsafe {
                                *m0_grad_raw.add(full_grad_base + ch) += grad3
                                    * conv1_out_l_major[conv1_base + ch]
                                    + grad1 * conv1_out_l_major[conv1_base + 2 * channels + ch];
                                *m0_grad_raw.add(full_grad_base + channels + ch) += grad7
                                    * conv1_out_l_major[conv1_base + channels + ch]
                                    + grad5 * conv1_out_l_major[conv1_base + 3 * channels + ch];
                            }
                        }
                    }
                    trace_uma_stage("f64.so2_vjp.order1.gate_vjp", stage_start);
                    order_profile.gate_vjp.record_optional(stage_start);

                    let stage_start = uma_timing_start(profile_enabled);
                    crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                        nodes,
                        in_dim,
                        out_dim_conv1,
                        &conv1_m_fused_vjp[0],
                        conv1_blk_grad,
                        conv1_block_grad_modulated,
                    );
                    trace_uma_stage("f64.so2_vjp.order1.conv1_vjp", stage_start);
                    order_profile.conv1_vjp.record_optional(stage_start);
                }

                let stage_start = uma_timing_start(profile_enabled);
                let blk_in_stride = n_sources * conv1_in_channels;
                if rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes() {
                    (0..nodes).into_par_iter().for_each(|node| {
                        let grad_input_raw = grad_input_addr as *mut f64;
                        let grad_radial_raw = grad_radial_addr as *mut f64;
                        let in_base = node * input_node_stride;
                        let rad_base = node * radial_node_stride + radial_offset_1;
                        let blk_base = node * blk_in_stride;
                        for ch in 0..conv1_in_channels {
                            let radial_v0 = conv1_radial[rad_base + ch];
                            let radial_v1 = conv1_radial[rad_base + conv1_in_channels + ch];
                            let g0 = conv1_block_grad_modulated[blk_base + ch];
                            let g1 = conv1_block_grad_modulated[blk_base + conv1_in_channels + ch];
                            let g2 =
                                conv1_block_grad_modulated[blk_base + 2 * conv1_in_channels + ch];
                            let g3 =
                                conv1_block_grad_modulated[blk_base + 3 * conv1_in_channels + ch];
                            let inp0 = conv1_input_l_major[in_base + 3 * conv1_in_channels + ch];
                            let inp1 = conv1_input_l_major[in_base + 7 * conv1_in_channels + ch];
                            let inp2 = conv1_input_l_major[in_base + conv1_in_channels + ch];
                            let inp3 = conv1_input_l_major[in_base + 5 * conv1_in_channels + ch];
                            unsafe {
                                *grad_input_raw.add(in_base + 3 * conv1_in_channels + ch) =
                                    g0 * radial_v0;
                                *grad_input_raw.add(in_base + 7 * conv1_in_channels + ch) =
                                    g1 * radial_v1;
                                *grad_input_raw.add(in_base + conv1_in_channels + ch) =
                                    g2 * radial_v0;
                                *grad_input_raw.add(in_base + 5 * conv1_in_channels + ch) =
                                    g3 * radial_v1;
                                *grad_radial_raw.add(rad_base + ch) = g0 * inp0 + g2 * inp2;
                                *grad_radial_raw.add(rad_base + conv1_in_channels + ch) =
                                    g1 * inp1 + g3 * inp3;
                            }
                        }
                    });
                } else {
                    let grad_input_raw = grad_input_addr as *mut f64;
                    let grad_radial_raw = grad_radial_addr as *mut f64;
                    for node in 0..nodes {
                        let in_base = node * input_node_stride;
                        let rad_base = node * radial_node_stride + radial_offset_1;
                        let blk_base = node * blk_in_stride;
                        for ch in 0..conv1_in_channels {
                            let radial_v0 = conv1_radial[rad_base + ch];
                            let radial_v1 = conv1_radial[rad_base + conv1_in_channels + ch];
                            let g0 = conv1_block_grad_modulated[blk_base + ch];
                            let g1 = conv1_block_grad_modulated[blk_base + conv1_in_channels + ch];
                            let g2 =
                                conv1_block_grad_modulated[blk_base + 2 * conv1_in_channels + ch];
                            let g3 =
                                conv1_block_grad_modulated[blk_base + 3 * conv1_in_channels + ch];
                            let inp0 = conv1_input_l_major[in_base + 3 * conv1_in_channels + ch];
                            let inp1 = conv1_input_l_major[in_base + 7 * conv1_in_channels + ch];
                            let inp2 = conv1_input_l_major[in_base + conv1_in_channels + ch];
                            let inp3 = conv1_input_l_major[in_base + 5 * conv1_in_channels + ch];
                            unsafe {
                                *grad_input_raw.add(in_base + 3 * conv1_in_channels + ch) =
                                    g0 * radial_v0;
                                *grad_input_raw.add(in_base + 7 * conv1_in_channels + ch) =
                                    g1 * radial_v1;
                                *grad_input_raw.add(in_base + conv1_in_channels + ch) =
                                    g2 * radial_v0;
                                *grad_input_raw.add(in_base + 5 * conv1_in_channels + ch) =
                                    g3 * radial_v1;
                                *grad_radial_raw.add(rad_base + ch) = g0 * inp0 + g2 * inp2;
                                *grad_radial_raw.add(rad_base + conv1_in_channels + ch) =
                                    g1 * inp1 + g3 * inp3;
                            }
                        }
                    }
                }
                trace_uma_stage("f64.so2_vjp.order1.radial_vjp", stage_start);
                order_profile.radial_vjp.record_optional(stage_start);

                Ok(order_profile)
            },
        )
    };

    let process_order2 = move || -> Result<UmaSo2FusedVjpOrderProfile, ModelError> {
        let mut order_profile = UmaSo2FusedVjpOrderProfile::default();
        let n_sources = 2usize;
        let m_size = 1usize;
        let blk_len = nodes * n_sources * channels;
        let blk_stride = n_sources * channels;
        let conv2_in_dim = m_size * channels;
        let conv2_out_dim = m_size * channels;

        UMA_L2_M2_FUSED_F64_ORDER2_VJP_SCRATCH.with(
            |scratch| -> Result<UmaSo2FusedVjpOrderProfile, ModelError> {
                let mut scratch = scratch.borrow_mut();
                let UmaL2M2FusedF64OrderVjpScratch {
                    conv2_block_grad_out,
                    activated_block_grad,
                    conv1_block_grad_out,
                    conv1_block_grad_modulated,
                } = &mut *scratch;

                let stage_start = uma_timing_start(profile_enabled);
                reset_f64_vec_uninit(conv2_block_grad_out, blk_len);
                conv2_block_grad_out
                    .par_chunks_mut(blk_stride)
                    .enumerate()
                    .for_each(|(node, row)| {
                        let src = node * out_node_stride;
                        row[..channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 8 * channels..src + 9 * channels],
                        );
                        row[channels..2 * channels].copy_from_slice(
                            &grad_conv2_out_l_major[src + 4 * channels..src + 5 * channels],
                        );
                    });
                trace_uma_stage("f64.so2_vjp.order2.gather_conv2", stage_start);
                order_profile.gather_conv2.record_optional(stage_start);

                let stage_start = uma_timing_start(profile_enabled);
                reset_f64_vec_uninit(activated_block_grad, blk_len);
                crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                    nodes,
                    conv2_in_dim,
                    conv2_out_dim,
                    &conv2_m_fused_vjp[1],
                    conv2_block_grad_out,
                    activated_block_grad,
                );
                trace_uma_stage("f64.so2_vjp.order2.conv2_vjp", stage_start);
                order_profile.conv2_vjp.record_optional(stage_start);

                let order2_m0_gate_raw = order2_m0_gate_grad_addr as *mut f64;
                let in_dim = m_size * conv1_in_channels;
                let out_dim_conv1 = m_size * channels;
                let blk_grad_mod_len = nodes * n_sources * conv1_in_channels;
                reset_f64_vec_uninit(conv1_block_grad_modulated, blk_grad_mod_len);
                if use_inplace_gate_conv1 {
                    let stage_start = uma_timing_start(profile_enabled);
                    let conv1_blk_grad = &mut activated_block_grad[..blk_len];
                    for node in 0..nodes {
                        let blk = node * blk_stride;
                        let conv1_base = node * out_node_stride + 7 * channels;
                        let gate_base = node * gate_node_stride;
                        let gate_grad_base = node * channels;
                        for ch in 0..channels {
                            let gate2 = gate_sigmoids[gate_base + channels + ch];
                            let grad8 = conv1_blk_grad[blk + ch];
                            let grad4 = conv1_blk_grad[blk + channels + ch];
                            conv1_blk_grad[blk + ch] = grad8 * gate2;
                            conv1_blk_grad[blk + channels + ch] = grad4 * gate2;
                            unsafe {
                                *order2_m0_gate_raw.add(gate_grad_base + ch) = grad8
                                    * conv1_out_l_major[conv1_base + ch]
                                    + grad4 * conv1_out_l_major[conv1_base + channels + ch];
                            }
                        }
                    }
                    crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                        nodes,
                        in_dim,
                        out_dim_conv1,
                        &conv1_m_fused_vjp[1],
                        conv1_blk_grad,
                        conv1_block_grad_modulated,
                    );
                    trace_uma_stage("f64.so2_vjp.order2.gate_conv1_stack_vjp", stage_start);
                    order_profile
                        .gate_conv1_stack_vjp
                        .record_optional(stage_start);
                } else {
                    let stage_start = uma_timing_start(profile_enabled);
                    reset_f64_vec_uninit(conv1_block_grad_out, blk_len);
                    let act_blk_grad = &activated_block_grad[..blk_len];
                    let conv1_blk_grad = &mut conv1_block_grad_out[..blk_len];
                    for node in 0..nodes {
                        let blk = node * blk_stride;
                        let conv1_base = node * out_node_stride + 7 * channels;
                        let gate_base = node * gate_node_stride;
                        let gate_grad_base = node * channels;
                        for ch in 0..channels {
                            let gate2 = gate_sigmoids[gate_base + channels + ch];
                            let grad8 = act_blk_grad[blk + ch];
                            let grad4 = act_blk_grad[blk + channels + ch];
                            conv1_blk_grad[blk + ch] = grad8 * gate2;
                            conv1_blk_grad[blk + channels + ch] = grad4 * gate2;
                            unsafe {
                                *order2_m0_gate_raw.add(gate_grad_base + ch) = grad8
                                    * conv1_out_l_major[conv1_base + ch]
                                    + grad4 * conv1_out_l_major[conv1_base + channels + ch];
                            }
                        }
                    }
                    trace_uma_stage("f64.so2_vjp.order2.gate_vjp", stage_start);
                    order_profile.gate_vjp.record_optional(stage_start);

                    let stage_start = uma_timing_start(profile_enabled);
                    crate::blas_backend::so2_mconv_vjp_input_write_precomputed_fused(
                        nodes,
                        in_dim,
                        out_dim_conv1,
                        &conv1_m_fused_vjp[1],
                        conv1_blk_grad,
                        conv1_block_grad_modulated,
                    );
                    trace_uma_stage("f64.so2_vjp.order2.conv1_vjp", stage_start);
                    order_profile.conv1_vjp.record_optional(stage_start);
                }

                let stage_start = uma_timing_start(profile_enabled);
                let blk_in_stride = n_sources * conv1_in_channels;
                if rayon::current_num_threads() > 1 && nodes >= uma_so2_parallel_min_nodes() {
                    (0..nodes).into_par_iter().for_each(|node| {
                        let grad_input_raw = grad_input_addr as *mut f64;
                        let grad_radial_raw = grad_radial_addr as *mut f64;
                        let in_base = node * input_node_stride;
                        let rad_base = node * radial_node_stride + radial_offset_2;
                        let blk_base = node * blk_in_stride;
                        for ch in 0..conv1_in_channels {
                            let radial_v0 = conv1_radial[rad_base + ch];
                            let g0 = conv1_block_grad_modulated[blk_base + ch];
                            let g1 = conv1_block_grad_modulated[blk_base + conv1_in_channels + ch];
                            let inp0 = conv1_input_l_major[in_base + 8 * conv1_in_channels + ch];
                            let inp1 = conv1_input_l_major[in_base + 4 * conv1_in_channels + ch];
                            unsafe {
                                *grad_input_raw.add(in_base + 8 * conv1_in_channels + ch) =
                                    g0 * radial_v0;
                                *grad_input_raw.add(in_base + 4 * conv1_in_channels + ch) =
                                    g1 * radial_v0;
                                *grad_radial_raw.add(rad_base + ch) = g0 * inp0 + g1 * inp1;
                            }
                        }
                    });
                } else {
                    let grad_input_raw = grad_input_addr as *mut f64;
                    let grad_radial_raw = grad_radial_addr as *mut f64;
                    for node in 0..nodes {
                        let in_base = node * input_node_stride;
                        let rad_base = node * radial_node_stride + radial_offset_2;
                        let blk_base = node * blk_in_stride;
                        for ch in 0..conv1_in_channels {
                            let radial_v0 = conv1_radial[rad_base + ch];
                            let g0 = conv1_block_grad_modulated[blk_base + ch];
                            let g1 = conv1_block_grad_modulated[blk_base + conv1_in_channels + ch];
                            let inp0 = conv1_input_l_major[in_base + 8 * conv1_in_channels + ch];
                            let inp1 = conv1_input_l_major[in_base + 4 * conv1_in_channels + ch];
                            unsafe {
                                *grad_input_raw.add(in_base + 8 * conv1_in_channels + ch) =
                                    g0 * radial_v0;
                                *grad_input_raw.add(in_base + 4 * conv1_in_channels + ch) =
                                    g1 * radial_v0;
                                *grad_radial_raw.add(rad_base + ch) = g0 * inp0 + g1 * inp1;
                            }
                        }
                    }
                }
                trace_uma_stage("f64.so2_vjp.order2.radial_vjp", stage_start);
                order_profile.radial_vjp.record_optional(stage_start);

                Ok(order_profile)
            },
        )
    };

    let (res1, res2) = rayon::join(process_order1, process_order2);
    let order1_profile = res1?;
    let order2_profile = res2?;
    if let Some(p) = profile.as_deref_mut() {
        p.order1.merge_from(&order1_profile);
        p.order2.merge_from(&order2_profile);
    }

    let stage_start = uma_timing_start(profile_enabled);
    for node in 0..nodes {
        let full_grad_base = node * m0_out_dim + channels;
        let gate_grad_base = node * channels;
        for ch in 0..channels {
            conv1_m0_full_grad_out[full_grad_base + ch] += order2_m0_gate_grad[gate_grad_base + ch];
        }
    }
    trace_uma_stage("f64.so2_vjp.order2_m0_gate_accum", stage_start);
    if let Some(p) = &mut profile {
        p.order2_m0_gate_accum.record_optional(stage_start);
    }

    Ok(())
}

// ──────────────────────────────────────────────────────────────────────────────
// f32 fused UMA l=2/m=2 SO2 forward and VJP
//
// These mirror `fairchem_esen_so2_convolution_forward_l2_m2_radial_gate_conv2_with_fused_m_weights`
// and its VJP counterpart (both f64, in e3nn-core/src/so2.rs) but:
//   • work on f32 data
//   • use the precomputed fused SGEMM weights already stored in
//     `UmaMixedSo2WeightsF32::m_fused_weights_fwd / _vjp`
//   • eliminate all per-call Vec allocation via thread-local scratch buffers
//
// Source index constants (mirror L2_M2_*_L_MAJOR_SOURCES in so2.rs):
//   ORDER0 = [0, 2, 6]  (3 sources → m=0)
//   ORDER1 = [3, 7, 1, 5] (4 sources → m=±1)
//   ORDER2 = [8, 4]     (2 sources → m=±2)
// ──────────────────────────────────────────────────────────────────────────────

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[derive(Default)]
struct UmaL2M2FusedF64ForwardScratch {
    conv1_m0_input: Vec<f64>,
    conv1_m0_dense_out: Vec<f64>,
    conv2_m0_input: Vec<f64>,
    conv2_m0_out: Vec<f64>,
    conv1_block_input: Vec<f64>,
    conv1_block_out: Vec<f64>,
    conv2_block_input: Vec<f64>,
    conv2_block_out: Vec<f64>,
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[derive(Default)]
#[allow(dead_code)]
struct UmaL2M2FusedF64OrderForwardScratch {
    conv1_block_input: Vec<f64>,
    conv1_block_out: Vec<f64>,
    conv2_block_input: Vec<f64>,
    conv2_block_out: Vec<f64>,
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[derive(Default)]
struct UmaL2M2FusedF64VjpScratch {
    conv1_m0_full_grad_out: Vec<f64>,
    conv2_m0_grad_out: Vec<f64>,
    activated_m0_grad: Vec<f64>,
    conv2_block_grad_out: Vec<f64>,
    activated_block_grad: Vec<f64>,
    conv1_block_grad_out: Vec<f64>,
    conv1_block_grad_modulated: Vec<f64>,
    order2_m0_gate_grad: Vec<f64>,
    conv1_m0_grad_modulated: Vec<f64>,
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[derive(Default)]
#[allow(dead_code)]
struct UmaL2M2FusedF64OrderVjpScratch {
    conv2_block_grad_out: Vec<f64>,
    activated_block_grad: Vec<f64>,
    conv1_block_grad_out: Vec<f64>,
    conv1_block_grad_modulated: Vec<f64>,
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
std::thread_local! {
    static UMA_L2_M2_FUSED_F64_FWD_SCRATCH: std::cell::RefCell<UmaL2M2FusedF64ForwardScratch> =
        std::cell::RefCell::new(UmaL2M2FusedF64ForwardScratch::default());
    static UMA_L2_M2_FUSED_F64_VJP_SCRATCH: std::cell::RefCell<UmaL2M2FusedF64VjpScratch> =
        std::cell::RefCell::new(UmaL2M2FusedF64VjpScratch::default());
    // ORDER1 uses these; ORDER2 uses the *_ORDER2_* cells below. Two distinct
    // RefCells per (precision, fwd/vjp) so that the two rayon::join closures
    // never borrow the SAME thread-local on the SAME work-stealing worker while
    // one of them is parked inside its nested par-region (fixes the
    // 'already borrowed: BorrowMutError' double-borrow panic; PR #139 issue B1).
    static UMA_L2_M2_FUSED_F64_ORDER_FWD_SCRATCH: std::cell::RefCell<UmaL2M2FusedF64OrderForwardScratch> =
        std::cell::RefCell::new(UmaL2M2FusedF64OrderForwardScratch::default());
    static UMA_L2_M2_FUSED_F64_ORDER2_FWD_SCRATCH: std::cell::RefCell<UmaL2M2FusedF64OrderForwardScratch> =
        std::cell::RefCell::new(UmaL2M2FusedF64OrderForwardScratch::default());
    static UMA_L2_M2_FUSED_F64_ORDER_VJP_SCRATCH: std::cell::RefCell<UmaL2M2FusedF64OrderVjpScratch> =
        std::cell::RefCell::new(UmaL2M2FusedF64OrderVjpScratch::default());
    static UMA_L2_M2_FUSED_F64_ORDER2_VJP_SCRATCH: std::cell::RefCell<UmaL2M2FusedF64OrderVjpScratch> =
        std::cell::RefCell::new(UmaL2M2FusedF64OrderVjpScratch::default());
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(
        any(feature = "intel-mkl", feature = "openblas"),
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[allow(clippy::uninit_vec, unsafe_code)]
#[inline(always)]
fn reset_f64_vec_uninit(v: &mut Vec<f64>, len: usize) {
    if v.len() != len {
        if v.capacity() < len {
            v.reserve(len - v.len());
        }
        // Invariant: callers use this only for scratch buffers whose active
        // range is fully overwritten, or explicitly filled, before any read.
        unsafe {
            v.set_len(len);
        }
    }
}

