    let channels = config.channels();
    let input_coefficients = config.input_coefficients();
    let output_coefficients = config.output_coefficients();
    if output_coefficients <= 7 {
        return Err(invalid_manifest(format!(
            "UMA m0/order1 SO2 prepack requires at least 8 output coefficients, got {output_coefficients}"
        )));
    }
