#[cfg(all(
    target_arch = "aarch64",
    target_os = "linux",
    llmlip_aarch64_sve_kernels
))]
#[inline(always)]
fn uma_strided_required_len(nodes: usize, stride: usize, row_width: usize) -> Option<usize> {
    if nodes == 0 {
        return Some(0);
    }
    nodes
        .checked_sub(1)?
        .checked_mul(stride)?
        .checked_add(row_width)
}

