#[inline(always)]
fn uma_f32_so3_matrix_vjp_sve_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        if !uma_f32_sve_enabled() || env::var_os("LLMLIP_UMA_DISABLE_SO3_MATRIX_VJP_SVE").is_some()
        {
            return false;
        }

        !matches!(
            env::var("LLMLIP_UMA_ENABLE_SO3_MATRIX_VJP_SVE")
                .ok()
                .as_deref(),
            Some("0" | "false" | "FALSE" | "no" | "NO" | "off" | "OFF")
        )
    })
}

