#[cfg(all(
    target_arch = "aarch64",
    target_os = "linux",
    llmlip_aarch64_sve_kernels
))]
#[inline]
#[allow(unsafe_code)]
fn uma_so3_vjp_matrix_9x9_sve_f32(
    items: usize,
    channels: usize,
    input: &[f32],
    grad_out: &[f32],
    grad_matrix: &mut [f64],
    accumulate: bool,
) -> bool {
    if !uma_f32_so3_matrix_vjp_sve_enabled() || channels == 0 {
        return false;
    }
    let Some(row_width) = 9usize.checked_mul(channels) else {
        return false;
    };
    let Some(input_len) = items.checked_mul(row_width) else {
        return false;
    };
    let Some(matrix_len) = items.checked_mul(81) else {
        return false;
    };
    if input.len() < input_len || grad_out.len() < input_len || grad_matrix.len() < matrix_len {
        return false;
    }
    let accumulate_flag = i32::from(accumulate);

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && items >= 512 {
        let threads = rayon::current_num_threads().max(1);
        let chunk_items = items.div_ceil(threads * 4).max(1);
        let matrix_chunk_len = 81 * chunk_items;
        let input_chunk_len = row_width * chunk_items;
        grad_matrix[..matrix_len]
            .par_chunks_mut(matrix_chunk_len)
            .enumerate()
            .for_each(|(chunk_index, matrix_chunk)| {
                let chunk_items_actual = matrix_chunk.len() / 81;
                let input_offset = chunk_index * input_chunk_len;
                unsafe {
                    llmlip_uma_so3_vjp_matrix_9x9_sve_f32(
                        chunk_items_actual,
                        channels,
                        input.as_ptr().add(input_offset),
                        grad_out.as_ptr().add(input_offset),
                        matrix_chunk.as_mut_ptr(),
                        accumulate_flag,
                    );
                }
            });
        return true;
    }

    unsafe {
        llmlip_uma_so3_vjp_matrix_9x9_sve_f32(
            items,
            channels,
            input.as_ptr(),
            grad_out.as_ptr(),
            grad_matrix.as_mut_ptr(),
            accumulate_flag,
        );
    }
    true
}

