fn uma_so3_vjp_matrix_9x9_order_packed_f32(
    items: usize,
    channels: usize,
    input: &[f32],
    grad_out: &[f32],
    grad_matrix: &mut [f64],
    accumulate: bool,
) -> Result<(), ModelError> {
    let row_width = 9usize
        .checked_mul(channels)
        .ok_or_else(|| invalid_manifest("UMA order-packed SO3 VJP row width overflows"))?;
    let input_len = items
        .checked_mul(row_width)
        .ok_or_else(|| invalid_manifest("UMA order-packed SO3 VJP input length overflows"))?;
    let matrix_len = items
        .checked_mul(UMA_BASIS_DIM * UMA_BASIS_DIM)
        .ok_or_else(|| invalid_manifest("UMA order-packed SO3 VJP matrix length overflows"))?;
    check_len("UMA order-packed SO3 VJP input", input_len, input.len())?;
    check_len(
        "UMA order-packed SO3 VJP grad_out",
        input_len,
        grad_out.len(),
    )?;
    check_len(
        "UMA order-packed SO3 VJP grad_matrix",
        matrix_len,
        grad_matrix.len(),
    )?;

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && items >= 512 {
        grad_matrix[..matrix_len]
            .par_chunks_mut(UMA_BASIS_DIM * UMA_BASIS_DIM)
            .enumerate()
            .for_each(|(item, matrix_item)| {
                let input_item = &input[item * row_width..item * row_width + row_width];
                let grad_out_item = &grad_out[item * row_width..item * row_width + row_width];
                for out_coeff in 0..UMA_BASIS_DIM {
                    let grad_out_row =
                        &grad_out_item[out_coeff * channels..out_coeff * channels + channels];
                    let matrix_row = &mut matrix_item
                        [out_coeff * UMA_BASIS_DIM..(out_coeff + 1) * UMA_BASIS_DIM];
                    if !accumulate {
                        matrix_row.fill(0.0);
                    }
                    for (packed_coeff, &l_major_coeff) in
                        UMA_SO2_ORDER_PACKED_TO_L_MAJOR.iter().enumerate()
                    {
                        let input_row = &input_item
                            [packed_coeff * channels..packed_coeff * channels + channels];
                        let mut dot = 0.0_f32;
                        for ch in 0..channels {
                            dot += grad_out_row[ch] * input_row[ch];
                        }
                        if accumulate {
                            matrix_row[l_major_coeff] += dot as f64;
                        } else {
                            matrix_row[l_major_coeff] = dot as f64;
                        }
                    }
                }
            });
        return Ok(());
    }

    for item in 0..items {
        let input_item = &input[item * row_width..item * row_width + row_width];
        let grad_out_item = &grad_out[item * row_width..item * row_width + row_width];
        let matrix_item = &mut grad_matrix
            [item * UMA_BASIS_DIM * UMA_BASIS_DIM..(item + 1) * UMA_BASIS_DIM * UMA_BASIS_DIM];
        for out_coeff in 0..UMA_BASIS_DIM {
            let grad_out_row =
                &grad_out_item[out_coeff * channels..out_coeff * channels + channels];
            let matrix_row =
                &mut matrix_item[out_coeff * UMA_BASIS_DIM..(out_coeff + 1) * UMA_BASIS_DIM];
            if !accumulate {
                matrix_row.fill(0.0);
            }
            for (packed_coeff, &l_major_coeff) in UMA_SO2_ORDER_PACKED_TO_L_MAJOR.iter().enumerate()
            {
                let input_row =
                    &input_item[packed_coeff * channels..packed_coeff * channels + channels];
                let mut dot = 0.0_f32;
                for ch in 0..channels {
                    dot += grad_out_row[ch] * input_row[ch];
                }
                if accumulate {
                    matrix_row[l_major_coeff] += dot as f64;
                } else {
                    matrix_row[l_major_coeff] = dot as f64;
                }
            }
        }
    }
    Ok(())
}

