const UMA_SO3_INPUT_VJP_SVE_MIN_ITEMS: usize = 512;

#[cfg(all(
    target_arch = "aarch64",
    target_os = "linux",
    llmlip_aarch64_sve_kernels
))]
#[inline]
#[allow(unsafe_code)]
fn uma_so3_vjp_input_write_9x9_sve_f32(
    items: usize,
    channels: usize,
    matrix: &[f32],
    grad_out: &[f32],
    grad_input: &mut [f32],
) -> bool {
    if !uma_f32_so3_input_vjp_sve_enabled()
        || items < UMA_SO3_INPUT_VJP_SVE_MIN_ITEMS
        || channels == 0
    {
        return false;
    }
    let Some(row_width) = 9usize.checked_mul(channels) else {
        return false;
    };
    let Some(feature_len) = items.checked_mul(row_width) else {
        return false;
    };
    let Some(matrix_len) = items.checked_mul(81) else {
        return false;
    };
    if matrix.len() < matrix_len || grad_out.len() < feature_len || grad_input.len() < feature_len {
        return false;
    }

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 {
        let threads = rayon::current_num_threads().max(1);
        let chunk_items = items.div_ceil(threads * 4).max(1);
        let feature_chunk_len = row_width * chunk_items;
        grad_input[..feature_len]
            .par_chunks_mut(feature_chunk_len)
            .enumerate()
            .for_each(|(chunk_index, grad_input_chunk)| {
                let chunk_items_actual = grad_input_chunk.len() / row_width;
                let item_start = chunk_index * chunk_items;
                unsafe {
                    llmlip_uma_so3_vjp_input_write_9x9_sve_f32(
                        chunk_items_actual,
                        channels,
                        matrix.as_ptr().add(item_start * 81),
                        grad_out.as_ptr().add(item_start * row_width),
                        grad_input_chunk.as_mut_ptr(),
                    );
                }
            });
        return true;
    }

    unsafe {
        llmlip_uma_so3_vjp_input_write_9x9_sve_f32(
            items,
            channels,
            matrix.as_ptr(),
            grad_out.as_ptr(),
            grad_input.as_mut_ptr(),
        );
    }
    true
}

