#[cfg(all(
    feature = "parallel",
    target_arch = "aarch64",
    target_os = "linux",
    llmlip_aarch64_sve_kernels
))]
#[allow(clippy::too_many_arguments, unsafe_code, dead_code)]
#[inline]
fn uma_so2_m0_radial_vjp_parallel_sve_f32(
    nodes: usize,
    conv1_in_channels: usize,
    input_node_stride: usize,
    radial_node_stride: usize,
    conv1_m0_grad_mod: &[f32],
    conv1_input_l_major: &[f32],
    conv1_radial: &[f32],
    grad_conv1_input_l_major: &mut [f32],
    grad_conv1_radial: &mut [f32],
) -> bool {
    const CHUNK_ROWS: usize = 512;

    if nodes < UMA_M0_RADIAL_VJP_PARALLEL_MIN_NODES
        || rayon::current_num_threads() <= 2
        || !uma_f32_radial_vjp_sve_enabled()
    {
        return false;
    }
    let Some(block_width) = conv1_in_channels.checked_mul(3) else {
        return false;
    };
    let Some(input_width) = conv1_in_channels.checked_mul(7) else {
        return false;
    };
    let radial_width = block_width;
    if input_node_stride < input_width || radial_node_stride < radial_width {
        return false;
    }
    let Some(block_len) = nodes.checked_mul(block_width) else {
        return false;
    };
    let Some(input_len) = uma_strided_required_len(nodes, input_node_stride, input_width) else {
        return false;
    };
    let Some(radial_len) = uma_strided_required_len(nodes, radial_node_stride, radial_width) else {
        return false;
    };
    if conv1_m0_grad_mod.len() < block_len
        || conv1_input_l_major.len() < input_len
        || conv1_radial.len() < radial_len
        || grad_conv1_input_l_major.len() < input_len
        || grad_conv1_radial.len() < radial_len
    {
        return false;
    }

    let grad_mod_addr = conv1_m0_grad_mod.as_ptr() as usize;
    let input_addr = conv1_input_l_major.as_ptr() as usize;
    let radial_addr = conv1_radial.as_ptr() as usize;
    let grad_input_addr = grad_conv1_input_l_major.as_mut_ptr() as usize;
    let grad_radial_addr = grad_conv1_radial.as_mut_ptr() as usize;
    let chunk_count = nodes.div_ceil(CHUNK_ROWS);

    (0..chunk_count).into_par_iter().all(|chunk_index| {
        let row_start = chunk_index * CHUNK_ROWS;
        let chunk_nodes = (nodes - row_start).min(CHUNK_ROWS);
        let Some(block_start) = row_start.checked_mul(block_width) else {
            return false;
        };
        let Some(input_start) = row_start.checked_mul(input_node_stride) else {
            return false;
        };
        let Some(radial_start) = row_start.checked_mul(radial_node_stride) else {
            return false;
        };
        let Some(chunk_block_len) = chunk_nodes.checked_mul(block_width) else {
            return false;
        };
        let Some(chunk_input_len) =
            uma_strided_required_len(chunk_nodes, input_node_stride, input_width)
        else {
            return false;
        };
        let Some(chunk_radial_len) =
            uma_strided_required_len(chunk_nodes, radial_node_stride, radial_width)
        else {
            return false;
        };

        // SAFETY: chunks are disjoint node ranges. The m0 radial VJP writes only
        // m=0 slots within each row, and every mutable slice starts at the first
        // row owned by this task and spans only `chunk_nodes` rows.
        unsafe {
            let grad_mod_chunk = std::slice::from_raw_parts(
                (grad_mod_addr as *const f32).add(block_start),
                chunk_block_len,
            );
            let input_chunk = std::slice::from_raw_parts(
                (input_addr as *const f32).add(input_start),
                chunk_input_len,
            );
            let radial_chunk = std::slice::from_raw_parts(
                (radial_addr as *const f32).add(radial_start),
                chunk_radial_len,
            );
            let grad_input_chunk = std::slice::from_raw_parts_mut(
                (grad_input_addr as *mut f32).add(input_start),
                chunk_input_len,
            );
            let grad_radial_chunk = std::slice::from_raw_parts_mut(
                (grad_radial_addr as *mut f32).add(radial_start),
                chunk_radial_len,
            );
            uma_so2_m0_radial_vjp_sve_f32(
                chunk_nodes,
                conv1_in_channels,
                input_node_stride,
                radial_node_stride,
                grad_mod_chunk,
                input_chunk,
                radial_chunk,
                grad_input_chunk,
                grad_radial_chunk,
            )
        }
    })
}

