    let mut index = 0;
    while index + 4 <= a0.len() {
        acc0 += a0[index] * b0[index] + a1[index] * b1[index];
        acc1 += a0[index + 1] * b0[index + 1] + a1[index + 1] * b1[index + 1];
        acc2 += a0[index + 2] * b0[index + 2] + a1[index + 2] * b1[index + 2];
        acc3 += a0[index + 3] * b0[index + 3] + a1[index + 3] * b1[index + 3];
        index += 4;
    }
