impl Default for EsenOamProfile {
    fn default() -> Self {
        Self {
            schema_version: "llmlip-esen-oam-profile-v1",
            prepare: EsenOamPrepareProfile::default(),
            forward: EsenOamForwardProfile::default(),
            vjp: EsenOamVjpProfile::default(),
            force: EsenOamForceProfile::default(),
        }
    }
}

impl EsenOamProfile {
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    fn forward_block_mut(&mut self, block_index: usize) -> &mut EsenOamStageTiming {
        if self.forward.block_forward.len() <= block_index {
            self.forward
                .block_forward
                .resize(block_index + 1, EsenOamStageTiming::default());
        }
        &mut self.forward.block_forward[block_index]
    }

    fn forward_block_detail_mut(&mut self, block_index: usize) -> &mut EsenOamBlockForwardProfile {
        if self.forward.block_forward_detail.len() <= block_index {
            self.forward
                .block_forward_detail
                .resize(block_index + 1, EsenOamBlockForwardProfile::default());
        }
        &mut self.forward.block_forward_detail[block_index]
    }

    fn vjp_forward_replay_block_mut(&mut self, block_index: usize) -> &mut EsenOamStageTiming {
        if self.vjp.forward_replay.len() <= block_index {
            self.vjp
                .forward_replay
                .resize(block_index + 1, EsenOamStageTiming::default());
        }
        &mut self.vjp.forward_replay[block_index]
    }

    fn vjp_forward_replay_block_detail_mut(
        &mut self,
        block_index: usize,
    ) -> &mut EsenOamBlockForwardProfile {
        if self.vjp.forward_replay_detail.len() <= block_index {
            self.vjp
                .forward_replay_detail
                .resize(block_index + 1, EsenOamBlockForwardProfile::default());
        }
        &mut self.vjp.forward_replay_detail[block_index]
    }

    fn vjp_block_mut(&mut self, block_index: usize) -> &mut EsenOamStageTiming {
        if self.vjp.block_vjp.len() <= block_index {
            self.vjp
                .block_vjp
                .resize(block_index + 1, EsenOamStageTiming::default());
        }
        &mut self.vjp.block_vjp[block_index]
    }

    fn vjp_block_detail_mut(&mut self, block_index: usize) -> &mut EsenOamBlockVjpProfile {
        if self.vjp.block_vjp_detail.len() <= block_index {
            self.vjp
                .block_vjp_detail
                .resize(block_index + 1, EsenOamBlockVjpProfile::default());
        }
        &mut self.vjp.block_vjp_detail[block_index]
    }
}

// ── UMA-S-1.2 stage profiling ──────────────────────────────────────────────

/// Per-stage timing accumulator for UMA-S-1.2 predictions.
///
/// Each field accumulates wall-clock time across all calls within a benchmark
/// run (warmup + timed iterations).  Obtain one via [`UmaProfile::new`] and
/// pass it as `Some(&mut profile)` to the `_profiled` prediction variants.
/// When passed as `None` every instrumentation site is a no-op.
#[derive(Clone, Copy, Debug, Default, Serialize)]
pub struct UmaStageTiming {
    pub calls: usize,
    pub total_ms: f64,
}

impl UmaStageTiming {
    fn record(&mut self, start: Instant) {
        self.calls += 1;
        self.total_ms += elapsed_model_ms(start);
    }

    fn record_optional(&mut self, start: Option<Instant>) {
        if let Some(start) = start {
            self.record(start);
        }
    }

    #[cfg(all(
        feature = "parallel",
        any(
            all(feature = "accelerate-blas", target_os = "macos"),
            all(
                any(feature = "intel-mkl", feature = "openblas"),
                target_os = "linux",
                any(target_arch = "x86_64", target_arch = "aarch64")
            )
        )
    ))]
    fn merge_from(&mut self, other: &Self) {
        self.calls += other.calls;
        self.total_ms += other.total_ms;
    }
}

/// Top-level stage timings for the energy forward pass.
///
/// The same single forward serves both the energy-only path and the
/// energy+forces path. In the energy+forces path its scalar output is the
/// reported energy and its saved intermediates feed the VJP; no separate
/// forward is run for forces.
#[derive(Clone, Debug, Default, Serialize)]
pub struct UmaForwardProfile {
    /// MoLE routing MLP: routing_input → mole_coefficients.
    pub routing: UmaStageTiming,
    /// Mixed-weight assembly from mole_coefficients.
    pub mixed_weights: UmaStageTiming,
    /// All transformer blocks combined (sum of `block_forward` entries).
    pub blocks_forward: UmaStageTiming,
    /// Final RMS-norm before the energy head.
    pub final_norm: UmaStageTiming,
    /// Energy-head MLP + per-atom sum.
    pub energy_head: UmaStageTiming,
    /// Per-block total forward time (length = number of blocks).
    pub block_forward: Vec<UmaStageTiming>,
    /// Per-block sub-stage detail (length = number of blocks).
    pub block_forward_detail: Vec<UmaBlockForwardProfile>,
}

/// Sub-stage timings for a single UMA transformer block (forward pass).
#[derive(Clone, Debug, Default, Serialize)]
pub struct UmaBlockForwardProfile {
    pub conv1_radial_mlp: UmaStageTiming,
    pub norm1: UmaStageTiming,
    pub source_target_concat: UmaStageTiming,
    pub rotate_to_compact: UmaStageTiming,
    /// Fused path: conv1 + gate + conv2 in one call.
    pub so2_fused_conv1_gate_conv2: UmaStageTiming,
    /// Fused path inner detail for the f32 l=2,m=2 SO2 helper.
    pub so2_fused_conv1_gate_conv2_detail: UmaSo2FusedForwardProfile,
    /// Separate-path: conv1 SO2 only.
    pub conv1_so2: UmaStageTiming,
    /// Separate-path: fused gate + conv2 SO2.
    pub gate_conv2_so2: UmaStageTiming,
    /// Separate-path: gate activation only.
    pub gate: UmaStageTiming,
    /// Separate-path: conv2 SO2 only.
    pub conv2_so2: UmaStageTiming,
    pub envelope: UmaStageTiming,
    pub rotate_from_compact: UmaStageTiming,
    pub edge_scatter: UmaStageTiming,
    pub edge_residual: UmaStageTiming,
    pub norm2: UmaStageTiming,
    pub atomwise: UmaStageTiming,
    pub output_residual: UmaStageTiming,
}

