// ── end UMA profiling structs ──────────────────────────────────────────────

fn elapsed_model_ms(start: Instant) -> f64 {
    start.elapsed().as_secs_f64() * 1000.0
}

#[allow(clippy::uninit_vec, unsafe_code)]
fn uninit_model_f64_vec(len: usize) -> Vec<f64> {
    let mut values = Vec::with_capacity(len);
    // Invariant: callers use this only for f64 buffers that are fully
    // overwritten by the callee before any read.
    unsafe {
        values.set_len(len);
    }
    values
}

#[allow(clippy::uninit_vec, unsafe_code)]
fn uninit_model_f32_vec(len: usize) -> Vec<f32> {
    let mut values = Vec::with_capacity(len);
    // Invariant: callers use this only for f32 buffers that are fully
    // overwritten by the callee before any read.
    unsafe {
        values.set_len(len);
    }
    values
}

impl EsenOamRuntimeModel {
    #[must_use]
    pub fn edge_degree_radial_mlp_input_dim(&self) -> usize {
        self.edge_degree_radial_mlp.input_dim()
    }

    #[must_use]
    pub fn edge_degree_radial_mlp_output_dim(&self) -> usize {
        self.edge_degree_radial_mlp.output_dim()
    }

    pub fn edge_degree_radial_mlp_forward(
        &self,
        input: &[f64],
        out: &mut [f64],
    ) -> Result<(), ModelError> {
        let mut cache = EsenRadialMlpCache::default();
        self.edge_degree_radial_mlp_forward_cached(input, out, &mut cache)
    }

    fn edge_degree_radial_mlp_forward_cached(
        &self,
        input: &[f64],
        out: &mut [f64],
        cache: &mut EsenRadialMlpCache,
    ) -> Result<(), ModelError> {
        self.edge_degree_radial_mlp.forward(input, out, cache)?;
        Ok(())
    }

    fn edge_degree_radial_mlp_forward_batch_cached(
        &self,
        edge_count: usize,
        input: &[f64],
        out: &mut [f64],
        cache: &mut EsenRadialMlpBatchCache,
    ) -> Result<(), ModelError> {
        self.edge_degree_radial_mlp
            .forward_batch_contiguous_cache(edge_count, input, out, cache)?;
        Ok(())
    }

    #[must_use]
    pub fn block_count(&self) -> usize {
        self.block_conv1_radial_mlps.len()
    }

    fn block_so2_m_fused_weights(
        &self,
        block_index: usize,
    ) -> Result<&EsenOamBlockSo2MConvFusedWeights, ModelError> {
        self.block_so2_m_fused_weights
            .get(block_index)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "eSEN-OAM block index {block_index} is out of range for {} fused SO2 weight blocks",
                    self.block_so2_m_fused_weights.len()
                ))
            })
    }
}

