impl EsenOamPreparedInput {
    #[must_use]
    pub fn atom_count(&self) -> usize {
        self.atomic_numbers.len()
    }

    #[must_use]
    pub fn edge_count(&self) -> usize {
        self.edge_sources.len()
    }

    pub fn edge_degree_message_with_wigner_inv(
        &self,
        full_wigner_inv: &[f64],
    ) -> Result<Vec<f64>, ModelError> {
        let edge_count = self.edge_count();
        check_esen_oam_len(
            "eSEN-OAM full wigner_inv",
            edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM,
            full_wigner_inv.len(),
        )?;

        let mut compact_wigner_inv =
            vec![0.0; edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM];
        select_esen_oam_compact_wigner_inv_columns(full_wigner_inv, &mut compact_wigner_inv);
        self.edge_degree_message_with_compact_wigner_inv(&compact_wigner_inv)
    }

    pub fn edge_degree_message_with_compact_wigner_inv(
        &self,
        compact_wigner_inv: &[f64],
    ) -> Result<Vec<f64>, ModelError> {
        let edge_count = self.edge_count();
        if self.edge_targets.len() != edge_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM prepared edge target length {} must match edge count {edge_count}",
                self.edge_targets.len()
            )));
        }
        check_len(
            "eSEN-OAM prepared compact edge-degree coefficients",
            edge_count * ESEN_OAM_COMPACT_M_FEATURE_DIM,
            self.edge_degree_m_coefficients.len(),
        )?;
        check_len(
            "eSEN-OAM prepared pre-edge-degree node message",
            self.atom_count() * ESEN_OAM_NODE_FEATURE_DIM,
            self.node_message_before_edge_degree.len(),
        )?;
        check_esen_oam_len(
            "eSEN-OAM compact wigner_inv",
            edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM,
            compact_wigner_inv.len(),
        )?;
        let mut node_message = self.node_message_before_edge_degree.clone();
        esen_oam_compact_inverse_rotate_scatter_forward_prepared(
            self.atom_count(),
            &self.edge_target_offsets,
            &self.edge_target_edge_indices,
            ESEN_OAM_EDGE_DEGREE_RESCALE_FACTOR,
            compact_wigner_inv,
            &self.edge_degree_m_coefficients,
            &mut node_message,
            true,
        )?;
        Ok(node_message)
    }
}

