#[allow(clippy::too_many_arguments)]
fn esen_oam_source_target_compact_rotate_input_vjp_prepared(
    edge_sources: &[usize],
    edge_targets: &[usize],
    edge_source_offsets: &[usize],
    edge_source_edge_indices: &[usize],
    edge_target_offsets: &[usize],
    edge_target_edge_indices: &[usize],
    compact_wigner: &[f64],
    grad_rotated: &[f64],
    grad_node_features: &mut [f64],
    assume_block_diagonal_wigner: bool,
) -> Result<(), ModelError> {
    if edge_sources.len() != edge_targets.len() {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused concat/rotate input VJP source length {} must match target length {}",
            edge_sources.len(),
            edge_targets.len()
        )));
    }
    if !grad_node_features
        .len()
        .is_multiple_of(ESEN_OAM_NODE_FEATURE_DIM)
    {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused concat/rotate input VJP node grad length {} is not a multiple of {}",
            grad_node_features.len(),
            ESEN_OAM_NODE_FEATURE_DIM
        )));
    }
    let edge_count = edge_sources.len();
    let node_count = grad_node_features.len() / ESEN_OAM_NODE_FEATURE_DIM;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate input VJP source offsets",
        node_count + 1,
        edge_source_offsets.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate input VJP source edge indices",
        edge_count,
        edge_source_edge_indices.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate input VJP target offsets",
        node_count + 1,
        edge_target_offsets.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate input VJP target edge indices",
        edge_count,
        edge_target_edge_indices.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate input VJP compact Wigner",
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM,
        compact_wigner.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate input VJP grad rotated",
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS,
        grad_rotated.len(),
    )?;

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= 512 {
        for (edge_index, (&source, &target)) in
            edge_sources.iter().zip(edge_targets.iter()).enumerate()
        {
            if source >= node_count || target >= node_count {
                return Err(invalid_manifest(format!(
                    "eSEN-OAM fused concat/rotate input VJP edge {edge_index} has out-of-range source/target {source}->{target} for {node_count} nodes"
                )));
            }
        }

        grad_node_features
            .par_chunks_mut(ESEN_OAM_NODE_FEATURE_DIM)
            .enumerate()
            .for_each(|(node, grad_node)| {
                for &edge_index in &edge_source_edge_indices
                    [edge_source_offsets[node]..edge_source_offsets[node + 1]]
                {
                    let matrix_start =
                        edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM;
                    let grad_edge_start =
                        edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
                    for out_coefficient in 0..ESEN_OAM_COMPACT_M_BASIS_DIM {
                        let matrix_row_start = matrix_start + out_coefficient * ESEN_OAM_BASIS_DIM;
                        let grad_out_start =
                            grad_edge_start + out_coefficient * 2 * ESEN_OAM_CHANNELS;
                        let (input_start_coefficient, input_end_coefficient) =
                            esen_oam_compact_wigner_input_coefficient_range(
                                out_coefficient,
                                assume_block_diagonal_wigner,
                            );
                        for in_coefficient in input_start_coefficient..input_end_coefficient {
                            let weight = compact_wigner[matrix_row_start + in_coefficient];
                            let grad_node_start = in_coefficient * ESEN_OAM_CHANNELS;
                            for channel in 0..ESEN_OAM_CHANNELS {
                                grad_node[grad_node_start + channel] +=
                                    weight * grad_rotated[grad_out_start + channel];
                            }
                        }
                    }
                }

                for &edge_index in &edge_target_edge_indices
                    [edge_target_offsets[node]..edge_target_offsets[node + 1]]
                {
                    let matrix_start =
                        edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM;
                    let grad_edge_start =
                        edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
                    for out_coefficient in 0..ESEN_OAM_COMPACT_M_BASIS_DIM {
                        let matrix_row_start = matrix_start + out_coefficient * ESEN_OAM_BASIS_DIM;
                        let grad_out_start = grad_edge_start
                            + out_coefficient * 2 * ESEN_OAM_CHANNELS
                            + ESEN_OAM_CHANNELS;
                        let (input_start_coefficient, input_end_coefficient) =
                            esen_oam_compact_wigner_input_coefficient_range(
                                out_coefficient,
                                assume_block_diagonal_wigner,
                            );
                        for in_coefficient in input_start_coefficient..input_end_coefficient {
                            let weight = compact_wigner[matrix_row_start + in_coefficient];
                            let grad_node_start = in_coefficient * ESEN_OAM_CHANNELS;
                            for channel in 0..ESEN_OAM_CHANNELS {
                                grad_node[grad_node_start + channel] +=
                                    weight * grad_rotated[grad_out_start + channel];
                            }
                        }
                    }
                }
            });
        return Ok(());
    }

    for edge_index in 0..edge_count {
        let source = edge_sources[edge_index];
        let target = edge_targets[edge_index];
        if source >= node_count || target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM fused concat/rotate input VJP edge {edge_index} has out-of-range source/target {source}->{target} for {node_count} nodes"
            )));
        }
        let matrix_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        let grad_edge_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
        for out_coefficient in 0..ESEN_OAM_COMPACT_M_BASIS_DIM {
            let matrix_row_start = matrix_start + out_coefficient * ESEN_OAM_BASIS_DIM;
            let source_grad_start = grad_edge_start + out_coefficient * 2 * ESEN_OAM_CHANNELS;
            let target_grad_start = source_grad_start + ESEN_OAM_CHANNELS;
            let (input_start_coefficient, input_end_coefficient) =
                esen_oam_compact_wigner_input_coefficient_range(
                    out_coefficient,
                    assume_block_diagonal_wigner,
                );
            for in_coefficient in input_start_coefficient..input_end_coefficient {
                let weight = compact_wigner[matrix_row_start + in_coefficient];
                let source_node_start =
                    source * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                let target_node_start =
                    target * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                for channel in 0..ESEN_OAM_CHANNELS {
                    grad_node_features[source_node_start + channel] +=
                        weight * grad_rotated[source_grad_start + channel];
                    grad_node_features[target_node_start + channel] +=
                        weight * grad_rotated[target_grad_start + channel];
                }
            }
        }
    }
    Ok(())
}

fn esen_oam_source_target_compact_rotate_matrix_vjp_prepared(
    edge_sources: &[usize],
    edge_targets: &[usize],
    node_features: &[f64],
    grad_rotated: &[f64],
    grad_compact_wigner: &mut [f64],
) -> Result<(), ModelError> {
    if edge_sources.len() != edge_targets.len() {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused concat/rotate matrix VJP source length {} must match target length {}",
            edge_sources.len(),
            edge_targets.len()
        )));
    }
    if !node_features
        .len()
        .is_multiple_of(ESEN_OAM_NODE_FEATURE_DIM)
    {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused concat/rotate matrix VJP node feature length {} is not a multiple of {}",
            node_features.len(),
            ESEN_OAM_NODE_FEATURE_DIM
        )));
    }
    let edge_count = edge_sources.len();
    let node_count = node_features.len() / ESEN_OAM_NODE_FEATURE_DIM;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate matrix VJP grad rotated",
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS,
        grad_rotated.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate matrix VJP grad compact Wigner",
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM,
        grad_compact_wigner.len(),
    )?;
    for (edge_index, (&source, &target)) in edge_sources.iter().zip(edge_targets.iter()).enumerate()
    {
        if source >= node_count || target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM fused concat/rotate matrix VJP edge {edge_index} has out-of-range source/target {source}->{target} for {node_count} nodes"
            )));
        }
    }

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= 512 {
        grad_compact_wigner
            .par_chunks_mut(ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM)
            .enumerate()
            .for_each(|(edge_index, grad_matrix)| {
                let source = edge_sources[edge_index];
                let target = edge_targets[edge_index];
                let grad_edge_start =
                    edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
                for out_coefficient in 0..ESEN_OAM_COMPACT_M_BASIS_DIM {
                    let grad_source_start =
                        grad_edge_start + out_coefficient * 2 * ESEN_OAM_CHANNELS;
                    let grad_target_start = grad_source_start + ESEN_OAM_CHANNELS;
                    let grad_matrix_row_start = out_coefficient * ESEN_OAM_BASIS_DIM;
                    for in_coefficient in 0..ESEN_OAM_BASIS_DIM {
                        let source_node_start =
                            source * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                        let target_node_start =
                            target * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                        let mut value = 0.0;
                        for channel in 0..ESEN_OAM_CHANNELS {
                            value += grad_rotated[grad_source_start + channel]
                                * node_features[source_node_start + channel]
                                + grad_rotated[grad_target_start + channel]
                                    * node_features[target_node_start + channel];
                        }
                        grad_matrix[grad_matrix_row_start + in_coefficient] += value;
                    }
                }
            });
        return Ok(());
    }

    for edge_index in 0..edge_count {
        let source = edge_sources[edge_index];
        let target = edge_targets[edge_index];
        let grad_edge_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
        let grad_matrix_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        for out_coefficient in 0..ESEN_OAM_COMPACT_M_BASIS_DIM {
            let grad_source_start = grad_edge_start + out_coefficient * 2 * ESEN_OAM_CHANNELS;
            let grad_target_start = grad_source_start + ESEN_OAM_CHANNELS;
            let grad_matrix_row_start = grad_matrix_start + out_coefficient * ESEN_OAM_BASIS_DIM;
            for in_coefficient in 0..ESEN_OAM_BASIS_DIM {
                let source_node_start =
                    source * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                let target_node_start =
                    target * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                let mut value = 0.0;
                for channel in 0..ESEN_OAM_CHANNELS {
                    value += grad_rotated[grad_source_start + channel]
                        * node_features[source_node_start + channel]
                        + grad_rotated[grad_target_start + channel]
                            * node_features[target_node_start + channel];
                }
                grad_compact_wigner[grad_matrix_row_start + in_coefficient] += value;
            }
        }
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn esen_oam_source_target_compact_rotate_matrix_full_wigner_vjp_prepared(
    edge_sources: &[usize],
    edge_targets: &[usize],
    node_features: &[f64],
    grad_rotated: &[f64],
    grad_wigner_inv: &mut [f64],
    assume_block_diagonal_wigner: bool,
) -> Result<(), ModelError> {
    if edge_sources.len() != edge_targets.len() {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused concat/rotate full-Wigner matrix VJP source length {} must match target length {}",
            edge_sources.len(),
            edge_targets.len()
        )));
    }
    if !node_features
        .len()
        .is_multiple_of(ESEN_OAM_NODE_FEATURE_DIM)
    {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused concat/rotate full-Wigner matrix VJP node feature length {} is not a multiple of {}",
            node_features.len(),
            ESEN_OAM_NODE_FEATURE_DIM
        )));
    }
    let edge_count = edge_sources.len();
    let node_count = node_features.len() / ESEN_OAM_NODE_FEATURE_DIM;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate full-Wigner matrix VJP grad rotated",
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS,
        grad_rotated.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused concat/rotate full-Wigner matrix VJP Wigner inverse gradient",
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM,
        grad_wigner_inv.len(),
    )?;
    for (edge_index, (&source, &target)) in edge_sources.iter().zip(edge_targets.iter()).enumerate()
    {
        if source >= node_count || target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM fused concat/rotate full-Wigner matrix VJP edge {edge_index} has out-of-range source/target {source}->{target} for {node_count} nodes"
            )));
        }
    }

    grad_wigner_inv
        .par_chunks_mut(ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM)
        .enumerate()
        .for_each(|(edge_index, grad_wigner_edge)| {
            let source = edge_sources[edge_index];
            let target = edge_targets[edge_index];
            let grad_edge_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;

            for (compact_row, &full_wigner_row) in
                ESEN_OAM_COMPACT_FULL_COEFFICIENT_INDICES.iter().enumerate()
            {
                let grad_source_start = grad_edge_start + compact_row * 2 * ESEN_OAM_CHANNELS;
                let grad_target_start = grad_source_start + ESEN_OAM_CHANNELS;
                let (input_start_coefficient, input_end_coefficient) =
                    esen_oam_compact_wigner_input_coefficient_range(
                        compact_row,
                        assume_block_diagonal_wigner,
                    );

                for in_coefficient in input_start_coefficient..input_end_coefficient {
                    let source_node_start =
                        source * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                    let target_node_start =
                        target * ESEN_OAM_NODE_FEATURE_DIM + in_coefficient * ESEN_OAM_CHANNELS;
                    let grad_wigner_inv_row_start = in_coefficient * ESEN_OAM_BASIS_DIM;
                    let mut value = 0.0;
                    for channel in 0..ESEN_OAM_CHANNELS {
                        value += grad_rotated[grad_source_start + channel]
                            * node_features[source_node_start + channel]
                            + grad_rotated[grad_target_start + channel]
                                * node_features[target_node_start + channel];
                    }
                    grad_wigner_edge[grad_wigner_inv_row_start + full_wigner_row] += value;
                }
            }
        });
    Ok(())
}

fn esen_oam_source_target_concat_coeff_interleaved_vjp(
    edge_sources: &[usize],
    edge_targets: &[usize],
    grad_edge_features: &[f64],
    grad_node_features: &mut [f64],
) -> Result<(), ModelError> {
    if edge_sources.len() != edge_targets.len() {
        return Err(invalid_manifest(format!(
            "eSEN-OAM source/target concat VJP source length {} must match target length {}",
            edge_sources.len(),
            edge_targets.len()
        )));
    }
    if !grad_node_features
        .len()
        .is_multiple_of(ESEN_OAM_NODE_FEATURE_DIM)
    {
        return Err(invalid_manifest(format!(
            "eSEN-OAM source/target concat VJP node feature length {} is not a multiple of {}",
            grad_node_features.len(),
            ESEN_OAM_NODE_FEATURE_DIM
        )));
    }
    let edge_count = edge_sources.len();
    check_len(
        "eSEN-OAM source/target concat VJP edge gradient",
        edge_count * ESEN_OAM_BASIS_DIM * 2 * ESEN_OAM_CHANNELS,
        grad_edge_features.len(),
    )?;
    let node_count = grad_node_features.len() / ESEN_OAM_NODE_FEATURE_DIM;

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= 512 {
        for (edge_index, (&source, &target)) in
            edge_sources.iter().zip(edge_targets.iter()).enumerate()
        {
            if source >= node_count || target >= node_count {
                return Err(invalid_manifest(format!(
                    "eSEN-OAM source/target concat VJP edge {edge_index} has out-of-range source/target {source}->{target} for {node_count} nodes"
                )));
            }
        }
        let mut source_counts = vec![0usize; node_count];
        let mut target_counts = vec![0usize; node_count];
        for (&source, &target) in edge_sources.iter().zip(edge_targets.iter()) {
            source_counts[source] += 1;
            target_counts[target] += 1;
        }

        let mut source_offsets = vec![0usize; node_count + 1];
        let mut target_offsets = vec![0usize; node_count + 1];
        for node in 0..node_count {
            source_offsets[node + 1] = source_offsets[node] + source_counts[node];
            target_offsets[node + 1] = target_offsets[node] + target_counts[node];
        }

        let mut source_next = source_offsets[..node_count].to_vec();
        let mut target_next = target_offsets[..node_count].to_vec();
        let mut source_edge_indices = vec![0usize; edge_count];
        let mut target_edge_indices = vec![0usize; edge_count];
        for (edge_index, (&source, &target)) in
            edge_sources.iter().zip(edge_targets.iter()).enumerate()
        {
            let source_position = source_next[source];
            source_edge_indices[source_position] = edge_index;
            source_next[source] += 1;

            let target_position = target_next[target];
            target_edge_indices[target_position] = edge_index;
            target_next[target] += 1;
        }

        grad_node_features
            .par_chunks_mut(ESEN_OAM_NODE_FEATURE_DIM)
            .enumerate()
            .for_each(|(node, grad_node)| {
                for &edge_index in
                    &source_edge_indices[source_offsets[node]..source_offsets[node + 1]]
                {
                    let edge_base = edge_index * ESEN_OAM_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
                    for coefficient in 0..ESEN_OAM_BASIS_DIM {
                        let node_start = coefficient * ESEN_OAM_CHANNELS;
                        let edge_start = edge_base + coefficient * 2 * ESEN_OAM_CHANNELS;
                        for channel in 0..ESEN_OAM_CHANNELS {
                            grad_node[node_start + channel] +=
                                grad_edge_features[edge_start + channel];
                        }
                    }
                }

                for &edge_index in
                    &target_edge_indices[target_offsets[node]..target_offsets[node + 1]]
                {
                    let edge_base = edge_index * ESEN_OAM_BASIS_DIM * 2 * ESEN_OAM_CHANNELS;
                    for coefficient in 0..ESEN_OAM_BASIS_DIM {
                        let node_start = coefficient * ESEN_OAM_CHANNELS;
                        let edge_start =
                            edge_base + coefficient * 2 * ESEN_OAM_CHANNELS + ESEN_OAM_CHANNELS;
                        for channel in 0..ESEN_OAM_CHANNELS {
                            grad_node[node_start + channel] +=
                                grad_edge_features[edge_start + channel];
                        }
                    }
                }
            });
        return Ok(());
    }

    for edge_index in 0..edge_count {
        let source = edge_sources[edge_index];
        let target = edge_targets[edge_index];
        if source >= node_count || target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM source/target concat VJP edge {edge_index} has out-of-range source/target {source}->{target} for {node_count} nodes"
            )));
        }
        for coefficient in 0..ESEN_OAM_BASIS_DIM {
            let source_start = source * ESEN_OAM_NODE_FEATURE_DIM + coefficient * ESEN_OAM_CHANNELS;
            let target_start = target * ESEN_OAM_NODE_FEATURE_DIM + coefficient * ESEN_OAM_CHANNELS;
            let edge_start = edge_index * ESEN_OAM_BASIS_DIM * 2 * ESEN_OAM_CHANNELS
                + coefficient * 2 * ESEN_OAM_CHANNELS;
            for channel in 0..ESEN_OAM_CHANNELS {
                grad_node_features[source_start + channel] +=
                    grad_edge_features[edge_start + channel];
                grad_node_features[target_start + channel] +=
                    grad_edge_features[edge_start + ESEN_OAM_CHANNELS + channel];
            }
        }
    }
    Ok(())
}

fn build_esen_oam_edge_target_adjacency(
    node_count: usize,
    edge_targets: &[usize],
) -> Result<(Vec<usize>, Vec<usize>), ModelError> {
    build_esen_oam_edge_node_adjacency("target", node_count, edge_targets)
}

fn build_esen_oam_edge_node_adjacency(
    label: &str,
    node_count: usize,
    edge_nodes: &[usize],
) -> Result<(Vec<usize>, Vec<usize>), ModelError> {
    let mut counts = vec![0usize; node_count];
    for (edge_index, &node) in edge_nodes.iter().enumerate() {
        if node >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM edge {label} adjacency edge {edge_index} has {label} {node} for {node_count} nodes"
            )));
        }
        counts[node] += 1;
    }

    let mut offsets = vec![0usize; node_count + 1];
    for node in 0..node_count {
        offsets[node + 1] = offsets[node] + counts[node];
    }

    let mut next = offsets[..node_count].to_vec();
    let mut edge_indices = vec![0usize; edge_nodes.len()];
    for (edge_index, &node) in edge_nodes.iter().enumerate() {
        let position = next[node];
        edge_indices[position] = edge_index;
        next[node] += 1;
    }
    Ok((offsets, edge_indices))
}

#[allow(clippy::too_many_arguments)]
fn esen_oam_edge_to_node_scaled_scatter_forward_prepared(
    node_count: usize,
    feature_dim: usize,
    edge_target_offsets: &[usize],
    edge_target_edge_indices: &[usize],
    rescale_factor: f64,
    edge_features: &[f64],
    node_features: &mut [f64],
) -> Result<(), ModelError> {
    check_len(
        "eSEN-OAM prepared edge-to-node scatter offsets",
        node_count + 1,
        edge_target_offsets.len(),
    )?;
    check_len(
        "eSEN-OAM prepared edge-to-node scatter node features",
        node_count * feature_dim,
        node_features.len(),
    )?;
    check_len(
        "eSEN-OAM prepared edge-to-node scatter edge features",
        edge_target_edge_indices.len() * feature_dim,
        edge_features.len(),
    )?;
    if !rescale_factor.is_finite() || rescale_factor == 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM prepared edge-to-node scatter rescale factor must be finite and nonzero, got {rescale_factor}"
        )));
    }
    let scale = 1.0 / rescale_factor;

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_target_edge_indices.len() >= 512 {
        node_features
            .par_chunks_mut(feature_dim)
            .enumerate()
            .for_each(|(node, node_feature)| {
                for &edge_index in &edge_target_edge_indices
                    [edge_target_offsets[node]..edge_target_offsets[node + 1]]
                {
                    let edge_start = edge_index * feature_dim;
                    for feature in 0..feature_dim {
                        node_feature[feature] += edge_features[edge_start + feature] * scale;
                    }
                }
            });
        return Ok(());
    }

    for node in 0..node_count {
        let node_start = node * feature_dim;
        for &edge_index in
            &edge_target_edge_indices[edge_target_offsets[node]..edge_target_offsets[node + 1]]
        {
            let edge_start = edge_index * feature_dim;
            for feature in 0..feature_dim {
                node_features[node_start + feature] += edge_features[edge_start + feature] * scale;
            }
        }
    }
    Ok(())
}

fn esen_oam_edge_to_node_scaled_scatter_vjp_edges_write_parallel(
    node_count: usize,
    feature_dim: usize,
    edge_targets: &[usize],
    rescale_factor: f64,
    grad_node_features: &[f64],
    grad_edge_features: &mut [f64],
) -> Result<(), ModelError> {
    check_len(
        "eSEN-OAM edge-to-node scatter VJP write node features",
        node_count * feature_dim,
        grad_node_features.len(),
    )?;
    check_len(
        "eSEN-OAM edge-to-node scatter VJP write edge features",
        edge_targets.len() * feature_dim,
        grad_edge_features.len(),
    )?;
    if !rescale_factor.is_finite() || rescale_factor == 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM edge-to-node scatter VJP write rescale factor must be finite and nonzero, got {rescale_factor}"
        )));
    }
    for (edge_index, &target) in edge_targets.iter().enumerate() {
        if target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM edge-to-node scatter VJP write edge {edge_index} has out-of-range target {target} for {node_count} nodes"
            )));
        }
    }
    let unit_scale = rescale_factor.to_bits() == 1.0_f64.to_bits();
    let scale = 1.0 / rescale_factor;

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_targets.len() >= 512 {
        grad_edge_features
            .par_chunks_mut(feature_dim)
            .zip(edge_targets.par_iter())
            .for_each(|(grad_edge_feature, &target)| {
                let node_start = target * feature_dim;
                let node_feature = &grad_node_features[node_start..node_start + feature_dim];
                if unit_scale {
                    grad_edge_feature.copy_from_slice(node_feature);
                } else {
                    for feature in 0..feature_dim {
                        grad_edge_feature[feature] = node_feature[feature] * scale;
                    }
                }
            });
        return Ok(());
    }

    for (edge_index, &target) in edge_targets.iter().enumerate() {
        let edge_start = edge_index * feature_dim;
        let node_start = target * feature_dim;
        let grad_edge_feature = &mut grad_edge_features[edge_start..edge_start + feature_dim];
        let node_feature = &grad_node_features[node_start..node_start + feature_dim];
        if unit_scale {
            grad_edge_feature.copy_from_slice(node_feature);
        } else {
            for feature in 0..feature_dim {
                grad_edge_feature[feature] = node_feature[feature] * scale;
            }
        }
    }
    Ok(())
}

