#[allow(clippy::too_many_arguments)]
fn esen_oam_compact_inverse_rotate_scatter_forward_prepared(
    node_count: usize,
    edge_target_offsets: &[usize],
    edge_target_edge_indices: &[usize],
    rescale_factor: f64,
    compact_wigner_inv: &[f64],
    edge_compact_features: &[f64],
    node_features: &mut [f64],
    assume_block_diagonal_wigner: bool,
) -> Result<(), ModelError> {
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter offsets",
        node_count + 1,
        edge_target_offsets.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter node features",
        node_count * ESEN_OAM_NODE_FEATURE_DIM,
        node_features.len(),
    )?;
    let edge_count = edge_target_edge_indices.len();
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter compact Wigner inverse",
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM,
        compact_wigner_inv.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter compact edge features",
        edge_count * ESEN_OAM_COMPACT_M_FEATURE_DIM,
        edge_compact_features.len(),
    )?;
    if !rescale_factor.is_finite() || rescale_factor == 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused inverse-rotate scatter rescale factor must be finite and nonzero, got {rescale_factor}"
        )));
    }
    #[cfg(not(feature = "parallel"))]
    let _ = assume_block_diagonal_wigner;
    for (position, &edge_index) in edge_target_edge_indices.iter().enumerate() {
        if edge_index >= edge_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM fused inverse-rotate scatter position {position} references out-of-range edge {edge_index} for {edge_count} edges"
            )));
        }
    }
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= 512 {
        let scale = 1.0 / rescale_factor;
        node_features
            .par_chunks_mut(ESEN_OAM_NODE_FEATURE_DIM)
            .enumerate()
            .for_each(|(node, node_feature)| {
                for &edge_index in &edge_target_edge_indices
                    [edge_target_offsets[node]..edge_target_offsets[node + 1]]
                {
                    add_compact_inverse_rotated_edge_to_node(
                        compact_wigner_inv,
                        edge_compact_features,
                        edge_index,
                        scale,
                        node_feature,
                        assume_block_diagonal_wigner,
                    );
                }
            });
        return Ok(());
    }

    let mut edge_messages = vec![0.0; edge_count * ESEN_OAM_NODE_FEATURE_DIM];
    fairchem_esen_so3_batched_matmul_forward(
        EsenSo3BatchedMatmulConfig::new(
            ESEN_OAM_COMPACT_M_BASIS_DIM,
            ESEN_OAM_BASIS_DIM,
            ESEN_OAM_CHANNELS,
        )?,
        compact_wigner_inv,
        edge_compact_features,
        &mut edge_messages,
    )?;
    esen_oam_scatter_rotated_edges_for_diagnostics(
        node_count,
        edge_target_offsets,
        edge_target_edge_indices,
        1.0 / rescale_factor,
        &edge_messages,
        node_features,
    )?;
    Ok(())
}

fn esen_oam_scatter_rotated_edges_for_diagnostics(
    node_count: usize,
    edge_target_offsets: &[usize],
    edge_target_edge_indices: &[usize],
    scale: f64,
    edge_features: &[f64],
    node_features: &mut [f64],
) -> Result<(), ModelError> {
    check_esen_oam_len(
        "eSEN-OAM diagnostic edge scatter offsets",
        node_count + 1,
        edge_target_offsets.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM diagnostic edge scatter node features",
        node_count * ESEN_OAM_NODE_FEATURE_DIM,
        node_features.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM diagnostic edge scatter edge features",
        edge_target_edge_indices.len() * ESEN_OAM_NODE_FEATURE_DIM,
        edge_features.len(),
    )?;
    for (position, &edge_index) in edge_target_edge_indices.iter().enumerate() {
        if edge_index >= edge_target_edge_indices.len() {
            return Err(invalid_manifest(format!(
                "eSEN-OAM diagnostic edge scatter position {position} references out-of-range edge {edge_index}"
            )));
        }
    }
    for node in 0..node_count {
        let node_start = node * ESEN_OAM_NODE_FEATURE_DIM;
        for &edge_index in
            &edge_target_edge_indices[edge_target_offsets[node]..edge_target_offsets[node + 1]]
        {
            let edge_start = edge_index * ESEN_OAM_NODE_FEATURE_DIM;
            for feature in 0..ESEN_OAM_NODE_FEATURE_DIM {
                node_features[node_start + feature] += scale * edge_features[edge_start + feature];
            }
        }
    }
    Ok(())
}

#[cfg(feature = "parallel")]
fn add_compact_inverse_rotated_edge_to_node(
    compact_wigner_inv: &[f64],
    edge_compact_features: &[f64],
    edge_index: usize,
    scale: f64,
    node_feature: &mut [f64],
    assume_block_diagonal_wigner: bool,
) {
    debug_assert_eq!(node_feature.len(), ESEN_OAM_NODE_FEATURE_DIM);
    let matrix_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM;
    let input_start = edge_index * ESEN_OAM_COMPACT_M_FEATURE_DIM;
    for out_coefficient in 0..ESEN_OAM_BASIS_DIM {
        let node_row_start = out_coefficient * ESEN_OAM_CHANNELS;
        let matrix_row_start = matrix_start + out_coefficient * ESEN_OAM_COMPACT_M_BASIS_DIM;
        let (input_start_coefficient, input_end_coefficient) =
            esen_oam_compact_wigner_compact_input_range_for_full_row(
                out_coefficient,
                assume_block_diagonal_wigner,
            );
        for in_coefficient in input_start_coefficient..input_end_coefficient {
            let weight = scale * compact_wigner_inv[matrix_row_start + in_coefficient];
            let input_row_start = input_start + in_coefficient * ESEN_OAM_CHANNELS;
            for channel in 0..ESEN_OAM_CHANNELS {
                node_feature[node_row_start + channel] +=
                    weight * edge_compact_features[input_row_start + channel];
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn esen_oam_compact_inverse_rotate_scatter_vjp_prepared(
    node_count: usize,
    edge_targets: &[usize],
    rescale_factor: f64,
    compact_wigner_inv: &[f64],
    edge_compact_features: &[f64],
    grad_node_features: &[f64],
    grad_edge_compact_features: &mut [f64],
    grad_compact_wigner_inv: &mut [f64],
    assume_block_diagonal_wigner: bool,
) -> Result<(), ModelError> {
    let edge_count = edge_targets.len();
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter VJP node features",
        node_count * ESEN_OAM_NODE_FEATURE_DIM,
        grad_node_features.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter VJP compact Wigner inverse",
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM,
        compact_wigner_inv.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter VJP compact edge features",
        edge_count * ESEN_OAM_COMPACT_M_FEATURE_DIM,
        edge_compact_features.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter VJP compact edge feature gradient",
        edge_count * ESEN_OAM_COMPACT_M_FEATURE_DIM,
        grad_edge_compact_features.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate scatter VJP compact Wigner inverse gradient",
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM,
        grad_compact_wigner_inv.len(),
    )?;
    if !rescale_factor.is_finite() || rescale_factor == 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused inverse-rotate scatter VJP rescale factor must be finite and nonzero, got {rescale_factor}"
        )));
    }
    #[cfg(not(feature = "parallel"))]
    let _ = assume_block_diagonal_wigner;
    for (edge_index, &target) in edge_targets.iter().enumerate() {
        if target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM fused inverse-rotate scatter VJP edge {edge_index} has out-of-range target {target} for {node_count} nodes"
            )));
        }
    }
    let scale = 1.0 / rescale_factor;

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && edge_count >= 512 {
        grad_edge_compact_features
            .par_chunks_mut(ESEN_OAM_COMPACT_M_FEATURE_DIM)
            .zip(
                grad_compact_wigner_inv
                    .par_chunks_mut(ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM),
            )
            .enumerate()
            .for_each(|(edge_index, (grad_edge, grad_matrix))| {
                let target = edge_targets[edge_index];
                let grad_node_start = target * ESEN_OAM_NODE_FEATURE_DIM;
                let edge_input_start = edge_index * ESEN_OAM_COMPACT_M_FEATURE_DIM;
                let matrix_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM;
                accumulate_compact_inverse_rotate_scatter_edge_vjp(
                    &compact_wigner_inv[matrix_start
                        ..matrix_start + ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM],
                    &edge_compact_features
                        [edge_input_start..edge_input_start + ESEN_OAM_COMPACT_M_FEATURE_DIM],
                    &grad_node_features
                        [grad_node_start..grad_node_start + ESEN_OAM_NODE_FEATURE_DIM],
                    scale,
                    grad_edge,
                    grad_matrix,
                    assume_block_diagonal_wigner,
                );
            });
        return Ok(());
    }

    esen_oam_compact_inverse_rotate_scatter_vjp_blas_fallback(
        node_count,
        edge_targets,
        scale,
        compact_wigner_inv,
        edge_compact_features,
        grad_node_features,
        grad_edge_compact_features,
        grad_compact_wigner_inv,
    )
}

#[cfg(feature = "parallel")]
#[allow(clippy::too_many_arguments)]
fn esen_oam_compact_inverse_rotate_scatter_enveloped_full_wigner_vjp_prepared_m_major_grad_out(
    node_count: usize,
    edge_targets: &[usize],
    rescale_factor: f64,
    compact_wigner_inv: &[f64],
    modulated_edge_compact_features: &[f64],
    edge_distances: &[f64],
    cutoff: f64,
    exponent: usize,
    grad_node_features: &[f64],
    grad_edge_features_before_envelope_m_major: &mut [f64],
    grad_edge_distances: &mut [f64],
    grad_wigner_inv: &mut [f64],
    assume_block_diagonal_wigner: bool,
) -> Result<(), ModelError> {
    let edge_count = edge_targets.len();
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP node features",
        node_count * ESEN_OAM_NODE_FEATURE_DIM,
        grad_node_features.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP compact Wigner inverse",
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM,
        compact_wigner_inv.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP modulated compact edge features",
        edge_count * ESEN_OAM_COMPACT_M_FEATURE_DIM,
        modulated_edge_compact_features.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP edge distances",
        edge_count,
        edge_distances.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP edge feature gradient",
        edge_count * ESEN_OAM_COMPACT_M_FEATURE_DIM,
        grad_edge_features_before_envelope_m_major.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP distance gradient",
        edge_count,
        grad_edge_distances.len(),
    )?;
    check_esen_oam_len(
        "eSEN-OAM fused inverse-rotate/envelope m-major VJP Wigner inverse gradient",
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM,
        grad_wigner_inv.len(),
    )?;
    if !rescale_factor.is_finite() || rescale_factor == 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused inverse-rotate/envelope m-major VJP rescale factor must be finite and nonzero, got {rescale_factor}"
        )));
    }
    if !cutoff.is_finite() || cutoff <= 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM fused inverse-rotate/envelope m-major VJP cutoff must be positive finite, got {cutoff}"
        )));
    }
    if exponent == 0 {
        return Err(invalid_manifest(
            "eSEN-OAM fused inverse-rotate/envelope m-major VJP exponent must be positive",
        ));
    }
    for (edge_index, &target) in edge_targets.iter().enumerate() {
        if target >= node_count {
            return Err(invalid_manifest(format!(
                "eSEN-OAM fused inverse-rotate/envelope m-major VJP edge {edge_index} has out-of-range target {target} for {node_count} nodes"
            )));
        }
    }

    let scale = 1.0 / rescale_factor;
    grad_edge_features_before_envelope_m_major
        .par_chunks_mut(ESEN_OAM_COMPACT_M_FEATURE_DIM)
        .zip(grad_wigner_inv.par_chunks_mut(ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM))
        .zip(grad_edge_distances.par_iter_mut())
        .enumerate()
        .for_each(
            |(edge_index, ((grad_edge_m_major, grad_wigner_edge), grad_distance))| {
                grad_edge_m_major.fill(0.0);
                let target = edge_targets[edge_index];
                let grad_node_start = target * ESEN_OAM_NODE_FEATURE_DIM;
                let edge_input_start = edge_index * ESEN_OAM_COMPACT_M_FEATURE_DIM;
                let matrix_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM;
                let modulated_edge = &modulated_edge_compact_features
                    [edge_input_start..edge_input_start + ESEN_OAM_COMPACT_M_FEATURE_DIM];

                accumulate_compact_inverse_rotate_scatter_edge_full_wigner_vjp_m_major_grad_out(
                    &compact_wigner_inv[matrix_start
                        ..matrix_start + ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM],
                    modulated_edge,
                    &grad_node_features
                        [grad_node_start..grad_node_start + ESEN_OAM_NODE_FEATURE_DIM],
                    scale,
                    grad_edge_m_major,
                    grad_wigner_edge,
                    assume_block_diagonal_wigner,
                );

                let envelope = fairchem_esen_polynomial_envelope_forward_unchecked(
                    edge_distances[edge_index] / cutoff,
                    exponent,
                );
                let mut grad_envelope = 0.0;
                if envelope.value != 0.0 {
                    let inv_envelope = envelope.value.recip();
                    for (compact_l_major, &m_major) in ESEN_OAM_COMPACT_L_TO_M_COEFFICIENT_INDICES
                        .iter()
                        .enumerate()
                    {
                        let l_major_start = compact_l_major * ESEN_OAM_CHANNELS;
                        let m_major_start = m_major * ESEN_OAM_CHANNELS;
                        for channel in 0..ESEN_OAM_CHANNELS {
                            let grad = grad_edge_m_major[m_major_start + channel];
                            grad_edge_m_major[m_major_start + channel] = grad * envelope.value;
                            grad_envelope +=
                                grad * modulated_edge[l_major_start + channel] * inv_envelope;
                        }
                    }
                } else {
                    grad_edge_m_major.fill(0.0);
                }
                *grad_distance += grad_envelope * envelope.derivative / cutoff;
            },
        );
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn esen_oam_compact_inverse_rotate_scatter_vjp_blas_fallback(
    node_count: usize,
    edge_targets: &[usize],
    scale: f64,
    compact_wigner_inv: &[f64],
    edge_compact_features: &[f64],
    grad_node_features: &[f64],
    grad_edge_compact_features: &mut [f64],
    grad_compact_wigner_inv: &mut [f64],
) -> Result<(), ModelError> {
    let edge_count = edge_targets.len();
    let mut grad_edge_messages = vec![0.0; edge_count * ESEN_OAM_NODE_FEATURE_DIM];
    for (edge_index, &target) in edge_targets.iter().enumerate() {
        debug_assert!(target < node_count);
        let edge_start = edge_index * ESEN_OAM_NODE_FEATURE_DIM;
        let node_start = target * ESEN_OAM_NODE_FEATURE_DIM;
        for feature in 0..ESEN_OAM_NODE_FEATURE_DIM {
            grad_edge_messages[edge_start + feature] +=
                scale * grad_node_features[node_start + feature];
        }
    }
    let config = EsenSo3BatchedMatmulConfig::new(
        ESEN_OAM_COMPACT_M_BASIS_DIM,
        ESEN_OAM_BASIS_DIM,
        ESEN_OAM_CHANNELS,
    )?;
    fairchem_esen_so3_batched_matmul_vjp_input(
        config,
        compact_wigner_inv,
        &grad_edge_messages,
        grad_edge_compact_features,
    )?;
    fairchem_esen_so3_batched_matmul_vjp_matrix(
        config,
        edge_compact_features,
        &grad_edge_messages,
        grad_compact_wigner_inv,
    )?;
    Ok(())
}

#[cfg(feature = "parallel")]
fn accumulate_compact_inverse_rotate_scatter_edge_vjp(
    compact_wigner_inv: &[f64],
    edge_compact_features: &[f64],
    grad_node_feature: &[f64],
    scale: f64,
    grad_edge_compact_features: &mut [f64],
    grad_compact_wigner_inv: &mut [f64],
    assume_block_diagonal_wigner: bool,
) {
    debug_assert_eq!(
        compact_wigner_inv.len(),
        ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM
    );
    debug_assert_eq!(edge_compact_features.len(), ESEN_OAM_COMPACT_M_FEATURE_DIM);
    debug_assert_eq!(grad_node_feature.len(), ESEN_OAM_NODE_FEATURE_DIM);
    debug_assert_eq!(
        grad_edge_compact_features.len(),
        ESEN_OAM_COMPACT_M_FEATURE_DIM
    );
    debug_assert_eq!(
        grad_compact_wigner_inv.len(),
        ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM
    );

    for out_coefficient in 0..ESEN_OAM_BASIS_DIM {
        let grad_node_row_start = out_coefficient * ESEN_OAM_CHANNELS;
        let matrix_row_start = out_coefficient * ESEN_OAM_COMPACT_M_BASIS_DIM;
        let (input_start_coefficient, input_end_coefficient) =
            esen_oam_compact_wigner_compact_input_range_for_full_row(
                out_coefficient,
                assume_block_diagonal_wigner,
            );
        for in_coefficient in input_start_coefficient..input_end_coefficient {
            let input_row_start = in_coefficient * ESEN_OAM_CHANNELS;
            let matrix_index = matrix_row_start + in_coefficient;
            let weight = compact_wigner_inv[matrix_index];
            let mut matrix_grad = 0.0;
            for channel in 0..ESEN_OAM_CHANNELS {
                let grad = scale * grad_node_feature[grad_node_row_start + channel];
                grad_edge_compact_features[input_row_start + channel] += weight * grad;
                matrix_grad += grad * edge_compact_features[input_row_start + channel];
            }
            grad_compact_wigner_inv[matrix_index] += matrix_grad;
        }
    }
}

#[cfg(feature = "parallel")]
#[allow(clippy::too_many_arguments)]
fn accumulate_compact_inverse_rotate_scatter_edge_full_wigner_vjp_m_major_grad_out(
    compact_wigner_inv: &[f64],
    edge_compact_features_l_major: &[f64],
    grad_node_feature: &[f64],
    scale: f64,
    grad_edge_compact_features_m_major: &mut [f64],
    grad_wigner_inv: &mut [f64],
    assume_block_diagonal_wigner: bool,
) {
    debug_assert_eq!(
        compact_wigner_inv.len(),
        ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM
    );
    debug_assert_eq!(
        edge_compact_features_l_major.len(),
        ESEN_OAM_COMPACT_M_FEATURE_DIM
    );
    debug_assert_eq!(grad_node_feature.len(), ESEN_OAM_NODE_FEATURE_DIM);
    debug_assert_eq!(
        grad_edge_compact_features_m_major.len(),
        ESEN_OAM_COMPACT_M_FEATURE_DIM
    );
    debug_assert_eq!(
        grad_wigner_inv.len(),
        ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM
    );

    for out_coefficient in 0..ESEN_OAM_BASIS_DIM {
        let grad_node_row_start = out_coefficient * ESEN_OAM_CHANNELS;
        let compact_matrix_row_start = out_coefficient * ESEN_OAM_COMPACT_M_BASIS_DIM;
        let full_matrix_row_start = out_coefficient * ESEN_OAM_BASIS_DIM;
        let (input_start_coefficient, input_end_coefficient) =
            esen_oam_compact_wigner_compact_input_range_for_full_row(
                out_coefficient,
                assume_block_diagonal_wigner,
            );
        for (compact_in_coefficient, &full_in_coefficient) in
            ESEN_OAM_COMPACT_FULL_COEFFICIENT_INDICES
                .iter()
                .enumerate()
                .take(input_end_coefficient)
                .skip(input_start_coefficient)
        {
            let input_l_major_row_start = compact_in_coefficient * ESEN_OAM_CHANNELS;
            let input_m_major_row_start = ESEN_OAM_COMPACT_L_TO_M_COEFFICIENT_INDICES
                [compact_in_coefficient]
                * ESEN_OAM_CHANNELS;
            let compact_matrix_index = compact_matrix_row_start + compact_in_coefficient;
            let weight = compact_wigner_inv[compact_matrix_index];
            let mut matrix_grad = 0.0;
            for channel in 0..ESEN_OAM_CHANNELS {
                let grad = scale * grad_node_feature[grad_node_row_start + channel];
                grad_edge_compact_features_m_major[input_m_major_row_start + channel] +=
                    weight * grad;
                matrix_grad +=
                    grad * edge_compact_features_l_major[input_l_major_row_start + channel];
            }
            grad_wigner_inv[full_matrix_row_start + full_in_coefficient] += matrix_grad;
        }
    }
}

fn select_esen_oam_compact_wigner_inv_columns(full_wigner_inv: &[f64], compact: &mut [f64]) {
    debug_assert_eq!(
        full_wigner_inv.len() % (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM),
        0
    );
    let edge_count = full_wigner_inv.len() / (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM);
    debug_assert_eq!(
        compact.len(),
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM
    );

    for edge_index in 0..edge_count {
        let full_edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        let compact_edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM;
        for row in 0..ESEN_OAM_BASIS_DIM {
            for (compact_col, &full_col) in
                ESEN_OAM_COMPACT_FULL_COEFFICIENT_INDICES.iter().enumerate()
            {
                compact[compact_edge_start + row * ESEN_OAM_COMPACT_M_BASIS_DIM + compact_col] =
                    full_wigner_inv[full_edge_start + row * ESEN_OAM_BASIS_DIM + full_col];
            }
        }
    }
}

fn select_esen_oam_compact_wigner_rows(full_wigner: &[f64], compact: &mut [f64]) {
    debug_assert_eq!(
        full_wigner.len() % (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM),
        0
    );
    let edge_count = full_wigner.len() / (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM);
    debug_assert_eq!(
        compact.len(),
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM
    );

    for edge_index in 0..edge_count {
        let full_edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        let compact_edge_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        for (compact_row, &full_row) in ESEN_OAM_COMPACT_FULL_COEFFICIENT_INDICES.iter().enumerate()
        {
            let full_start = full_edge_start + full_row * ESEN_OAM_BASIS_DIM;
            let compact_start = compact_edge_start + compact_row * ESEN_OAM_BASIS_DIM;
            compact[compact_start..compact_start + ESEN_OAM_BASIS_DIM]
                .copy_from_slice(&full_wigner[full_start..full_start + ESEN_OAM_BASIS_DIM]);
        }
    }
}

fn scatter_esen_oam_compact_wigner_inv_columns_vjp(compact_grad: &[f64], full_grad: &mut [f64]) {
    debug_assert_eq!(
        full_grad.len() % (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM),
        0
    );
    let edge_count = full_grad.len() / (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM);
    debug_assert_eq!(
        compact_grad.len(),
        edge_count * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM
    );

    for edge_index in 0..edge_count {
        let full_edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        let compact_edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_COMPACT_M_BASIS_DIM;
        for row in 0..ESEN_OAM_BASIS_DIM {
            for (compact_col, &full_col) in
                ESEN_OAM_COMPACT_FULL_COEFFICIENT_INDICES.iter().enumerate()
            {
                full_grad[full_edge_start + row * ESEN_OAM_BASIS_DIM + full_col] += compact_grad
                    [compact_edge_start + row * ESEN_OAM_COMPACT_M_BASIS_DIM + compact_col];
            }
        }
    }
}

fn scatter_esen_oam_compact_wigner_rows_to_wigner_inv_vjp(
    compact_wigner_grad: &[f64],
    full_wigner_inv_grad: &mut [f64],
) {
    debug_assert_eq!(
        full_wigner_inv_grad.len() % (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM),
        0
    );
    let edge_count = full_wigner_inv_grad.len() / (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM);
    debug_assert_eq!(
        compact_wigner_grad.len(),
        edge_count * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM
    );

    for edge_index in 0..edge_count {
        let full_edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        let compact_edge_start = edge_index * ESEN_OAM_COMPACT_M_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        for (compact_row, &full_wigner_row) in
            ESEN_OAM_COMPACT_FULL_COEFFICIENT_INDICES.iter().enumerate()
        {
            for col in 0..ESEN_OAM_BASIS_DIM {
                let grad_wigner = compact_wigner_grad
                    [compact_edge_start + compact_row * ESEN_OAM_BASIS_DIM + col];
                full_wigner_inv_grad
                    [full_edge_start + col * ESEN_OAM_BASIS_DIM + full_wigner_row] += grad_wigner;
            }
        }
    }
}

fn check_len(op: &'static str, expected: usize, actual: usize) -> Result<(), ModelError> {
    if expected != actual {
        return Err(invalid_manifest(format!(
            "{op} length mismatch: expected {expected}, got {actual}"
        )));
    }
    Ok(())
}

fn check_esen_oam_len(op: &'static str, expected: usize, actual: usize) -> Result<(), ModelError> {
    check_len(op, expected, actual)
}

fn full_pbc_cell_for_stress_virial<'a>(
    architecture: &str,
    pbc: [bool; 3],
    cell: Option<&'a Cell>,
) -> Result<&'a Cell, ModelError> {
    if pbc != [true; 3] {
        return Err(ModelError::ArchitectureNotImplemented(format!(
            "{architecture} stress/virial requires full PBC"
        )));
    }
    cell.ok_or_else(|| {
        ModelError::ArchitectureNotImplemented(format!(
            "{architecture} stress/virial requires a cell"
        ))
    })
}

fn stress_virial_from_displacement_gradient(
    architecture: &str,
    pbc: [bool; 3],
    cell: Option<&Cell>,
    displacement_gradient: Mat3,
    options: &PredictionOptions,
) -> Result<(Option<Mat3>, Option<Mat3>), ModelError> {
    let displacement_gradient = symmetric_part(displacement_gradient);
    let cell = full_pbc_cell_for_stress_virial(architecture, pbc, cell)?;
    let stress = if options.compute_stress {
        Some(stress_from_displacement_gradient(
            displacement_gradient,
            cell,
        )?)
    } else {
        None
    };
    let virial = if options.compute_virial {
        Some(virial_from_displacement_gradient(displacement_gradient))
    } else {
        None
    };
    Ok((stress, virial))
}

#[must_use]
fn symmetric_part(matrix: Mat3) -> Mat3 {
    let mut out = matrix;
    for row in 0..3 {
        for col in 0..row {
            let value = 0.5 * (matrix[row][col] + matrix[col][row]);
            out[row][col] = value;
            out[col][row] = value;
        }
    }
    out
}

fn transpose_esen_oam_batched_wigner_inv(wigner_inv: &[f64], wigner: &mut [f64]) {
    debug_assert_eq!(wigner_inv.len(), wigner.len());
    debug_assert_eq!(
        wigner_inv.len() % (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM),
        0
    );
    let edge_count = wigner_inv.len() / (ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM);
    for edge_index in 0..edge_count {
        let edge_start = edge_index * ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM;
        for row in 0..ESEN_OAM_BASIS_DIM {
            for col in 0..ESEN_OAM_BASIS_DIM {
                wigner[edge_start + row * ESEN_OAM_BASIS_DIM + col] =
                    wigner_inv[edge_start + col * ESEN_OAM_BASIS_DIM + row];
            }
        }
    }
}

fn compute_esen_oam_wigner_inv_from_project_edge_vector(
    project_edge_vector: [f64; 3],
    tensors: &EsenOamRuntimeTensorView<'_>,
    out: &mut [f64],
) -> Result<(), ModelError> {
    check_len(
        "eSEN-OAM per-edge wigner_inv",
        ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM,
        out.len(),
    )?;
    let angles = esen_oam_wigner_angles_from_project_edge_vector(project_edge_vector)?;

    let mut wigner = vec![0.0; ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM];
    let mut block_start = 0;
    for degree in 0..=ESEN_OAM_L_MAX {
        let block_dim = 2 * degree + 1;
        let mut block = vec![0.0; block_dim * block_dim];
        esen_oam_wigner_d_block(
            degree,
            angles.alpha,
            angles.beta,
            angles.gamma,
            tensors.wigner_jd[degree],
            &mut block,
        )?;
        for row in 0..block_dim {
            for col in 0..block_dim {
                wigner[(block_start + row) * ESEN_OAM_BASIS_DIM + block_start + col] =
                    block[row * block_dim + col];
            }
        }
        block_start += block_dim;
    }
    for row in 0..ESEN_OAM_BASIS_DIM {
        for col in 0..ESEN_OAM_BASIS_DIM {
            out[row * ESEN_OAM_BASIS_DIM + col] = wigner[col * ESEN_OAM_BASIS_DIM + row];
        }
    }
    Ok(())
}

fn esen_oam_wigner_angles_from_project_edge_vector(
    project_edge_vector: [f64; 3],
) -> Result<EsenOamWignerAngles, ModelError> {
    // FairChem's eSEN graph convention passes R_source - R_target to
    // init_edge_rot_mat, opposite to the project edge vector R_target - R_source.
    let edge_vec = [
        -project_edge_vector[0],
        -project_edge_vector[1],
        -project_edge_vector[2],
    ];
    let norm_x = normalized_esen_oam_vec3(edge_vec, "eSEN-OAM edge vector")?;
    let y_axis = [0.0, 1.0, 0.0];
    let z_axis = [0.0, 0.0, 1.0];
    let helper = if esen_oam_dot3(norm_x, z_axis).abs() < 0.99 {
        z_axis
    } else {
        y_axis
    };
    let norm_z = normalized_esen_oam_vec3(esen_oam_cross3(norm_x, helper), "eSEN-OAM z frame")?;
    let norm_y = normalized_esen_oam_vec3(esen_oam_cross3(norm_x, norm_z), "eSEN-OAM y frame")?;
    let edge_rot_mat = [
        [norm_z[0], norm_z[1], norm_z[2]],
        [norm_x[0], norm_x[1], norm_x[2]],
        [-norm_y[0], -norm_y[1], -norm_y[2]],
    ];

    let rotated_y = [edge_rot_mat[0][1], edge_rot_mat[1][1], edge_rot_mat[2][1]];
    let angles_vec = normalized_esen_oam_vec3(rotated_y, "eSEN-OAM angle vector")?;
    let beta = angles_vec[1].clamp(-1.0, 1.0).acos();
    let alpha = angles_vec[0].atan2(angles_vec[2]);
    let angle_matrix = esen_oam_angles_to_matrix(alpha, beta, 0.0);
    let angle_matrix_t = esen_oam_transpose3(angle_matrix);
    let residual = esen_oam_mat3_mul(angle_matrix_t, edge_rot_mat);
    let gamma = residual[0][2].atan2(residual[0][0]);

    Ok(EsenOamWignerAngles { alpha, beta, gamma })
}

fn esen_oam_wigner_d_block(
    degree: usize,
    alpha: f64,
    beta: f64,
    gamma: f64,
    jd: &[f64],
    out: &mut [f64],
) -> Result<(), ModelError> {
    let dim = 2 * degree + 1;
    check_len("eSEN-OAM Jd block", dim * dim, jd.len())?;
    check_len("eSEN-OAM Wigner-D block", dim * dim, out.len())?;
    let xa = esen_oam_z_rot_mat(degree, alpha);
    let xb = esen_oam_z_rot_mat(degree, beta);
    let xc = esen_oam_z_rot_mat(degree, gamma);
    let mut tmp0 = vec![0.0; dim * dim];
    let mut tmp1 = vec![0.0; dim * dim];
    let mut tmp2 = vec![0.0; dim * dim];
    let mut tmp3 = vec![0.0; dim * dim];
    esen_oam_square_matmul(dim, &xa, jd, &mut tmp0);
    esen_oam_square_matmul(dim, &tmp0, &xb, &mut tmp1);
    esen_oam_square_matmul(dim, &tmp1, jd, &mut tmp2);
    esen_oam_square_matmul(dim, &tmp2, &xc, &mut tmp3);
    out.copy_from_slice(&tmp3);
    Ok(())
}

fn esen_oam_wigner_d_block_angle_vjp(
    degree: usize,
    angles: EsenOamWignerAngles,
    jd: &[f64],
    grad_out: &[f64],
) -> Result<EsenOamWignerAngles, ModelError> {
    let dim = 2 * degree + 1;
    check_len("eSEN-OAM Jd block", dim * dim, jd.len())?;
    check_len(
        "eSEN-OAM Wigner-D block gradient",
        dim * dim,
        grad_out.len(),
    )?;
    let xa = esen_oam_z_rot_mat(degree, angles.alpha);
    let xb = esen_oam_z_rot_mat(degree, angles.beta);
    let xc = esen_oam_z_rot_mat(degree, angles.gamma);
    let dxa = esen_oam_z_rot_mat_derivative(degree, angles.alpha);
    let dxb = esen_oam_z_rot_mat_derivative(degree, angles.beta);
    let dxc = esen_oam_z_rot_mat_derivative(degree, angles.gamma);

    let mut tmp0 = vec![0.0; dim * dim];
    let mut tmp1 = vec![0.0; dim * dim];
    let mut tmp2 = vec![0.0; dim * dim];
    let mut derivative = vec![0.0; dim * dim];

    esen_oam_square_matmul(dim, &dxa, jd, &mut tmp0);
    esen_oam_square_matmul(dim, &tmp0, &xb, &mut tmp1);
    esen_oam_square_matmul(dim, &tmp1, jd, &mut tmp2);
    esen_oam_square_matmul(dim, &tmp2, &xc, &mut derivative);
    let grad_alpha = esen_oam_dot_flat(&derivative, grad_out);

    esen_oam_square_matmul(dim, &xa, jd, &mut tmp0);
    esen_oam_square_matmul(dim, &tmp0, &dxb, &mut tmp1);
    esen_oam_square_matmul(dim, &tmp1, jd, &mut tmp2);
    esen_oam_square_matmul(dim, &tmp2, &xc, &mut derivative);
    let grad_beta = esen_oam_dot_flat(&derivative, grad_out);

    esen_oam_square_matmul(dim, &xa, jd, &mut tmp0);
    esen_oam_square_matmul(dim, &tmp0, &xb, &mut tmp1);
    esen_oam_square_matmul(dim, &tmp1, jd, &mut tmp2);
    esen_oam_square_matmul(dim, &tmp2, &dxc, &mut derivative);
    let grad_gamma = esen_oam_dot_flat(&derivative, grad_out);

    Ok(EsenOamWignerAngles {
        alpha: grad_alpha,
        beta: grad_beta,
        gamma: grad_gamma,
    })
}

fn esen_oam_z_rot_mat(degree: usize, angle: f64) -> Vec<f64> {
    let dim = 2 * degree + 1;
    let mut out = vec![0.0; dim * dim];
    for index in 0..dim {
        let frequency = degree as isize - index as isize;
        let phase = frequency as f64 * angle;
        out[index * dim + (dim - 1 - index)] = phase.sin();
        out[index * dim + index] = phase.cos();
    }
    out
}

fn esen_oam_z_rot_mat_derivative(degree: usize, angle: f64) -> Vec<f64> {
    let dim = 2 * degree + 1;
    let mut out = vec![0.0; dim * dim];
    for index in 0..dim {
        let frequency = degree as isize - index as isize;
        let frequency_f64 = frequency as f64;
        let phase = frequency_f64 * angle;
        out[index * dim + (dim - 1 - index)] = frequency_f64 * phase.cos();
        out[index * dim + index] = -frequency_f64 * phase.sin();
    }
    out
}

fn esen_oam_dot_flat(lhs: &[f64], rhs: &[f64]) -> f64 {
    debug_assert_eq!(lhs.len(), rhs.len());
    lhs.iter()
        .zip(rhs.iter())
        .map(|(left, right)| left * right)
        .sum()
}

fn esen_oam_square_matmul(dim: usize, lhs: &[f64], rhs: &[f64], out: &mut [f64]) {
    debug_assert_eq!(lhs.len(), dim * dim);
    debug_assert_eq!(rhs.len(), dim * dim);
    debug_assert_eq!(out.len(), dim * dim);
    for row in 0..dim {
        for col in 0..dim {
            let mut value = 0.0;
            for inner in 0..dim {
                value += lhs[row * dim + inner] * rhs[inner * dim + col];
            }
            out[row * dim + col] = value;
        }
    }
}

fn esen_oam_angles_to_matrix(alpha: f64, beta: f64, gamma: f64) -> [[f64; 3]; 3] {
    esen_oam_mat3_mul(
        esen_oam_mat3_mul(esen_oam_matrix_y(alpha), esen_oam_matrix_x(beta)),
        esen_oam_matrix_y(gamma),
    )
}

fn esen_oam_matrix_x(angle: f64) -> [[f64; 3]; 3] {
    let c = angle.cos();
    let s = angle.sin();
    [[1.0, 0.0, 0.0], [0.0, c, -s], [0.0, s, c]]
}

fn esen_oam_matrix_y(angle: f64) -> [[f64; 3]; 3] {
    let c = angle.cos();
    let s = angle.sin();
    [[c, 0.0, s], [0.0, 1.0, 0.0], [-s, 0.0, c]]
}

fn esen_oam_mat3_mul(lhs: [[f64; 3]; 3], rhs: [[f64; 3]; 3]) -> [[f64; 3]; 3] {
    let mut out = [[0.0; 3]; 3];
    for row in 0..3 {
        for col in 0..3 {
            out[row][col] =
                lhs[row][0] * rhs[0][col] + lhs[row][1] * rhs[1][col] + lhs[row][2] * rhs[2][col];
        }
    }
    out
}

fn esen_oam_transpose3(matrix: [[f64; 3]; 3]) -> [[f64; 3]; 3] {
    [
        [matrix[0][0], matrix[1][0], matrix[2][0]],
        [matrix[0][1], matrix[1][1], matrix[2][1]],
        [matrix[0][2], matrix[1][2], matrix[2][2]],
    ]
}

fn normalized_esen_oam_vec3(vector: [f64; 3], label: &'static str) -> Result<[f64; 3], ModelError> {
    let norm = esen_oam_dot3(vector, vector).sqrt();
    if !norm.is_finite() || norm <= 0.0 {
        return Err(invalid_manifest(format!(
            "{label} must have finite positive norm, got {norm}"
        )));
    }
    Ok([vector[0] / norm, vector[1] / norm, vector[2] / norm])
}

fn esen_oam_dot3(lhs: [f64; 3], rhs: [f64; 3]) -> f64 {
    lhs[0] * rhs[0] + lhs[1] * rhs[1] + lhs[2] * rhs[2]
}

fn esen_oam_cross3(lhs: [f64; 3], rhs: [f64; 3]) -> [f64; 3] {
    [
        lhs[1] * rhs[2] - lhs[2] * rhs[1],
        lhs[2] * rhs[0] - lhs[0] * rhs[2],
        lhs[0] * rhs[1] - lhs[1] * rhs[0],
    ]
}

fn esen_oam_gaussian_smearing_from_offsets(
    distance: f64,
    offsets: &[f64],
    out: &mut [f64],
) -> Result<(), ModelError> {
    if offsets.len() != out.len() || offsets.len() < 2 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM Gaussian distance expansion requires matching nontrivial offsets/out lengths, got offsets={} out={}",
            offsets.len(),
            out.len()
        )));
    }
    let step = offsets[1] - offsets[0];
    if !step.is_finite() || step <= 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM Gaussian distance expansion offset step must be finite and positive, got {step}"
        )));
    }
    let width = 2.0 * step;
    let coeff = -0.5 / (width * width);
    for (value, offset) in out.iter_mut().zip(offsets) {
        let delta = distance - offset;
        *value = (coeff * delta * delta).exp();
    }
    Ok(())
}

fn esen_oam_gaussian_smearing_from_offsets_vjp(
    distance: f64,
    offsets: &[f64],
    values: &[f64],
    grad_values: &[f64],
) -> Result<f64, ModelError> {
    if offsets.len() != values.len() || offsets.len() != grad_values.len() || offsets.len() < 2 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM Gaussian VJP requires matching nontrivial offsets/value/grad lengths, got offsets={} values={} grads={}",
            offsets.len(),
            values.len(),
            grad_values.len()
        )));
    }
    let step = offsets[1] - offsets[0];
    if !step.is_finite() || step <= 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM Gaussian VJP offset step must be finite and positive, got {step}"
        )));
    }
    let width = 2.0 * step;
    let coeff = -0.5 / (width * width);
    let mut grad_distance = 0.0;
    for ((&offset, &value), &grad_value) in offsets.iter().zip(values).zip(grad_values) {
        let derivative = value * 2.0 * coeff * (distance - offset);
        grad_distance += grad_value * derivative;
    }
    Ok(grad_distance)
}

fn esen_oam_wigner_inv_edge_vector_vjp(
    project_edge_vector: [f64; 3],
    tensors: &EsenOamRuntimeTensorView<'_>,
    grad_wigner_inv: &[f64],
) -> Result<[f64; 3], ModelError> {
    check_len(
        "eSEN-OAM Wigner edge-vector VJP matrix gradient",
        ESEN_OAM_BASIS_DIM * ESEN_OAM_BASIS_DIM,
        grad_wigner_inv.len(),
    )?;
    let angles = esen_oam_wigner_angles_from_project_edge_vector(project_edge_vector)?;
    let mut grad_angles = EsenOamWignerAngles {
        alpha: 0.0,
        beta: 0.0,
        gamma: 0.0,
    };
    let mut block_start = 0;
    for degree in 0..=ESEN_OAM_L_MAX {
        let block_dim = 2 * degree + 1;
        let mut grad_block = vec![0.0; block_dim * block_dim];
        for row in 0..block_dim {
            for col in 0..block_dim {
                grad_block[row * block_dim + col] =
                    grad_wigner_inv[(block_start + col) * ESEN_OAM_BASIS_DIM + block_start + row];
            }
        }
        let block_grad = esen_oam_wigner_d_block_angle_vjp(
            degree,
            angles,
            tensors.wigner_jd[degree],
            &grad_block,
        )?;
        grad_angles.alpha += block_grad.alpha;
        grad_angles.beta += block_grad.beta;
        grad_angles.gamma += block_grad.gamma;
        block_start += block_dim;
    }

    esen_oam_wigner_angles_edge_vector_vjp(project_edge_vector, grad_angles)
}

fn esen_oam_wigner_angles_edge_vector_vjp(
    project_edge_vector: [f64; 3],
    grad_angles: EsenOamWignerAngles,
) -> Result<[f64; 3], ModelError> {
    let edge_vec = [
        -project_edge_vector[0],
        -project_edge_vector[1],
        -project_edge_vector[2],
    ];
    let norm_x = normalized_esen_oam_vec3(edge_vec, "eSEN-OAM edge vector")?;
    let y_axis = [0.0, 1.0, 0.0];
    let z_axis = [0.0, 0.0, 1.0];
    let helper = if esen_oam_dot3(norm_x, z_axis).abs() < 0.99 {
        z_axis
    } else {
        y_axis
    };
    let norm_z_input = esen_oam_cross3(norm_x, helper);
    let norm_z = normalized_esen_oam_vec3(norm_z_input, "eSEN-OAM z frame")?;
    let norm_y_input = esen_oam_cross3(norm_x, norm_z);
    let norm_y = normalized_esen_oam_vec3(norm_y_input, "eSEN-OAM y frame")?;
    let edge_rot_mat = [
        [norm_z[0], norm_z[1], norm_z[2]],
        [norm_x[0], norm_x[1], norm_x[2]],
        [-norm_y[0], -norm_y[1], -norm_y[2]],
    ];
    let rotated_y = [edge_rot_mat[0][1], edge_rot_mat[1][1], edge_rot_mat[2][1]];
    let angles_vec = normalized_esen_oam_vec3(rotated_y, "eSEN-OAM angle vector")?;
    let beta_clamped = angles_vec[1].clamp(-1.0, 1.0);
    let beta_sin_sq = 1.0 - beta_clamped * beta_clamped;
    if beta_sin_sq <= 1.0e-20 {
        return esen_oam_wigner_angles_edge_vector_vjp_by_fd(project_edge_vector, grad_angles);
    }
    let beta = beta_clamped.acos();
    let alpha_den = angles_vec[0] * angles_vec[0] + angles_vec[2] * angles_vec[2];
    if alpha_den <= 1.0e-20 {
        return esen_oam_wigner_angles_edge_vector_vjp_by_fd(project_edge_vector, grad_angles);
    }
    let alpha = angles_vec[0].atan2(angles_vec[2]);
    let angle_matrix = esen_oam_angles_to_matrix(alpha, beta, 0.0);
    let angle_matrix_t = esen_oam_transpose3(angle_matrix);
    let residual = esen_oam_mat3_mul(angle_matrix_t, edge_rot_mat);
    let gamma_den = residual[0][2] * residual[0][2] + residual[0][0] * residual[0][0];
    if gamma_den <= 1.0e-20 {
        return esen_oam_wigner_angles_edge_vector_vjp_by_fd(project_edge_vector, grad_angles);
    }

    let mut grad_alpha = grad_angles.alpha;
    let mut grad_beta = grad_angles.beta;
    let mut grad_edge_rot_mat = [[0.0; 3]; 3];

    let mut grad_residual = [[0.0; 3]; 3];
    grad_residual[0][2] += grad_angles.gamma * residual[0][0] / gamma_den;
    grad_residual[0][0] -= grad_angles.gamma * residual[0][2] / gamma_den;

    let mut grad_angle_matrix = [[0.0; 3]; 3];
    for (row, grad_residual_row) in grad_residual.iter().enumerate() {
        for (col, grad_residual_value) in grad_residual_row.iter().enumerate() {
            for (inner, angle_matrix_row) in angle_matrix.iter().enumerate() {
                grad_angle_matrix[inner][row] += *grad_residual_value * edge_rot_mat[inner][col];
                grad_edge_rot_mat[inner][col] += angle_matrix_row[row] * *grad_residual_value;
            }
        }
    }
    grad_alpha += esen_oam_mat3_dot(
        esen_oam_mat3_mul(esen_oam_matrix_y_derivative(alpha), esen_oam_matrix_x(beta)),
        grad_angle_matrix,
    );
    grad_beta += esen_oam_mat3_dot(
        esen_oam_mat3_mul(esen_oam_matrix_y(alpha), esen_oam_matrix_x_derivative(beta)),
        grad_angle_matrix,
    );

    let mut grad_angles_vec = [0.0; 3];
    grad_angles_vec[0] += grad_alpha * angles_vec[2] / alpha_den;
    grad_angles_vec[2] -= grad_alpha * angles_vec[0] / alpha_den;
    grad_angles_vec[1] -= grad_beta / beta_sin_sq.sqrt();

    let grad_rotated_y = esen_oam_normalized_vec3_vjp(rotated_y, angles_vec, grad_angles_vec)?;
    grad_edge_rot_mat[0][1] += grad_rotated_y[0];
    grad_edge_rot_mat[1][1] += grad_rotated_y[1];
    grad_edge_rot_mat[2][1] += grad_rotated_y[2];

    let mut grad_norm_z = grad_edge_rot_mat[0];
    let mut grad_norm_x = grad_edge_rot_mat[1];
    let grad_norm_y = [
        -grad_edge_rot_mat[2][0],
        -grad_edge_rot_mat[2][1],
        -grad_edge_rot_mat[2][2],
    ];

    let grad_norm_y_input = esen_oam_normalized_vec3_vjp(norm_y_input, norm_y, grad_norm_y)?;
    let (grad_norm_x_from_y, grad_norm_z_from_y) =
        esen_oam_cross3_vjp(norm_x, norm_z, grad_norm_y_input);
    esen_oam_add3_assign(&mut grad_norm_x, grad_norm_x_from_y);
    esen_oam_add3_assign(&mut grad_norm_z, grad_norm_z_from_y);

    let grad_norm_z_input = esen_oam_normalized_vec3_vjp(norm_z_input, norm_z, grad_norm_z)?;
    let (grad_norm_x_from_z, _grad_helper) = esen_oam_cross3_vjp(norm_x, helper, grad_norm_z_input);
    esen_oam_add3_assign(&mut grad_norm_x, grad_norm_x_from_z);

    let grad_edge_vec = esen_oam_normalized_vec3_vjp(edge_vec, norm_x, grad_norm_x)?;
    Ok([-grad_edge_vec[0], -grad_edge_vec[1], -grad_edge_vec[2]])
}

fn esen_oam_wigner_angles_edge_vector_vjp_by_fd(
    project_edge_vector: [f64; 3],
    grad_angles: EsenOamWignerAngles,
) -> Result<[f64; 3], ModelError> {
    let mut grad_vector = [0.0; 3];
    let eps = 1.0e-6;
    for axis in 0..3 {
        let mut plus_vector = project_edge_vector;
        let mut minus_vector = project_edge_vector;
        plus_vector[axis] += eps;
        minus_vector[axis] -= eps;
        let plus = esen_oam_wigner_angles_from_project_edge_vector(plus_vector)?;
        let minus = esen_oam_wigner_angles_from_project_edge_vector(minus_vector)?;
        let inv_two_eps = 0.5 / eps;
        grad_vector[axis] =
            grad_angles.alpha * esen_oam_wrapped_angle_delta(plus.alpha, minus.alpha) * inv_two_eps
                + grad_angles.beta * (plus.beta - minus.beta) * inv_two_eps
                + grad_angles.gamma
                    * esen_oam_wrapped_angle_delta(plus.gamma, minus.gamma)
                    * inv_two_eps;
    }
    Ok(grad_vector)
}

fn esen_oam_normalized_vec3_vjp(
    input: [f64; 3],
    normalized: [f64; 3],
    grad_normalized: [f64; 3],
) -> Result<[f64; 3], ModelError> {
    let norm = esen_oam_dot3(input, input).sqrt();
    if !norm.is_finite() || norm <= 0.0 {
        return Err(invalid_manifest(format!(
            "eSEN-OAM normalized vector VJP input must have finite positive norm, got {norm}"
        )));
    }
    let projection = esen_oam_dot3(normalized, grad_normalized);
    Ok([
        (grad_normalized[0] - normalized[0] * projection) / norm,
        (grad_normalized[1] - normalized[1] * projection) / norm,
        (grad_normalized[2] - normalized[2] * projection) / norm,
    ])
}

fn esen_oam_cross3_vjp(lhs: [f64; 3], rhs: [f64; 3], grad_out: [f64; 3]) -> ([f64; 3], [f64; 3]) {
    (
        esen_oam_cross3(rhs, grad_out),
        esen_oam_cross3(grad_out, lhs),
    )
}

fn esen_oam_add3_assign(acc: &mut [f64; 3], value: [f64; 3]) {
    acc[0] += value[0];
    acc[1] += value[1];
    acc[2] += value[2];
}

fn esen_oam_matrix_x_derivative(angle: f64) -> [[f64; 3]; 3] {
    let c = angle.cos();
    let s = angle.sin();
    [[0.0, 0.0, 0.0], [0.0, -s, -c], [0.0, c, -s]]
}

fn esen_oam_matrix_y_derivative(angle: f64) -> [[f64; 3]; 3] {
    let c = angle.cos();
    let s = angle.sin();
    [[-s, 0.0, c], [0.0, 0.0, 0.0], [-c, 0.0, -s]]
}

fn esen_oam_mat3_dot(lhs: [[f64; 3]; 3], rhs: [[f64; 3]; 3]) -> f64 {
    let mut value = 0.0;
    for row in 0..3 {
        for col in 0..3 {
            value += lhs[row][col] * rhs[row][col];
        }
    }
    value
}

fn esen_oam_wrapped_angle_delta(plus: f64, minus: f64) -> f64 {
    let mut delta = plus - minus;
    while delta > std::f64::consts::PI {
        delta -= 2.0 * std::f64::consts::PI;
    }
    while delta < -std::f64::consts::PI {
        delta += 2.0 * std::f64::consts::PI;
    }
    delta
}

fn copy_esen_oam_embedding_row(
    name: &str,
    weights: &[f64],
    row_index: usize,
    out: &mut [f64],
) -> Result<(), ModelError> {
    if out.len() != ESEN_OAM_CHANNELS {
        return Err(invalid_manifest(format!(
            "eSEN-OAM embedding output width must be {ESEN_OAM_CHANNELS}, got {}",
            out.len()
        )));
    }
    let row_start = row_index
        .checked_mul(ESEN_OAM_CHANNELS)
        .ok_or_else(|| invalid_manifest(format!("eSEN-OAM embedding {name} row overflows")))?;
    let row_end = row_start
        .checked_add(ESEN_OAM_CHANNELS)
        .ok_or_else(|| invalid_manifest(format!("eSEN-OAM embedding {name} row overflows")))?;
    if row_end > weights.len() {
        return Err(invalid_manifest(format!(
            "eSEN-OAM embedding {name} missing atomic-number row {row_index}"
        )));
    }
    out.copy_from_slice(&weights[row_start..row_end]);
    Ok(())
}

fn esen_oam_atomic_number_for_symbol(symbol: &str) -> Result<usize, ModelError> {
    ESEN_OAM_ELEMENT_SYMBOLS
        .iter()
        .position(|candidate| *candidate == symbol)
        .map(|index| index + 1)
        .ok_or_else(|| {
            invalid_manifest(format!(
                "eSEN-OAM supports element symbols H through Pu; got {symbol:?}"
            ))
        })
}

fn build_esen_oam_radial_mlp_runtime_tensors<'a>(
    store: &'a EsenOamTensorStore,
    prefix: &str,
    final_out_dim: usize,
) -> Result<EsenOamRadialMlpRuntimeTensors<'a>, ModelError> {
    Ok(EsenOamRadialMlpRuntimeTensors {
        input_weight: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.0.weight"),
            &[ESEN_OAM_CHANNELS, ESEN_OAM_EDGE_DEGREE_RADIAL_INPUT_DIM],
        )?,
        input_bias: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.0.bias"),
            &[ESEN_OAM_CHANNELS],
        )?,
        input_norm_weight: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.1.weight"),
            &[ESEN_OAM_CHANNELS],
        )?,
        input_norm_bias: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.1.bias"),
            &[ESEN_OAM_CHANNELS],
        )?,
        hidden_weight: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.3.weight"),
            &[ESEN_OAM_CHANNELS, ESEN_OAM_CHANNELS],
        )?,
        hidden_bias: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.3.bias"),
            &[ESEN_OAM_CHANNELS],
        )?,
        hidden_norm_weight: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.4.weight"),
            &[ESEN_OAM_CHANNELS],
        )?,
        hidden_norm_bias: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.4.bias"),
            &[ESEN_OAM_CHANNELS],
        )?,
        output_weight: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.6.weight"),
            &[final_out_dim, ESEN_OAM_CHANNELS],
        )?,
        output_bias: get_esen_oam_runtime_f64(
            store,
            &format!("{prefix}.net.6.bias"),
            &[final_out_dim],
        )?,
    })
}

fn get_esen_oam_runtime_f64<'a>(
    store: &'a EsenOamTensorStore,
    name: &str,
    shape: &[usize],
) -> Result<&'a [f64], ModelError> {
    let (actual_shape, values) = store
        .get_f64(name)
        .ok_or_else(|| ModelError::MissingTensor(name.to_owned()))?;
    if actual_shape != shape {
        return Err(invalid_manifest(format!(
            "eSEN-OAM runtime tensor {name} shape must be {shape:?}, got {actual_shape:?}"
        )));
    }
    Ok(values)
}

fn esen_json_path_name(path: &[&str]) -> String {
    path.join(".")
}

fn esen_json_path<'a>(
    value: &'a serde_json::Value,
    path: &[&str],
) -> Result<&'a serde_json::Value, ModelError> {
    let mut current = value;
    for key in path {
        current = current.get(*key).ok_or_else(|| {
            invalid_manifest(format!(
                "eSEN-OAM state JSON missing {}",
                esen_json_path_name(path)
            ))
        })?;
    }
    Ok(current)
}

fn expect_esen_json_str(
    value: &serde_json::Value,
    path: &[&str],
    expected: &str,
) -> Result<(), ModelError> {
    let field = esen_json_path_name(path);
    let actual = esen_json_path(value, path)?
        .as_str()
        .ok_or_else(|| invalid_manifest(format!("eSEN-OAM state JSON {field} must be a string")))?;
    expect_str(&format!("eSEN-OAM state JSON {field}"), actual, expected)
}

fn expect_esen_json_u64(
    value: &serde_json::Value,
    path: &[&str],
    expected: u64,
) -> Result<(), ModelError> {
    let field = esen_json_path_name(path);
    let actual = esen_json_path(value, path)?.as_u64().ok_or_else(|| {
        invalid_manifest(format!(
            "eSEN-OAM state JSON {field} must be an unsigned integer"
        ))
    })?;
    if actual == expected {
        Ok(())
    } else {
        Err(invalid_manifest(format!(
            "eSEN-OAM state JSON {field} must be {expected}, got {actual}"
        )))
    }
}

