fn validate_esen_oam_species_coverage(symbols: &[String]) -> Result<(), ModelError> {
    const EXPECTED_COUNT: usize = 94;
    if symbols.len() != EXPECTED_COUNT {
        return Err(invalid_manifest(format!(
            "eSEN-OAM species.symbols must contain Z=1..94 coverage, got {} symbols",
            symbols.len()
        )));
    }
    for (index, expected) in [
        (0, "H"),
        (5, "C"),
        (6, "N"),
        (7, "O"),
        (13, "Si"),
        (25, "Fe"),
        (92, "Np"),
        (93, "Pu"),
    ] {
        if symbols.get(index).map(String::as_str) != Some(expected) {
            return Err(invalid_manifest(format!(
                "eSEN-OAM species.symbols[{index}] must be {expected:?}"
            )));
        }
    }
    Ok(())
}

fn validate_esen_oam_tensor_spec(spec: &TensorSpec) -> Result<(), ModelError> {
    esen_oam_tensor_dtype_size(&spec.dtype)?;
    expect_str(
        &format!("eSEN-OAM tensor {} layout", spec.name),
        &spec.layout,
        "row-major",
    )?;
    if spec.name.trim().is_empty() {
        return Err(invalid_manifest("eSEN-OAM tensor name must not be empty"));
    }
    if spec.shape.contains(&0) {
        return Err(invalid_manifest(format!(
            "eSEN-OAM tensor {} shape dimensions must be nonzero, got {:?}",
            spec.name, spec.shape
        )));
    }
    validate_relative_path(&format!("eSEN-OAM tensor {} path", spec.name), &spec.path)?;
    product(&spec.shape)?;
    if let Some(sha256) = &spec.sha256 {
        if sha256.len() != SHA256_HEX_LEN || !sha256.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return Err(invalid_manifest(format!(
                "eSEN-OAM tensor {} sha256 must be a SHA256 hex digest",
                spec.name
            )));
        }
    }
    Ok(())
}

fn esen_oam_tensor_dtype_size(dtype: &str) -> Result<usize, ModelError> {
    match dtype {
        DTYPE_F64 => Ok(std::mem::size_of::<f64>()),
        DTYPE_F32 => Ok(std::mem::size_of::<f32>()),
        "i64" => Ok(std::mem::size_of::<i64>()),
        "i32" => Ok(std::mem::size_of::<i32>()),
        "bool" | "u8" => Ok(std::mem::size_of::<u8>()),
        other => Err(invalid_manifest(format!(
            "unsupported eSEN-OAM tensor dtype {other:?}; supported: f64, f32, i64, i32, bool, u8"
        ))),
    }
}

fn uma_tensor_dtype_size(dtype: &str) -> Result<usize, ModelError> {
    match dtype {
        DTYPE_F64 => Ok(std::mem::size_of::<f64>()),
        DTYPE_F32 => Ok(std::mem::size_of::<f32>()),
        "i64" => Ok(std::mem::size_of::<i64>()),
        "i32" => Ok(std::mem::size_of::<i32>()),
        "bool" | "u8" => Ok(std::mem::size_of::<u8>()),
        other => Err(invalid_manifest(format!(
            "unsupported UMA tensor dtype {other:?}; supported: f64, f32, i64, i32, bool, u8"
        ))),
    }
}

fn validate_uma_tensor_spec(spec: &TensorSpec) -> Result<(), ModelError> {
    uma_tensor_dtype_size(&spec.dtype)?;
    uma_tensor_state_role(&spec.name)?;
    uma_tensor_semantic_group(&spec.name)?;
    expect_str(
        &format!("tensor {} layout", spec.name),
        &spec.layout,
        "row-major",
    )?;
    if spec.name.trim().is_empty() {
        return Err(invalid_manifest("tensor name must not be empty"));
    }
    if spec.shape.contains(&0) {
        return Err(invalid_manifest(format!(
            "tensor {} shape dimensions must be nonzero, got {:?}",
            spec.name, spec.shape
        )));
    }
    validate_relative_path(&format!("tensor {} path", spec.name), &spec.path)?;
    product(&spec.shape)?;
    Ok(())
}

fn uma_tensor_state_role(name: &str) -> Result<&'static str, ModelError> {
    if name.starts_with(UMA_INFERENCE_STATE_PREFIX) {
        Ok("ema")
    } else if name == UMA_EMA_METADATA_TENSOR {
        Ok("ema_metadata")
    } else if name.starts_with(UMA_RAW_STATE_PREFIX) {
        Ok("raw")
    } else {
        Err(invalid_manifest(format!(
            "UMA tensor {name} must be under {UMA_INFERENCE_STATE_PREFIX:?}, {UMA_RAW_STATE_PREFIX:?}, or be {UMA_EMA_METADATA_TENSOR:?}"
        )))
    }
}

fn uma_tensor_inference_key(name: &str) -> Option<&str> {
    name.strip_prefix(UMA_INFERENCE_STATE_PREFIX)
}

fn uma_tensor_semantic_group(name: &str) -> Result<String, ModelError> {
    let key = uma_tensor_inference_key(name)
        .or_else(|| name.strip_prefix(UMA_RAW_STATE_PREFIX))
        .or_else(|| (name == UMA_EMA_METADATA_TENSOR).then_some(""));
    let Some(key) = key else {
        return Err(invalid_manifest(format!(
            "UMA tensor {name} has no semantic group"
        )));
    };
    if name == UMA_EMA_METADATA_TENSOR {
        return Ok("swa_metadata".to_owned());
    }
    if let Some(rest) = key.strip_prefix("backbone.blocks.") {
        let block = rest
            .split('.')
            .next()
            .ok_or_else(|| invalid_manifest(format!("UMA tensor {name} missing block index")))?;
        let block_index = block.parse::<usize>().map_err(|_| {
            invalid_manifest(format!(
                "UMA tensor {name} has non-numeric backbone block index"
            ))
        })?;
        if block_index >= 4 {
            return Err(invalid_manifest(format!(
                "UMA tensor {name} block index must be in 0..4"
            )));
        }
        return Ok(format!("backbone_block_{block_index}"));
    }
    if key.starts_with("backbone.edge_degree_embedding.") {
        return Ok("edge_degree_embedding".to_owned());
    }
    if key.starts_with("backbone.dataset_embedding.") {
        return Ok("dataset_embedding".to_owned());
    }
    if key.starts_with("backbone.routing_mlp.") {
        return Ok("routing_mlp".to_owned());
    }
    if key.starts_with("output_heads.energyandforcehead.") {
        return Ok("energy_force_head".to_owned());
    }
    if key.starts_with("backbone.") {
        return Ok("backbone_global".to_owned());
    }
    Err(invalid_manifest(format!(
        "UMA tensor {name} has unsupported semantic group"
    )))
}

fn validate_uma_species_coverage(symbols: &[String]) -> Result<(), ModelError> {
    for symbol in symbols {
        if !ESEN_OAM_ELEMENT_SYMBOLS
            .iter()
            .any(|candidate| *candidate == symbol)
        {
            return Err(invalid_manifest(format!(
                "UMA-S-1.2 supports element symbols H through Pu; got {symbol:?}"
            )));
        }
    }
    Ok(())
}

fn parse_esen_shape(value: &serde_json::Value, field: &str) -> Result<Vec<usize>, ModelError> {
    let dims = value
        .as_array()
        .ok_or_else(|| invalid_manifest(format!("eSEN-OAM state JSON {field} must be an array")))?;
    let mut shape = Vec::with_capacity(dims.len());
    for dim in dims {
        let dim = dim.as_u64().ok_or_else(|| {
            invalid_manifest(format!(
                "eSEN-OAM state JSON {field} must contain unsigned integers"
            ))
        })?;
        let dim = usize::try_from(dim).map_err(|_| {
            invalid_manifest(format!(
                "eSEN-OAM state JSON {field} dimension overflows usize"
            ))
        })?;
        if dim == 0 {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON {field} dimensions must be nonzero"
            )));
        }
        shape.push(dim);
    }
    Ok(shape)
}

fn validate_esen_oam_state_tensors(
    state: &serde_json::Value,
    specs: &[TensorSpec],
) -> Result<(), ModelError> {
    let tensors = esen_json_path(state, &["tensors"])?
        .as_array()
        .ok_or_else(|| invalid_manifest("eSEN-OAM state JSON tensors must be an array"))?;
    if tensors.len() != specs.len() {
        return Err(invalid_manifest(format!(
            "eSEN-OAM state JSON tensors length must be {}, got {}",
            specs.len(),
            tensors.len()
        )));
    }

    let mut by_name = HashMap::new();
    for tensor in tensors {
        let name = tensor
            .get("name")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest("eSEN-OAM state JSON tensor entry missing string name")
            })?;
        if by_name.insert(name, tensor).is_some() {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON contains duplicate tensor {name}"
            )));
        }
    }

    for spec in specs {
        let tensor = by_name.get(spec.name.as_str()).ok_or_else(|| {
            invalid_manifest(format!("eSEN-OAM state JSON missing tensor {}", spec.name))
        })?;
        let expected_file = path_to_slash_string(&spec.path);
        let actual_file = tensor
            .get("file")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "eSEN-OAM state JSON tensor {} missing string file",
                    spec.name
                ))
            })?;
        if actual_file != expected_file {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON tensor {} file must be {expected_file:?}, got {actual_file:?}",
                spec.name
            )));
        }
        let actual_dtype = tensor
            .get("exported_dtype")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "eSEN-OAM state JSON tensor {} missing string exported_dtype",
                    spec.name
                ))
            })?;
        if actual_dtype != spec.dtype {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON tensor {} exported_dtype must be {:?}, got {:?}",
                spec.name, spec.dtype, actual_dtype
            )));
        }
        let shape_value = tensor.get("shape").ok_or_else(|| {
            invalid_manifest(format!(
                "eSEN-OAM state JSON tensor {} missing shape",
                spec.name
            ))
        })?;
        let actual_shape = parse_esen_shape(shape_value, &format!("tensor {} shape", spec.name))?;
        if actual_shape != spec.shape {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON tensor {} shape must be {:?}, got {:?}",
                spec.name, spec.shape, actual_shape
            )));
        }
        let expected_numel = product(&spec.shape)?;
        let actual_numel = tensor
            .get("numel")
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "eSEN-OAM state JSON tensor {} missing unsigned numel",
                    spec.name
                ))
            })?;
        if actual_numel
            != u64::try_from(expected_numel).map_err(|_| {
                invalid_manifest(format!("eSEN-OAM tensor {} numel overflows u64", spec.name))
            })?
        {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON tensor {} numel mismatch",
                spec.name
            )));
        }
        let expected_bytes = expected_numel
            .checked_mul(esen_oam_tensor_dtype_size(&spec.dtype)?)
            .ok_or_else(|| {
                invalid_manifest(format!("eSEN-OAM tensor {} byte size overflows", spec.name))
            })?;
        let actual_bytes = tensor
            .get("bytes")
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "eSEN-OAM state JSON tensor {} missing unsigned bytes",
                    spec.name
                ))
            })?;
        if actual_bytes
            != u64::try_from(expected_bytes).map_err(|_| {
                invalid_manifest(format!("eSEN-OAM tensor {} bytes overflows u64", spec.name))
            })?
        {
            return Err(invalid_manifest(format!(
                "eSEN-OAM state JSON tensor {} bytes mismatch",
                spec.name
            )));
        }
        if let Some(expected_sha256) = &spec.sha256 {
            let actual_sha256 = tensor
                .get("sha256")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| {
                    invalid_manifest(format!(
                        "eSEN-OAM state JSON tensor {} missing string sha256",
                        spec.name
                    ))
                })?;
            if actual_sha256 != expected_sha256 {
                return Err(invalid_manifest(format!(
                    "eSEN-OAM state JSON tensor {} sha256 mismatch",
                    spec.name
                )));
            }
        }
    }

    Ok(())
}

fn parse_uma_shape(value: &serde_json::Value, field: &str) -> Result<Vec<usize>, ModelError> {
    let dims = value
        .as_array()
        .ok_or_else(|| invalid_manifest(format!("UMA state JSON {field} must be an array")))?;
    let mut shape = Vec::with_capacity(dims.len());
    for dim in dims {
        let dim = dim.as_u64().ok_or_else(|| {
            invalid_manifest(format!(
                "UMA state JSON {field} must contain unsigned integers"
            ))
        })?;
        let dim = usize::try_from(dim).map_err(|_| {
            invalid_manifest(format!("UMA state JSON {field} dimension overflows usize"))
        })?;
        if dim == 0 {
            return Err(invalid_manifest(format!(
                "UMA state JSON {field} dimensions must be nonzero"
            )));
        }
        shape.push(dim);
    }
    Ok(shape)
}

fn validate_uma_state_tensors(
    state: &serde_json::Value,
    specs: &[TensorSpec],
) -> Result<(), ModelError> {
    let tensors = uma_json_path(state, &["tensors"])?
        .as_array()
        .ok_or_else(|| invalid_manifest("UMA state JSON tensors must be an array"))?;
    if tensors.len() != specs.len() {
        return Err(invalid_manifest(format!(
            "UMA state JSON tensors length must be {}, got {}",
            specs.len(),
            tensors.len()
        )));
    }

    let mut by_name = HashMap::new();
    for tensor in tensors {
        let name = tensor
            .get("name")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| invalid_manifest("UMA state JSON tensor entry missing string name"))?;
        if by_name.insert(name, tensor).is_some() {
            return Err(invalid_manifest(format!(
                "UMA state JSON contains duplicate tensor {name}"
            )));
        }
    }

    for spec in specs {
        let tensor = by_name.get(spec.name.as_str()).ok_or_else(|| {
            invalid_manifest(format!("UMA state JSON missing tensor {}", spec.name))
        })?;
        let expected_file = path_to_slash_string(&spec.path);
        let actual_file = tensor
            .get("file")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing string file",
                    spec.name
                ))
            })?;
        if actual_file != expected_file {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} file must be {expected_file:?}, got {actual_file:?}",
                spec.name
            )));
        }
        let actual_dtype = tensor
            .get("exported_dtype")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing string exported_dtype",
                    spec.name
                ))
            })?;
        if actual_dtype != spec.dtype {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} exported_dtype must be {:?}, got {:?}",
                spec.name, spec.dtype, actual_dtype
            )));
        }
        let shape_value = tensor.get("shape").ok_or_else(|| {
            invalid_manifest(format!("UMA state JSON tensor {} missing shape", spec.name))
        })?;
        let actual_shape = parse_uma_shape(shape_value, &format!("tensor {} shape", spec.name))?;
        if actual_shape != spec.shape {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} shape must be {:?}, got {:?}",
                spec.name, spec.shape, actual_shape
            )));
        }
        let expected_numel = product(&spec.shape)?;
        let actual_numel = tensor
            .get("numel")
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing unsigned numel",
                    spec.name
                ))
            })?;
        if actual_numel
            != u64::try_from(expected_numel).map_err(|_| {
                invalid_manifest(format!("UMA tensor {} numel overflows u64", spec.name))
            })?
        {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} numel mismatch",
                spec.name
            )));
        }
        let expected_bytes = expected_numel
            .checked_mul(uma_tensor_dtype_size(&spec.dtype)?)
            .ok_or_else(|| {
                invalid_manifest(format!("UMA tensor {} byte size overflows", spec.name))
            })?;
        let actual_bytes = tensor
            .get("bytes")
            .and_then(serde_json::Value::as_u64)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing unsigned bytes",
                    spec.name
                ))
            })?;
        if actual_bytes
            != u64::try_from(expected_bytes).map_err(|_| {
                invalid_manifest(format!("UMA tensor {} bytes overflows u64", spec.name))
            })?
        {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} bytes mismatch",
                spec.name
            )));
        }
        if let Some(expected_sha256) = &spec.sha256 {
            let actual_sha256 = tensor
                .get("sha256")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| {
                    invalid_manifest(format!(
                        "UMA state JSON tensor {} missing string sha256",
                        spec.name
                    ))
                })?;
            if actual_sha256 != expected_sha256 {
                return Err(invalid_manifest(format!(
                    "UMA state JSON tensor {} sha256 mismatch",
                    spec.name
                )));
            }
        }
        let expected_state_role = uma_tensor_state_role(&spec.name)?;
        let actual_state_role = tensor
            .get("state_role")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing string state_role",
                    spec.name
                ))
            })?;
        if actual_state_role != expected_state_role {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} state_role must be {:?}, got {:?}",
                spec.name, expected_state_role, actual_state_role
            )));
        }
        let expected_semantic_group = uma_tensor_semantic_group(&spec.name)?;
        let actual_semantic_group = tensor
            .get("semantic_group")
            .and_then(serde_json::Value::as_str)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing string semantic_group",
                    spec.name
                ))
            })?;
        if actual_semantic_group != expected_semantic_group {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} semantic_group must be {:?}, got {:?}",
                spec.name, expected_semantic_group, actual_semantic_group
            )));
        }
        let expected_inference_key = uma_tensor_inference_key(&spec.name);
        let actual_active = tensor
            .get("active_for_inference")
            .and_then(serde_json::Value::as_bool)
            .ok_or_else(|| {
                invalid_manifest(format!(
                    "UMA state JSON tensor {} missing boolean active_for_inference",
                    spec.name
                ))
            })?;
        if actual_active != expected_inference_key.is_some() {
            return Err(invalid_manifest(format!(
                "UMA state JSON tensor {} active_for_inference mismatch",
                spec.name
            )));
        }
        let actual_inference_key = tensor.get("inference_key").ok_or_else(|| {
            invalid_manifest(format!(
                "UMA state JSON tensor {} missing inference_key",
                spec.name
            ))
        })?;
        match expected_inference_key {
            Some(expected) => {
                let actual = actual_inference_key.as_str().ok_or_else(|| {
                    invalid_manifest(format!(
                        "UMA state JSON tensor {} inference_key must be a string",
                        spec.name
                    ))
                })?;
                if actual != expected {
                    return Err(invalid_manifest(format!(
                        "UMA state JSON tensor {} inference_key must be {:?}, got {:?}",
                        spec.name, expected, actual
                    )));
                }
            }
            None => {
                if !actual_inference_key.is_null() {
                    return Err(invalid_manifest(format!(
                        "UMA state JSON tensor {} inference_key must be null",
                        spec.name
                    )));
                }
            }
        }
    }

    validate_uma_inference_summary(state, specs)?;

    Ok(())
}

fn validate_uma_inference_summary(
    state: &serde_json::Value,
    specs: &[TensorSpec],
) -> Result<(), ModelError> {
    expect_uma_json_str(
        state,
        &["inference_state", "source"],
        UMA_INFERENCE_STATE_SOURCE,
    )?;
    expect_uma_json_str(
        state,
        &["inference_state", "checkpoint_loader"],
        UMA_INFERENCE_CHECKPOINT_LOADER,
    )?;

    let mut active_count = 0u64;
    let mut active_numel = 0u64;
    let mut active_bytes = 0u64;
    let mut group_counts = BTreeMap::<String, u64>::new();
    let mut group_numel = BTreeMap::<String, u64>::new();
    for spec in specs {
        if uma_tensor_inference_key(&spec.name).is_none() {
            continue;
        }
        let numel = u64::try_from(product(&spec.shape)?)
            .map_err(|_| invalid_manifest(format!("UMA tensor {} numel overflows", spec.name)))?;
        let bytes = numel
            .checked_mul(
                u64::try_from(uma_tensor_dtype_size(&spec.dtype)?).map_err(|_| {
                    invalid_manifest(format!("UMA tensor {} dtype size overflows", spec.name))
                })?,
            )
            .ok_or_else(|| invalid_manifest(format!("UMA tensor {} bytes overflow", spec.name)))?;
        let group = uma_tensor_semantic_group(&spec.name)?;
        active_count += 1;
        active_numel = active_numel
            .checked_add(numel)
            .ok_or_else(|| invalid_manifest("UMA active tensor numel overflows"))?;
        active_bytes = active_bytes
            .checked_add(bytes)
            .ok_or_else(|| invalid_manifest("UMA active tensor bytes overflow"))?;
        *group_counts.entry(group.clone()).or_default() += 1;
        *group_numel.entry(group).or_default() += numel;
    }

    expect_uma_json_u64(
        state,
        &["inference_state", "active_tensor_count"],
        active_count,
    )?;
    expect_uma_json_u64(
        state,
        &["inference_state", "active_total_numel"],
        active_numel,
    )?;
    expect_uma_json_u64(
        state,
        &["inference_state", "active_total_bytes"],
        active_bytes,
    )?;
    expect_uma_json_u64(
        state,
        &["tensor_summary", "active_inference_count"],
        active_count,
    )?;
    expect_uma_json_u64(
        state,
        &["tensor_summary", "active_inference_numel"],
        active_numel,
    )?;
    expect_uma_json_u64(
        state,
        &["tensor_summary", "active_inference_bytes"],
        active_bytes,
    )?;
    expect_uma_json_u64_map(
        state,
        &["tensor_summary", "active_semantic_group_counts"],
        &group_counts,
    )?;
    expect_uma_json_u64_map(
        state,
        &["tensor_summary", "active_semantic_group_numel"],
        &group_numel,
    )?;
    Ok(())
}

fn validate_uma_runtime_tensor_contract(specs: &[TensorSpec]) -> Result<bool, ModelError> {
    let by_name = specs
        .iter()
        .map(|spec| (spec.name.as_str(), spec))
        .collect::<HashMap<_, _>>();
    let has_runtime_anchor = by_name.contains_key(UMA_TENSOR_CHARGE_EMBEDDING)
        || by_name.contains_key(UMA_TENSOR_SPHERE_EMBEDDING)
        || by_name.contains_key("ema_state_dict.module.backbone.blocks.0.norm_1.affine_weight");
    if !has_runtime_anchor {
        if specs.len() == UMA_S_1P2_RUNTIME_TENSOR_COUNT {
            return Err(invalid_manifest(
                "UMA-S-1.2 export has the pinned tensor count but no recognized runtime tensors",
            ));
        }
        return Ok(false);
    }
    for (name, shape) in UMA_REQUIRED_RUNTIME_TENSORS {
        expect_uma_contract_tensor(&by_name, name, shape)?;
    }
    for block_index in 0..UMA_BLOCK_COUNT {
        validate_uma_block_tensor_contract(&by_name, block_index)?;
    }
    Ok(true)
}

fn validate_uma_block_tensor_contract(
    by_name: &HashMap<&str, &TensorSpec>,
    block_index: usize,
) -> Result<(), ModelError> {
    let prefix = format!("ema_state_dict.module.backbone.blocks.{block_index}");
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.norm_1.affine_weight"),
        &[UMA_L_MAX + 1, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.norm_1.affine_bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.norm_2.affine_weight"),
        &[UMA_L_MAX + 1, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.norm_2.affine_bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_1.fc_m0.weights"),
        &[UMA_ROUTING_EXPERTS, 640, 768],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_1.fc_m0.bias"),
        &[640],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_1.so2_m_conv.0.fc.weights"),
        &[UMA_ROUTING_EXPERTS, 512, 512],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_1.so2_m_conv.1.fc.weights"),
        &[UMA_ROUTING_EXPERTS, 256, 256],
    )?;
    validate_uma_block_conv1_radial_contract(by_name, &prefix)?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_2.fc_m0.weights"),
        &[UMA_ROUTING_EXPERTS, 384, 384],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_2.fc_m0.bias"),
        &[384],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_2.so2_m_conv.0.fc.weights"),
        &[UMA_ROUTING_EXPERTS, 512, 256],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.edge_wise.so2_conv_2.so2_m_conv.1.fc.weights"),
        &[UMA_ROUTING_EXPERTS, 256, 128],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.atom_wise.scalar_mlp.0.weight"),
        &[256, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.atom_wise.scalar_mlp.0.bias"),
        &[256],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.atom_wise.so3_linear_1.weight"),
        &[UMA_L_MAX + 1, UMA_SPHERE_CHANNELS, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.atom_wise.so3_linear_1.bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.atom_wise.so3_linear_2.weight"),
        &[UMA_L_MAX + 1, UMA_SPHERE_CHANNELS, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.atom_wise.so3_linear_2.bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    Ok(())
}

fn validate_uma_block_conv1_radial_contract(
    by_name: &HashMap<&str, &TensorSpec>,
    block_prefix: &str,
) -> Result<(), ModelError> {
    let prefix = format!("{block_prefix}.edge_wise.so2_conv_1.rad_func");
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.0.weight"),
        &[UMA_SPHERE_CHANNELS, UMA_EDGE_DEGREE_RADIAL_INPUT_DIM],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.0.bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.1.weight"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.1.bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.3.weight"),
        &[UMA_SPHERE_CHANNELS, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.3.bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.4.weight"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.4.bias"),
        &[UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.6.weight"),
        &[UMA_BLOCK_CONV1_RADIAL_OUTPUT_DIM, UMA_SPHERE_CHANNELS],
    )?;
    expect_uma_contract_tensor(
        by_name,
        &format!("{prefix}.net.6.bias"),
        &[UMA_BLOCK_CONV1_RADIAL_OUTPUT_DIM],
    )?;
    Ok(())
}

fn expect_uma_contract_tensor(
    by_name: &HashMap<&str, &TensorSpec>,
    name: &str,
    shape: &[usize],
) -> Result<(), ModelError> {
    let spec = by_name
        .get(name)
        .ok_or_else(|| invalid_manifest(format!("UMA runtime tensor contract missing {name}")))?;
    if spec.dtype != DTYPE_F64 {
        return Err(invalid_manifest(format!(
            "UMA runtime tensor {name} dtype must be {DTYPE_F64:?}, got {:?}",
            spec.dtype
        )));
    }
    if spec.shape != shape {
        return Err(invalid_manifest(format!(
            "UMA runtime tensor {name} shape must be {:?}, got {:?}",
            shape, spec.shape
        )));
    }
    if spec.sha256.is_none() {
        return Err(invalid_manifest(format!(
            "UMA runtime tensor {name} must carry a pinned sha256"
        )));
    }
    Ok(())
}

