fn uma_required_runtime_tensor_shape(name: &str) -> Option<&'static [usize]> {
    UMA_REQUIRED_RUNTIME_TENSORS
        .iter()
        .find_map(|(candidate, shape)| (*candidate == name).then_some(*shape))
}

