fn reject_nequix_section_for_architecture(manifest: &Manifest) -> Result<(), ModelError> {
    if manifest.nequix.is_some() {
        return Err(invalid_manifest(format!(
            "architecture {} must not contain [nequix] section",
            manifest.architecture
        )));
    }
    Ok(())
}

fn validate_esen_oam_manifest(esen: &EsenOamSection) -> Result<(), ModelError> {
    validate_relative_path("esen_oam.state", &esen.state)?;
    expect_str(
        "esen_oam.reference_package",
        &esen.reference_package,
        "fairchem",
    )?;
    expect_str(
        "esen_oam.reference_version",
        &esen.reference_version,
        "1.10.0",
    )?;
    expect_str(
        "esen_oam.reference_commit",
        &esen.reference_commit,
        ESEN_OAM_FAIRCHEM_REFERENCE_COMMIT,
    )?;
    expect_str(
        "esen_oam.selected_model",
        &esen.selected_model,
        "esen-30m-oam",
    )?;
    expect_str(
        "esen_oam.state_schema",
        &esen.state_schema,
        "esen-oam-state-dict-v1",
    )?;
    if esen.artifact_sha256.len() != SHA256_HEX_LEN
        || !esen
            .artifact_sha256
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit())
    {
        return Err(invalid_manifest(
            "esen_oam.artifact_sha256 must be a SHA256 hex digest",
        ));
    }
    expect_str(
        "esen_oam.artifact_sha256",
        &esen.artifact_sha256,
        ESEN_30M_OAM_ARTIFACT_SHA256,
    )?;
    if esen.artifact_size_bytes != ESEN_30M_OAM_ARTIFACT_SIZE_BYTES {
        return Err(invalid_manifest(
            "esen_oam.artifact_size_bytes must match pinned eSEN-30M-OAM artifact size",
        ));
    }
    Ok(())
}

