fn validate_tensor_spec(spec: &TensorSpec) -> Result<(), ModelError> {
    tensor_dtype_size(&spec.dtype).map_err(|_| {
        invalid_manifest(format!(
            "tensor {} dtype must be {:?} or {:?}, got {:?}",
            spec.name, DTYPE_F64, DTYPE_F32, spec.dtype
        ))
    })?;
    expect_str(
        &format!("tensor {} layout", spec.name),
        &spec.layout,
        "row-major",
    )?;
    if spec.name.trim().is_empty() {
        return Err(invalid_manifest("tensor name must not be empty"));
    }
    if spec.shape.contains(&0) {
        return Err(invalid_manifest(format!(
            "tensor {} shape dimensions must be nonzero, got {:?}",
            spec.name, spec.shape
        )));
    }
    validate_relative_path(&format!("tensor {} path", spec.name), &spec.path)?;
    product(&spec.shape)?;
    Ok(())
}

