    #[cfg(all(
        feature = "parallel",
        target_arch = "aarch64",
        target_os = "linux",
        llmlip_aarch64_sve_kernels
    ))]
    #[test]
    fn uma_so2_order_gather_parallel_sve_wrappers_match_scalar_reference(
    ) -> Result<(), rayon::ThreadPoolBuildError> {
        if !std::arch::is_aarch64_feature_detected!("sve") {
            return Ok(());
        }

        let nodes = 1031usize;
        let conv1_in_channels = 17usize;
        let input_node_stride = 9 * conv1_in_channels;
        let radial_node_stride = 6 * conv1_in_channels;
        let radial_offset1 = 3 * conv1_in_channels;
        let radial_offset2 = radial_offset1 + 2 * conv1_in_channels;
        let input_len = nodes * input_node_stride;
        let radial_len = nodes * radial_node_stride;
        let input = (0..input_len)
            .map(|i| (i as f32 * 0.013 + 0.19).sin() * 0.45)
            .collect::<Vec<_>>();
        let radial = (0..radial_len)
            .map(|i| (i as f32 * 0.017 + 0.31).cos() * 0.20 + 0.80)
            .collect::<Vec<_>>();

        let mut expected_order1 = vec![0.0_f32; nodes * 4 * conv1_in_channels];
        for node in 0..nodes {
            let in_base = node * input_node_stride;
            let rad_base = node * radial_node_stride + radial_offset1;
            let dst = node * 4 * conv1_in_channels;
            for ch in 0..conv1_in_channels {
                let radial0 = radial[rad_base + ch];
                let radial1 = radial[rad_base + conv1_in_channels + ch];
                expected_order1[dst + ch] = input[in_base + 3 * conv1_in_channels + ch] * radial0;
                expected_order1[dst + conv1_in_channels + ch] =
                    input[in_base + 7 * conv1_in_channels + ch] * radial1;
                expected_order1[dst + 2 * conv1_in_channels + ch] =
                    input[in_base + conv1_in_channels + ch] * radial0;
                expected_order1[dst + 3 * conv1_in_channels + ch] =
                    input[in_base + 5 * conv1_in_channels + ch] * radial1;
            }
        }

        let mut expected_order2 = vec![0.0_f32; nodes * 2 * conv1_in_channels];
        for node in 0..nodes {
            let in_base = node * input_node_stride;
            let rad_base = node * radial_node_stride + radial_offset2;
            let dst = node * 2 * conv1_in_channels;
            for ch in 0..conv1_in_channels {
                let radial0 = radial[rad_base + ch];
                expected_order2[dst + ch] = input[in_base + 8 * conv1_in_channels + ch] * radial0;
                expected_order2[dst + conv1_in_channels + ch] =
                    input[in_base + 4 * conv1_in_channels + ch] * radial0;
            }
        }

        let pool = rayon::ThreadPoolBuilder::new().num_threads(4).build()?;
        pool.install(|| {
            let mut actual_order1 = vec![f32::NAN; expected_order1.len()];
            assert!(uma_so2_order1_gather_parallel_sve_f32(
                nodes,
                conv1_in_channels,
                input_node_stride,
                radial_node_stride,
                radial_offset1,
                &input,
                &radial,
                &mut actual_order1,
            ));
            for (index, (&actual, &expected)) in
                actual_order1.iter().zip(expected_order1.iter()).enumerate()
            {
                let abs = (actual - expected).abs();
                assert!(
                    abs <= 2.0e-6,
                    "order1_parallel_gather[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                );
            }

            let mut actual_order2 = vec![f32::NAN; expected_order2.len()];
            assert!(uma_so2_order2_gather_parallel_sve_f32(
                nodes,
                conv1_in_channels,
                input_node_stride,
                radial_node_stride,
                radial_offset2,
                &input,
                &radial,
                &mut actual_order2,
            ));
            for (index, (&actual, &expected)) in
                actual_order2.iter().zip(expected_order2.iter()).enumerate()
            {
                let abs = (actual - expected).abs();
                assert!(
                    abs <= 2.0e-6,
                    "order2_parallel_gather[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                );
            }
        });
        Ok(())
    }

