    #[test]
    fn uma_so2_m0_gate_parallel_sve_wrapper_matches_scalar_reference(
    ) -> Result<(), rayon::ThreadPoolBuildError> {
        if !std::arch::is_aarch64_feature_detected!("sve") {
            return Ok(());
        }

        let nodes = 1031usize;
        let channels = 13usize;
        let m0_out_dim = 5 * channels + 2;
        let conv1_out_node_stride = 9 * channels + 5;
        let gate_node_stride = 2 * channels + 3;
        let conv2_m0_in_node_stride = 3 * channels + 4;

        let dense_len = nodes * m0_out_dim;
        let conv1_len = nodes * conv1_out_node_stride;
        let gate_len = nodes * gate_node_stride;
        let deriv_len = nodes * channels;
        let conv2_len = nodes * conv2_m0_in_node_stride;
        let conv1_m0_dense_out = (0..dense_len)
            .map(|i| (i as f32 * 0.019 + 0.11).sin() * 0.35)
            .collect::<Vec<_>>();

        let mut expected_conv1 = vec![-99.0_f32; conv1_len];
        let mut expected_gates = vec![-99.0_f32; gate_len];
        let mut expected_derivatives = vec![-99.0_f32; deriv_len];
        let mut expected_conv2 = vec![-99.0_f32; conv2_len];
        for node in 0..nodes {
            let dense_base = node * m0_out_dim;
            let conv1_base = node * conv1_out_node_stride;
            let gate_base = node * gate_node_stride;
            let deriv_base = node * channels;
            let conv2_base = node * conv2_m0_in_node_stride;
            for ch in 0..channels {
                let gate1 = uma_so2_gate_sigmoid_f32(conv1_m0_dense_out[dense_base + ch]);
                expected_gates[gate_base + ch] = gate1;

                let gate2 =
                    uma_so2_gate_sigmoid_f32(conv1_m0_dense_out[dense_base + channels + ch]);
                expected_gates[gate_base + channels + ch] = gate2;

                let scalar = conv1_m0_dense_out[dense_base + 2 * channels + ch];
                expected_conv1[conv1_base + ch] = scalar;
                let (silu, derivative) = uma_so2_silu_f32(scalar);
                expected_conv2[conv2_base + ch] = silu;
                expected_derivatives[deriv_base + ch] = derivative;

                let l1 = conv1_m0_dense_out[dense_base + 3 * channels + ch];
                expected_conv1[conv1_base + channels + ch] = l1;
                expected_conv2[conv2_base + channels + ch] = l1 * gate1;

                let l2 = conv1_m0_dense_out[dense_base + 4 * channels + ch];
                expected_conv1[conv1_base + 2 * channels + ch] = l2;
                expected_conv2[conv2_base + 2 * channels + ch] = l2 * gate2;
            }
        }

        let pool = rayon::ThreadPoolBuilder::new().num_threads(4).build()?;
        pool.install(|| {
            let mut actual_conv1 = vec![-99.0_f32; conv1_len];
            let mut actual_gates = vec![-99.0_f32; gate_len];
            let mut actual_derivatives = vec![-99.0_f32; deriv_len];
            let mut actual_conv2 = vec![-99.0_f32; conv2_len];
            assert!(uma_so2_m0_gate_scatter_fill_parallel_sve_f32(
                nodes,
                channels,
                m0_out_dim,
                conv1_out_node_stride,
                gate_node_stride,
                conv2_m0_in_node_stride,
                &conv1_m0_dense_out,
                &mut actual_conv1,
                &mut actual_gates,
                &mut actual_derivatives,
                &mut actual_conv2,
            ));

            for (name, actual, expected) in [
                ("conv1", &actual_conv1, &expected_conv1),
                ("gates", &actual_gates, &expected_gates),
                ("derivatives", &actual_derivatives, &expected_derivatives),
                ("conv2", &actual_conv2, &expected_conv2),
            ] {
                for (index, (&actual, &expected)) in actual.iter().zip(expected.iter()).enumerate()
                {
                    let abs = (actual - expected).abs();
                    assert!(
                        abs <= 5.0e-4,
                        "m0_gate_parallel_{name}[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                    );
                }
            }
        });
        Ok(())
    }

