    #[test]
    fn uma_so2_m0_gate_vjp_parallel_sve_wrapper_matches_scalar_reference(
    ) -> Result<(), rayon::ThreadPoolBuildError> {
        if !std::arch::is_aarch64_feature_detected!("sve") {
            return Ok(());
        }

        let nodes = UMA_M0_GATE_VJP_PARALLEL_MIN_NODES + 29;
        let channels = 17usize;
        let m0_out_dim = 5 * channels + 3;
        let out_node_stride = 9 * channels + 5;
        let gate_node_stride = 2 * channels + 3;
        let act_len = nodes * 3 * channels;
        let conv1_len = nodes * out_node_stride;
        let gate_len = nodes * gate_node_stride;
        let deriv_len = nodes * channels;
        let grad_len = nodes * m0_out_dim;

        let activated = (0..act_len)
            .map(|i| (i as f32 * 0.017 + 0.19).sin() * 0.25)
            .collect::<Vec<_>>();
        let conv1_out = (0..conv1_len)
            .map(|i| (i as f32 * 0.023 + 0.31).cos() * 0.30)
            .collect::<Vec<_>>();
        let gates = (0..gate_len)
            .map(|i| (i as f32 * 0.011 + 0.13).sin() * 0.20 + 0.55)
            .collect::<Vec<_>>();
        let derivatives = (0..deriv_len)
            .map(|i| (i as f32 * 0.029 + 0.07).cos() * 0.40)
            .collect::<Vec<_>>();
        let base_grad = (0..grad_len)
            .map(|i| (i as f32 * 0.007 + 0.17).sin() * 0.01)
            .collect::<Vec<_>>();

        let mut expected = base_grad.clone();
        for node in 0..nodes {
            let act_base = node * 3 * channels;
            let conv1_base = node * out_node_stride;
            let gate_base = node * gate_node_stride;
            let deriv_base = node * channels;
            let grad_base = node * m0_out_dim;
            for ch in 0..channels {
                let grad_scalar = activated[act_base + ch];
                let grad_l1 = activated[act_base + channels + ch];
                let grad_l2 = activated[act_base + 2 * channels + ch];
                let gate1 = gates[gate_base + ch];
                let gate2 = gates[gate_base + channels + ch];
                let conv1_l1 = conv1_out[conv1_base + channels + ch];
                let conv1_l2 = conv1_out[conv1_base + 2 * channels + ch];
                let scalar_deriv = derivatives[deriv_base + ch];

                expected[grad_base + ch] += grad_l1 * conv1_l1;
                expected[grad_base + channels + ch] += grad_l2 * conv1_l2;
                expected[grad_base + 2 * channels + ch] += grad_scalar * scalar_deriv;
                expected[grad_base + 3 * channels + ch] += grad_l1 * gate1;
                expected[grad_base + 4 * channels + ch] += grad_l2 * gate2;
            }
        }

        let pool = rayon::ThreadPoolBuilder::new().num_threads(4).build()?;
        pool.install(|| {
            let mut actual = base_grad;
            assert!(uma_so2_m0_gate_vjp_parallel_sve_f32(
                nodes,
                channels,
                m0_out_dim,
                out_node_stride,
                gate_node_stride,
                &activated,
                &conv1_out,
                &gates,
                &derivatives,
                &mut actual,
            ));

            for (index, (&actual, &expected)) in actual.iter().zip(expected.iter()).enumerate() {
                let abs = (actual - expected).abs();
                assert!(
                    abs <= 5.0e-6,
                    "m0_gate_vjp_parallel[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                );
            }
        });
        Ok(())
    }

