    #[test]
    fn uma_so2_order_gate_vjp_parallel_sve_wrappers_match_scalar_reference(
    ) -> Result<(), rayon::ThreadPoolBuildError> {
        if !std::arch::is_aarch64_feature_detected!("sve") {
            return Ok(());
        }

        let nodes = UMA_ORDER_GATE_VJP_PARALLEL_MIN_NODES + 29;
        let channels = 17usize;
        let out_node_stride = 9 * channels + 5;
        let gate_node_stride = 2 * channels + 3;
        let m0_out_dim = 2 * channels + 3;
        let conv1_len = nodes * out_node_stride;
        let gate_len = nodes * gate_node_stride;
        let m0_len = nodes * m0_out_dim;
        let conv1_out = (0..conv1_len)
            .map(|i| (i as f32 * 0.019 + 0.23).sin() * 0.30)
            .collect::<Vec<_>>();
        let gate_sigmoids = (0..gate_len)
            .map(|i| (i as f32 * 0.013 + 0.11).cos() * 0.20 + 0.55)
            .collect::<Vec<_>>();
        let base_m0 = (0..m0_len)
            .map(|i| (i as f32 * 0.007 + 0.17).sin() * 0.01)
            .collect::<Vec<_>>();

        let order1_block_width = 4 * channels;
        let order1_act = (0..nodes * order1_block_width)
            .map(|i| (i as f32 * 0.017 + 0.31).sin() * 0.25)
            .collect::<Vec<_>>();
        let mut expected_order1_blk = vec![f32::NAN; order1_act.len()];
        let mut expected_order1_m0 = base_m0.clone();
        for node in 0..nodes {
            let blk = node * order1_block_width;
            let conv1_base = node * out_node_stride + 3 * channels;
            let gate_base = node * gate_node_stride;
            let m0_base = node * m0_out_dim;
            for ch in 0..channels {
                let gate1 = gate_sigmoids[gate_base + ch];
                let gate2 = gate_sigmoids[gate_base + channels + ch];
                let grad3 = order1_act[blk + ch];
                let grad7 = order1_act[blk + channels + ch];
                let grad1 = order1_act[blk + 2 * channels + ch];
                let grad5 = order1_act[blk + 3 * channels + ch];
                expected_order1_blk[blk + ch] = grad3 * gate1;
                expected_order1_blk[blk + channels + ch] = grad7 * gate2;
                expected_order1_blk[blk + 2 * channels + ch] = grad1 * gate1;
                expected_order1_blk[blk + 3 * channels + ch] = grad5 * gate2;
                expected_order1_m0[m0_base + ch] += grad3 * conv1_out[conv1_base + ch]
                    + grad1 * conv1_out[conv1_base + 2 * channels + ch];
                expected_order1_m0[m0_base + channels + ch] += grad7
                    * conv1_out[conv1_base + channels + ch]
                    + grad5 * conv1_out[conv1_base + 3 * channels + ch];
            }
        }

        let pool = rayon::ThreadPoolBuilder::new().num_threads(4).build()?;
        pool.install(|| {
            let mut actual_order1_blk = vec![f32::NAN; expected_order1_blk.len()];
            let mut actual_order1_m0 = base_m0.clone();
            assert!(uma_so2_order1_gate_vjp_parallel_sve_f32(
                nodes,
                channels,
                m0_out_dim,
                out_node_stride,
                gate_node_stride,
                &order1_act,
                &conv1_out,
                &gate_sigmoids,
                &mut actual_order1_blk,
                &mut actual_order1_m0,
            ));
            for (label, actual, expected) in [
                (
                    "order1_parallel_gate_conv1_blk",
                    &actual_order1_blk,
                    &expected_order1_blk,
                ),
                (
                    "order1_parallel_gate_m0",
                    &actual_order1_m0,
                    &expected_order1_m0,
                ),
            ] {
                for (index, (&actual, &expected)) in actual.iter().zip(expected.iter()).enumerate()
                {
                    let abs = (actual - expected).abs();
                    assert!(
                        abs <= 5.0e-6,
                        "{label}[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                    );
                }
            }
        });

        let order2_block_width = 2 * channels;
        let order2_act = (0..nodes * order2_block_width)
            .map(|i| (i as f32 * 0.023 + 0.37).cos() * 0.22)
            .collect::<Vec<_>>();
        let mut expected_order2_blk = vec![f32::NAN; order2_act.len()];
        let mut expected_order2_m0 = base_m0.clone();
        for node in 0..nodes {
            let blk = node * order2_block_width;
            let conv1_base = node * out_node_stride + 7 * channels;
            let gate_base = node * gate_node_stride;
            let m0_base = node * m0_out_dim;
            for ch in 0..channels {
                let gate2 = gate_sigmoids[gate_base + channels + ch];
                let grad8 = order2_act[blk + ch];
                let grad4 = order2_act[blk + channels + ch];
                expected_order2_blk[blk + ch] = grad8 * gate2;
                expected_order2_blk[blk + channels + ch] = grad4 * gate2;
                expected_order2_m0[m0_base + channels + ch] += grad8 * conv1_out[conv1_base + ch]
                    + grad4 * conv1_out[conv1_base + channels + ch];
            }
        }

        pool.install(|| {
            let mut actual_order2_blk = vec![f32::NAN; expected_order2_blk.len()];
            let mut actual_order2_m0 = base_m0;
            assert!(uma_so2_order2_gate_vjp_parallel_sve_f32(
                nodes,
                channels,
                m0_out_dim,
                out_node_stride,
                gate_node_stride,
                &order2_act,
                &conv1_out,
                &gate_sigmoids,
                &mut actual_order2_blk,
                &mut actual_order2_m0,
            ));
            for (label, actual, expected) in [
                (
                    "order2_parallel_gate_conv1_blk",
                    &actual_order2_blk,
                    &expected_order2_blk,
                ),
                (
                    "order2_parallel_gate_m0",
                    &actual_order2_m0,
                    &expected_order2_m0,
                ),
            ] {
                for (index, (&actual, &expected)) in actual.iter().zip(expected.iter()).enumerate()
                {
                    let abs = (actual - expected).abs();
                    assert!(
                        abs <= 5.0e-6,
                        "{label}[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                    );
                }
            }
        });
        Ok(())
    }

