    #[test]
    fn uma_so2_radial_vjp_sve_wrappers_match_scalar_reference() {
        if !std::arch::is_aarch64_feature_detected!("sve") {
            return;
        }

        let nodes = 3usize;
        let conv1_in_channels = 13usize;
        let input_node_stride = 9 * conv1_in_channels;
        let radial_node_stride = 6 * conv1_in_channels;
        let input_len = nodes * input_node_stride;
        let radial_len = nodes * radial_node_stride;
        let input = (0..input_len)
            .map(|i| (i as f32 * 0.031 + 0.17).sin() * 0.5)
            .collect::<Vec<_>>();
        let radial = (0..radial_len)
            .map(|i| (i as f32 * 0.047 + 0.23).cos() * 0.25 + 0.75)
            .collect::<Vec<_>>();
        let base_grad_input = (0..input_len)
            .map(|i| (i as f32 * 0.019 + 0.11).sin() * 0.01)
            .collect::<Vec<_>>();
        let base_grad_radial = (0..radial_len)
            .map(|i| (i as f32 * 0.023 + 0.07).cos() * 0.01)
            .collect::<Vec<_>>();

        let close = |actual: &[f32], expected: &[f32], label: &str| {
            for (index, (&actual, &expected)) in actual.iter().zip(expected.iter()).enumerate() {
                let abs = (actual - expected).abs();
                assert!(
                    abs <= 2.0e-6,
                    "{label}[{index}] actual={actual:.8e} expected={expected:.8e} abs={abs:.3e}"
                );
            }
        };

        let m0_grad_mod = (0..nodes * 3 * conv1_in_channels)
            .map(|i| (i as f32 * 0.041 + 0.29).sin() * 0.4)
            .collect::<Vec<_>>();
        let mut expected_input = base_grad_input.clone();
        let mut expected_radial = base_grad_radial.clone();
        for node in 0..nodes {
            let in_base = node * input_node_stride;
            let rad_base = node * radial_node_stride;
            let blk_base = node * 3 * conv1_in_channels;
            for ch in 0..conv1_in_channels {
                let g0 = m0_grad_mod[blk_base + ch];
                expected_input[in_base + ch] = g0 * radial[rad_base + ch];
                expected_radial[rad_base + ch] = g0 * input[in_base + ch];

                let g1 = m0_grad_mod[blk_base + conv1_in_channels + ch];
                expected_input[in_base + 2 * conv1_in_channels + ch] =
                    g1 * radial[rad_base + conv1_in_channels + ch];
                expected_radial[rad_base + conv1_in_channels + ch] =
                    g1 * input[in_base + 2 * conv1_in_channels + ch];

                let g2 = m0_grad_mod[blk_base + 2 * conv1_in_channels + ch];
                expected_input[in_base + 6 * conv1_in_channels + ch] =
                    g2 * radial[rad_base + 2 * conv1_in_channels + ch];
                expected_radial[rad_base + 2 * conv1_in_channels + ch] =
                    g2 * input[in_base + 6 * conv1_in_channels + ch];
            }
        }
        let mut actual_input = base_grad_input.clone();
        let mut actual_radial = base_grad_radial.clone();
        assert!(uma_so2_m0_radial_vjp_sve_f32(
            nodes,
            conv1_in_channels,
            input_node_stride,
            radial_node_stride,
            &m0_grad_mod,
            &input,
            &radial,
            &mut actual_input,
            &mut actual_radial,
        ));
        close(&actual_input, &expected_input, "m0_grad_input");
        close(&actual_radial, &expected_radial, "m0_grad_radial");

        let order1_offset = 3 * conv1_in_channels;
        let order1_mod = (0..nodes * 4 * conv1_in_channels)
            .map(|i| (i as f32 * 0.037 + 0.31).sin() * 0.35)
            .collect::<Vec<_>>();
        let mut expected_input = base_grad_input.clone();
        let mut expected_radial = base_grad_radial.clone();
        for node in 0..nodes {
            let in_base = node * input_node_stride;
            let rad_base = node * radial_node_stride + order1_offset;
            let blk_base = node * 4 * conv1_in_channels;
            for ch in 0..conv1_in_channels {
                let r0 = radial[rad_base + ch];
                let r1 = radial[rad_base + conv1_in_channels + ch];
                let g0 = order1_mod[blk_base + ch];
                let g1 = order1_mod[blk_base + conv1_in_channels + ch];
                let g2 = order1_mod[blk_base + 2 * conv1_in_channels + ch];
                let g3 = order1_mod[blk_base + 3 * conv1_in_channels + ch];
                expected_input[in_base + 3 * conv1_in_channels + ch] = g0 * r0;
                expected_input[in_base + 7 * conv1_in_channels + ch] = g1 * r1;
                expected_input[in_base + conv1_in_channels + ch] = g2 * r0;
                expected_input[in_base + 5 * conv1_in_channels + ch] = g3 * r1;
                expected_radial[rad_base + ch] = g0 * input[in_base + 3 * conv1_in_channels + ch]
                    + g2 * input[in_base + conv1_in_channels + ch];
                expected_radial[rad_base + conv1_in_channels + ch] = g1
                    * input[in_base + 7 * conv1_in_channels + ch]
                    + g3 * input[in_base + 5 * conv1_in_channels + ch];
            }
        }
        let mut actual_input = base_grad_input.clone();
        let mut actual_radial = base_grad_radial.clone();
        assert!(uma_so2_order1_radial_vjp_sve_ptr_f32(
            nodes,
            conv1_in_channels,
            input_node_stride,
            radial_node_stride,
            order1_offset,
            &order1_mod,
            &input,
            &radial,
            actual_input.as_mut_ptr() as usize,
            actual_input.len(),
            actual_radial.as_mut_ptr() as usize,
            actual_radial.len(),
        ));
        close(&actual_input, &expected_input, "order1_grad_input");
        close(&actual_radial, &expected_radial, "order1_grad_radial");

        let order2_offset = order1_offset + 2 * conv1_in_channels;
        let order2_mod = (0..nodes * 2 * conv1_in_channels)
            .map(|i| (i as f32 * 0.029 + 0.41).cos() * 0.3)
            .collect::<Vec<_>>();
        let mut expected_input = base_grad_input.clone();
        let mut expected_radial = base_grad_radial.clone();
        for node in 0..nodes {
            let in_base = node * input_node_stride;
            let rad_base = node * radial_node_stride + order2_offset;
            let blk_base = node * 2 * conv1_in_channels;
            for ch in 0..conv1_in_channels {
                let r0 = radial[rad_base + ch];
                let g0 = order2_mod[blk_base + ch];
                let g1 = order2_mod[blk_base + conv1_in_channels + ch];
                expected_input[in_base + 8 * conv1_in_channels + ch] = g0 * r0;
                expected_input[in_base + 4 * conv1_in_channels + ch] = g1 * r0;
                expected_radial[rad_base + ch] = g0 * input[in_base + 8 * conv1_in_channels + ch]
                    + g1 * input[in_base + 4 * conv1_in_channels + ch];
            }
        }
        let mut actual_input = base_grad_input;
        let mut actual_radial = base_grad_radial;
        assert!(uma_so2_order2_radial_vjp_sve_ptr_f32(
            nodes,
            conv1_in_channels,
            input_node_stride,
            radial_node_stride,
            order2_offset,
            &order2_mod,
            &input,
            &radial,
            actual_input.as_mut_ptr() as usize,
            actual_input.len(),
            actual_radial.as_mut_ptr() as usize,
            actual_radial.len(),
        ));
        close(&actual_input, &expected_input, "order2_grad_input");
        close(&actual_radial, &expected_radial, "order2_grad_radial");
    }

